export const COACH_CAPTIONS: Record<string, Record<string, string>> = {
  es: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Bien — Scotch Gambit. Empieza como una apertura abierta de verdad: e4, e5, caballos fuera, y las Blancas golpean el centro con d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Cuando las Negras toman en d4, las Blancas pueden dejar el peón y plantar el alfil en c4. Ese es el gambito: desarrollar rápido, apuntar a f7 y presionar a las Negras antes de que ordenen la posición.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "La familia Scotch debe su nombre a aquellas partidas por correspondencia Edinburgh–London de los años 1820. A los aficionados les sigue gustando esta línea porque el tablero se abre y los planes son concretos, no un largo ahogo silencioso.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Coge tu té. Practica conmigo las jugadas de libro: te mantendré en el verdadero camino del Scotch Gambit.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Muy bien — bienvenido a la Línea 1. Professor Potato Pie, a tu servicio.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "En este pack hemos destilado el gambito en diez líneas elegidas con cuidado.",
    "10 lines from Opening Lab.":
      "10 líneas de Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Apréndelas y no solo sobrevivirás a la teoría. Devolverás las jugadas correctas con confianza, mantendrás el equilibrio y seguirás bien metido en la partida.",
    "You get 10 lines from Opening Lab.":
      "Tienes 10 líneas de Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Cuando las Negras fallan, aprenderás a ver por qué la jugada es mala, elegir la continuación precisa, convertir el error en una ventaja clara y, a veces, en un jaque mate exquisito.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Naturalmente, las Negras tienen más de diez formas de jugar. Tómalo como un manual breve, no como una enciclopedia: la lógica de las jugadas, no solo una secuencia para memorizar.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Completa el pack y el Scotch Gambit te resultará familiar cada vez que aparezca. Reconocerás los hitos, entenderás los planes y tendrás una base firme para seguir estudiando.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Disfrútalo. Tómate tu tiempo, recorre cada línea, y nos vemos en el tablero.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Muy bien, ahora las trampas de apertura. Estas líneas son muy divertidas y, a veces, pillan a un rival desprevenido por completo. Solo por eso merece la pena conocerlas.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Pero hay un punto más serio. Estudiar trampas enseña a reconocer las señales de aviso, así que es mucho menos probable que caigas tú en una.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Recorre cada línea, capta la idea y disfruta de los pequeños mecanismos tácticos, tan elegantes.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Úsalas con criterio, entiéndelas de verdad y, cuando surja la ocasión, deja que la precisión haga el trabajo.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Prueba, pásalo bien, y ahora creo que toca un pastel de patata. Disfruta.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Muy bien, bienvenido a la Línea 1. Esto es Legal's Mate, llamado así por Monsieur de Légal, un jugador francés del siglo XVIII.",
    "White opens with the king's pawn, e4.": "Las Blancas abren con el peón de rey, e4.",
    "Black answers symmetrically with e5.": "Las Negras responden de forma simétrica con e5.",
    "Knight to f3 attacks that pawn.": "Caballo a f3 ataca ese peón.",
    "Black defends it with d6, which is the Philidor Defence.":
      "Las Negras lo defienden con d6, que es la Defensa Philidor.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "El alfil de las Blancas llega a c4 y mira la débil casilla f7.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "El alfil de las Negras va a g4 y clava el caballo contra la dama.",
    "White calmly develops, knight to c3.": "Las Blancas desarrollan con calma, caballo a c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "Las Negras juegan g6. Es una jugada lenta, y ahora la trampa está lista.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "¡El caballo toma en e5! Ese caballo solo estaba clavado contra la dama, no contra el rey, así que puede moverse con toda libertad.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "Las Negras no resisten y toman la dama en d1. Es la captura codiciosa, y es fatal.",
    "Bishop takes f7, check!": "El alfil toma en f7, ¡jaque!",
    "The king has only one square to go to, e7.": "Al rey solo le queda una casilla, e7.",
    "Knight to d5, and that's checkmate.": "Caballo a d5, y eso es jaque mate.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "Dos caballos y un alfil han vencido a todo el ejército negro. La dama, las torres y el alfil en d1 de las Negras siguen en el tablero, y ninguno puede ayudar.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Recuerda: si te ofrecen una dama gratis tan pronto, mira bien alrededor antes de tomarla.",
    "Now over to you. Practise it until your knights know the way.":
      "Ahora te toca a ti. Practícalo hasta que tus caballos sepan el camino.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "Ah, hola otra vez. Professor Potato Pie, té en mano. Hoy miramos la Defensa Caro-Kann, una apertura muy resistente, de excelentes modales y con unos codos sorprendentemente afilados.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "Empieza con e4 c6, y toma su nombre de Horatio Caro y Marcus Kann, dos jugadores del siglo XIX cuyo trabajo analítico dio identidad a esta defensa venerable.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "La premisa estratégica es admirablemente económica. Las Negras preparan d5, desafiando el centro de las Blancas de inmediato, y dejan libre el alfil de casillas claras en lugar de encerrarlo tras la cadena de peones.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "La Caro-Kann es sólida, paciente y sana de estructura, pero no confundas la calma con pasividad. Bajo ese exterior respetable hay una buena colección de contragolpes, sobre todo si las Blancas se pasan de ambiciosas.",
    "You'll study 10 lines from Opening Lab.":
      "Estudiarás 10 líneas de Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "Estas son 10 líneas de Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "En Practice daré pistas donde las necesites. En Test la ayuda desaparece: solo estás tú, la posición y tu criterio.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Cada línea termina donde acaba la línea de libro preparada. Después no hay continuación contra el ordenador.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "El objetivo no es seguir jugando sin rumbo, sino absorber las jugadas, comprender las ideas y reconocer los patrones cuando vuelvas al tablero.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Muy bien. El té, en su sitio; las piezas, listas. Empecemos.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Muy bien, bienvenido a la Línea 1, la Variante del Avance. Las Blancas reclaman el centro con e4.",
    "We answer c6, preparing the thematic d5 advance.":
      "Respondemos c6, preparando el avance temático d5.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "Las Blancas forman un centro amplio con d4, y lo desafiamos enseguida con d5.",
    "White pushes on to e5, gaining space.": "Las Blancas avanzan a e5 y ganan espacio.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Antes de cerrar la cadena de peones con e6, nuestro alfil escapa a f5. Eso, en esencia, es el primer buen orden de la Caro-Kann: el alfil sale antes de que se cierre la puerta.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "Sigue caballo f3, luego e6. Con el alfil ya desarrollado, e6 es del todo cómodo.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "Las Blancas eligen el planteamiento tranquilo y sensato de alfil a e2, un sistema popularizado por el gran maestro inglés Nigel Short.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "Golpeamos con c5, atacando la base de la cadena de peones blanca en d4.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "Las Blancas enrocan, y caballo c6 suma otra pieza a la presión.",
    "White reinforces d4 with c3.": "Las Blancas refuerzan d4 con c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "Cambiamos peones en d4, abrimos la columna c y damos a nuestro contrajuego una vía útil.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "El otro caballo se desarrolla a e7, camino de f5, donde puede volver a cuestionar d4.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "Las Blancas juegan caballo c3, y nuestro alfil aplica la clavada desde g4.",
    "White answers with knight e1, breaking the pin.":
      "Las Blancas responden con caballo e1 y rompen la clavada.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Por eso cambiamos el útil alfil blanco de e2. Recapturar con el caballo mantiene d4 bien defendido.",
    "Our knight settles on f5, still eyeing d4.":
      "Nuestro caballo se instala en f5, todavía mirando d4.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "Las Blancas lo protegen con alfil e3, y nosotros desarrollamos con calma el alfil a e7, listos para enrocar.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "El resultado es una posición igualada con un plan coherente. Mantén la presión sobre d4 y usa la columna c con intención.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "No hacen falta fuegos artificiales: solo estructura sana, presión paciente y cada pieza bien empleada.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "Te toca a ti. Repite la línea hasta que las jugadas se sientan menos como memoria y más como buen criterio.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Muy bien, aquí Professor Potato Pie, té en la mano, y hoy echamos un vistazo breve al sistema de Londres.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "La apertura quedó muy ligada al gran Torneo de Londres de 1922, donde esta disposición fiable atrajo más atención.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Bien, normalmente empieza con peón a d4, caballo a f3 y alfil a f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Luego viene peón a e3, peón a c3, caballo a d2, alfil a d3 y el enroque corto.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "El orden exacto puede cambiar, pero esa formación familiar es el corazón del sistema de Londres.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "Es una apertura sólida y sensata, jugada tanto por jugadores de club como por grandes maestros.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Bien, disfruta al familiarizarte más con el sistema de Londres y veamos cómo encajan las piezas.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Muy bien, echemos un vistazo a la primera línea de nuestro pack de aprendizaje del Londres.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Esta es la pinza de Londres, tranquila al principio, pero hay método en cada jugada.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Jugamos peón a d4 y las negras responden peón a d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Alfil a f4, caballo a f6, peón a e3 y las negras golpean con peón a c5.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Construimos la pirámide familiar con peón a c3, las negras desarrollan el caballo a c6.",
    "Knight to d2 and black plays pawn to e6.": "Caballo a d2 y las negras juegan peón a e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "Nuestro otro caballo llega a f3, mientras el alfil negro llega a d6.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Retiramos nuestro alfil a g3, manteniéndolo útil y seguro.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "Las negras enrocan en el flanco de rey, colocamos nuestro otro alfil en d3, las negras juegan peón a b6 y ahora plantamos el caballo en e5, un espléndido puesto central.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Alfil a b7, enrocamos en el flanco de rey, las negras colocan la dama en c7 y completamos la pinza con peón a f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "Ahí está, una posición compacta de Londres con el centro firmemente vigilado y nuestras piezas empezando a mirar hacia el flanco de rey.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Repítela hasta que tu mano conozca la ruta y tu rival se pregunte cuándo la apertura tranquila se convirtió en un ataque.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Muy bien, aquí Professor Potato Pie, té en la mano, y hoy nos encontramos con una de las aperturas más antiguas y elegantes del ajedrez, la partida italiana.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "Sus ideas las estudiaron los maestros italianos hace más de cuatro siglos, y la apertura sigue apareciendo hoy en todos los niveles del ajedrez.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "Las blancas empiezan con peón a e4, y las negras responden peón a e5, caballo a f3, caballo a c6, y luego alfil a c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "Ese alfil apunta hacia f7, la delicada casilla junto al rey negro.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "Desde aquí, las negras suelen responder con alfil a c5, entrando en el Giuoco Piano, o caballo a f6, y llegan a la defensa de los dos caballos.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "La partida italiana es clásica, viva, y se apoya en el desarrollo natural, el control del centro y las posibilidades de ataque.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Bien, disfruta al familiarizarte más con la partida italiana y veamos adónde nos lleva ese alfil en c4.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Muy bien, bienvenido a la Línea 1 de nuestro pack de aprendizaje de la partida italiana.",
    "This is the quieter Italian.": "Esta es la italiana más tranquila.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "No hace falta prender fuego a las cortinas cuando una preparación cuidadosa basta.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Empezamos con peón a e4, y las negras responden peón a e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "Caballo a f3, caballo a c6, alfil a c4, y las negras desarrollan el alfil a c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "Los dos alfiles ocupan sus puestos clásicos y vigilan el centro.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Jugamos peón a c3, preparando un futuro peón a d4.",
    "Black develops knight to f6 and places pressure on e4.":
      "Las negras desarrollan el caballo a f6 y presionan e4.",
    "Pawn to d3, pawn to d6.": "Peón a d3, peón a d6.",
    "Both sides secure the centre before making any grand declarations.":
      "Ambos bandos aseguran el centro antes de hacer grandes declaraciones.",
    "We castle king side.": "Enrocamos en el flanco de rey.",
    "Black plays pawn to a6.": "Las negras juegan peón a a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Respondemos peón a a4, ganando un poco de espacio en el flanco de dama, y el alfil se instala en a7.",
    "Knight to d2 and black castles king side.":
      "Caballo a d2 y las negras enrocan en el flanco de rey.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Jugamos peón a h3, evitando que un alfil se vuelva molesto en g4, y dando a nuestro rey una casilla útil para respirar.",
    "Black's knight moves to e7.": "El caballo negro se mueve a e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "Torre a e1 refuerza e4, y el caballo sigue hasta g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "Ahí estamos, una posición italiana sólida, con cada pieza preparándose para un trabajo útil.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Sigue desarrollando, vigila el centro y estate listo para la ruptura d4 cuando llegue el momento.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Repite la línea hasta que las jugadas se sientan tan naturales como poner la tetera.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Muy bien, aquí Professor Potato Pie, con el té bien hecho, y hoy presentamos una de las grandes aperturas clásicas, el gambito de dama.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "La apertura aparece en escritos de ajedrez desde finales del siglo XV, y generaciones de jugadores distinguidos la han usado para disputar el centro.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "Las blancas empiezan con peón a d4, y las negras responden peón a d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Luego las blancas juegan peón a c4, desafiando el peón central negro y ofreciendo el peón de c.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "Se llama gambito, aunque las blancas suelen recuperar el peón si las negras lo aceptan,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Así que esto es menos una donación temeraria y más una invitación estratégica, servida con cortesía pero con segundas intenciones.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "A partir de aquí, las negras pueden aceptar el peón o rechazarlo y mantener un centro sólido.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Bien, disfruta al familiarizarte más con el gambito de dama y veamos qué puede persuadir a hacer a las negras ese pequeño peón de c tan aventurero.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Muy bien, bienvenido a la Línea 1 de nuestro pack de aprendizaje del gambito de dama.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "Esto es ajedrez clásico de verdad: cimientos firmes, desarrollo paciente y ningún mueble volando por la habitación.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Empezamos con peón a d4 y las negras responden peón a d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Peón a c4 desafía el centro y las negras contestan peón a e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "Eso es el gambito de dama rechazado. Las negras sostienen el peón de d5 en lugar de aceptar nuestra oferta.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "Caballo a c3, caballo a f6, alfil a g5 crea la clavada y las negras desarrollan con calma el alfil a e7.",
    "We play pawn to e3 and black castles kingside.":
      "Jugamos peón a e3 y las negras enrocan en el flanco de rey.",
    "Knight to f3, knight to d7.": "Caballo a f3, caballo a d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Torre a c1 coloca la torre en la columna c mientras las negras juegan peón a c6 y refuerzan la estructura central.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Alfil a d3 y las negras resuelven ahora la tensión con peón de d5 toma c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "Nuestro alfil toma c4, recuperando el peón con desarrollo.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "El caballo negro va a d5 y ocupa una casilla central fuerte.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Cambiamos con alfil toma e7 y la dama negra recaptura en e7.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "Ahí está, una posición equilibrada del gambito de dama, con desarrollo sensato y todavía mucho juego en el centro.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Aprende la estructura, entiende los cambios y deja que la posición te diga cuándo es hora de presionar.",
    "Very civilised and quietly ambitious.": "Muy civilizado y discretamente ambicioso.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Muy bien, aquí Professor Potato Pie, te pongo a punto, y hoy nos encontramos con la defensa francesa: ¿cuáles son las respuestas más resistentes de las negras al peón de rey?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "Las blancas empiezan con peón a e4, y nosotros respondemos peón a e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "Las blancas ganan más espacio con peón a d4 y nosotros golpeamos de inmediato con peón a d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "La apertura tomó su nombre de una partida por correspondencia entre Londres y París en 1834, cuando el equipo de París empleó la defensa con éxito.",
    "Its character is patient, but hardly passive.": "Su carácter es paciente, pero nada pasivo.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "Las negras construyen una sólida cadena de peones, invitan a las blancas a declarar sus intenciones y luego desafían el centro con jugadas como peón a c5 y, cuando llega el momento, peón a f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "Nuestro alfil de casillas claras puede exigir un poco de diplomacia, pero eso forma parte de la sutil arquitectura de la apertura.",
    "Solid, combative and rich in counterplay.": "Sólida, combativa y rica en contrajuego.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "La francesa no precipita la discusión: la gana con una pregunta precisa cada vez.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "Así que acomódate, no pierdas de vista las rupturas de peón y disfruta al familiarizarte más con la defensa francesa.",
    "Right then, welcome to Line 1 of our French defence learning pack.":
      "Muy bien, bienvenido a la Línea 1 de nuestro paquete de aprendizaje de la defensa francesa.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "El título correcto es la defensa francesa, variante Winawer, línea principal posicional del avance, y la estamos practicando desde el lado de las negras.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "Las blancas empiezan con peón a e4, nosotros respondemos peón a e6, las blancas toman el centro con peón a d4 y nosotros lo desafiamos con peón a d5.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "Caballo a c3, luego alfil a b4: eso anuncia la Winawer.",
    "We pin the knight and ask white how ambitious they're feeling.": "Clavamos el caballo y preguntamos a las blancas cuán ambiciosas se sienten.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "Las blancas avanzan peón a e5 y nosotros contestamos de inmediato con peón a c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "Las blancas juegan peón a a3, desafiando a nuestro alfil, así que alfil toma c3, jaque.",
    "White recaptures with the b-pawn to c3.": "Las blancas recapturan con el peón de b hacia c3.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "Las blancas han ganado la pareja de alfiles y un centro amplio, pero han aceptado peones de c doblados a cambio.",
    "That trade-and-balance is the very grammar of the Winawer.": "Ese intercambio y equilibrio es la gramática misma de la Winawer.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.":
      "Desarrollamos el caballo a e7, las blancas desarrollan el caballo a f3 y nuestro alfil va a d7.",
    "White plays pawn to a4, restraining queen side expansion.": "Las blancas juegan peón a a4, frenando la expansión del flanco de dama.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Respondemos dama a a5, aplicando presión sobre c3 y ayudando a despejar el camino para el enroque en el flanco de dama.",
    "Bishop to d2 and our knight develops to c6.": "Alfil a d2 y nuestro caballo se desarrolla a c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "Las blancas colocan el alfil en d3, mirando con cierta descortesía hacia h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "Avanzamos peón a c4, ganando espacio y enviando ese alfil de vuelta a e2.",
    "Now comes pawn to f6, the characteristic French lever.": "Ahora llega peón a f6, la palanca característica de la francesa.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.":
      "No nos limitamos a admirar el centro de las blancas: le pedimos que presente sus credenciales.",
    "White castles king side, black castles queen side.": "Las blancas enrocan en el flanco de rey y las negras enrocan en el flanco de dama.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "Los reyes quedan ahora en flancos opuestos, la posición está espléndidamente desequilibrada y el plan de las negras está claro.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "Desafía el peón de e5, abre líneas útiles y genera actividad en el flanco de dama con un propósito claro.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Esa es la Winawer posicional: sólida en su construcción, combativa en su intención y con una cantidad considerable de electricidad oculta.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.":
      "Tu turno: practícala hasta que el orden de jugadas se sienta menos como memoria y más como sentido común.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Justo ahí, mis amores. Big Red aquí. Y hoy miramos como es debido la Ruy Lopez,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "también conocida como la apertura española. Hay historia en esta. Toma su nombre",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "de Ruy Lopez de Segura, un sacerdote español y escritor de ajedrez que estudió la apertura en",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "el siglo XVI. Las blancas empiezan con peón a e4. Las negras responden peón a e5. Caballo a f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "ataca ese peón y las negras lo defienden con caballo a c6. Luego viene el alfil a b5. Y ahí",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "lo tienes. La Ruy Lopez. El alfil no gana de inmediato el peón de e5. Está aplicando",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "presión al caballo que lo guarda, y deja a las negras un problema callado pero persistente.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "De este elegante comienzo crece una de las familias de aperturas más grandes del ajedrez.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Algunas líneas son tranquilas y de maniobra; otras pueden animarse antes de que hayas tenido tiempo de asentar",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "el té. Es clásica, sutil y llena de ideas estratégicas de verdad. Vieja, digna y todavía",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "llena de posibilidades. Un poco como el propio Londres. Así que vigila el centro,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "cuida tus piezas y disfruta familiarizarte más con la Ruy Lopez. Big Red te verá por aquí.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "Muy bien, mis amores: Big Red vuelve al tablero y esta es la línea 1 de nuestro pack de la Ruy Lopez, la Defensa Morphy, variante cerrada Breyer.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Jugamos con las piezas blancas y esto es una auténtica obra maestra estratégica.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "Las blancas empiezan con peón a e4, las negras responden peón a e5, Nf3 ataca el peón y las negras lo defienden con Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 y la Ruy Lopez está en el tablero. Las negras juegan peón a a6 y anuncian la Defensa Morphy",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "y le hacen a nuestro alfil una pregunta muy directa. Retiramos el alfil a a4. Las negras desarrollan Nf6,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "enrocamos en el flanco de rey y las negras desarrollan el alfil a e7. La torre a e1 refuerza nuestro peón de e4",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "y coloca la torre frente al rey negro. Las negras se expanden con peón a b5, así que nuestro alfil se asienta",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "en b3. El peón a d6 da al centro negro una base firme. Jugamos peón a c3,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "preparando el gran avance central, peón a d4. Las negras enrocan en el flanco de rey. Ahora peón a h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "una jugada pequeña y útil que mantiene lejos de g4 a un alfil o un caballo y da aire a nuestro rey.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Luego llega la jugada que hace inconfundible la Breyer. Las negras retiran el caballo a b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "Parece que el caballo ha olvidado por qué salió, pero nada de eso. Esto es estratégico",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "reciclaje del más alto nivel. Golpeamos con peón a d4 y establecemos un centro magnífico. Las negras",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "reencaminan ese caballo a d7, donde apoya e5 y libera el peón de c para el contrajuego futuro.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "Nuestro caballo de dama se desarrolla a d2. El alfil negro va a b7 y apunta a e4. El alfil",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "a c2 conserva nuestro valioso alfil español y apunta hacia el flanco de rey. Las negras colocan la",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "torre en e8, sumando más apoyo al peón de e5. Por fin, nuestro caballo se desliza a f1. Ese caballo",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "tiene un itinerario espléndido. Desde f1 puede viajar a g3, aumentando la presión sobre f5 y ayudando",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "a que el ataque en el flanco de rey cobre impulso. Esa es la Breyer cerrada. Paciente, sofisticada y",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "absolutamente rebosante de vida y energía. Las blancas poseen el espacio central. Las negras han construido una posición compacta",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "y preparan el contragolpe. Juégala con convicción. Disfruta cada maniobra",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "y recuerda: las jugadas quietas no están esperando. Están cargando el resorte.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "Te toca: practícala hasta que ese viaje del caballo de b1 a d2 y luego a f1 se sienta tan natural como encontrar",
    "your way around London.":
      "el camino por Londres.",
    "Right then, the Sicilian Defence for Black.":
      "Muy bien, la defensa siciliana para las negras.",
    "White starts with 1. e4, claiming the centre.":
      "Las blancas empiezan con un punto e4 y reclaman el centro.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "Las negras responden un punto c5, golpeando de lado en vez de copiar a las blancas directamente.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "La idea es desafiar las ambiciones centrales de las blancas, desarrollarse con actividad y crear contrajuego desde el principio.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Una ruta habitual es 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "Ahí lo tienes: una defensa aguda y flexible, con mucho mordiente.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Muy bien, bienvenido a la línea 1 de la Sicilian, la Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "Esta es una de las respuestas más ambiciosas de las negras al peón a e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "Las blancas abren con peón a e4, y las negras golpean enseguida con peón a c5.",
    "White develops knight to f3.":
      "Las blancas desarrollan el caballo a f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "Las negras juegan peón a d6, y las blancas abren el centro con peón a d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "Las negras toman en d4 con el peón de c, las blancas recapturan con caballo toma d4.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "Las negras desarrollan el caballo a f6, y las blancas traen el otro caballo a c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Ahora llega la famosa jugada Najdorf, peón a a6, una jugada flexible y pequeña con mucho veneno detrás.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "Las negras mantienen la posición adaptable y se preparan para expandirse en el flanco de dama.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "La primera parte de la línea es peón a e4, peón a c5, caballo a f3, peón a d6, peón a d4, peón toma d4, caballo toma d4, caballo a f6, caballo a c3, peón a a6, alfil a e3, peón a e5, caballo a b3, alfil a e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "Ahora la línea sigue, peón a f3, alfil a e7, dama a d2, enroque corto, enroque largo, caballo a bd7, peón a g4, peón a b5.",
    "White prepares a kingside assault with pawn to f3.":
      "Las blancas preparan un asalto en el flanco de rey con peón a f3.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "Las negras desarrollan con calma el alfil a e7, y luego las blancas traen la dama a d2.",
    "Black castles kingside and White castles queenside.":
      "Las negras enrocan en corto y las blancas enrocan en largo.",
    "Now the battle lines are drawn.":
      "Ahora las líneas de batalla están trazadas.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "Las negras desarrollan el caballo a bd7 y las blancas empiezan la famosa tormenta de peones con peón a g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "Las negras responden con peón a b5 y ahí está, la Najdorf ha cobrado vida.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "Las blancas reúnen fuerzas en el flanco de rey, las negras avanzan por el flanco de dama, y ambos preparan algo bastante peligroso.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Muy bien, sigue las jugadas de cerca, mantén la atención y disfruta esta tremenda línea Sicilian.",
  },
  zh: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "好——Scotch Gambit。它像一盘真正的开放性开局：e4，e5，马出来，然后白方用 d4 冲击中心。",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "当黑方在 d4 吃子时，白方可以不吃回这个兵，而把象放到 c4。这就是弃兵——尽快出子，瞄准 f7，在黑方收拾局面之前施加压力。",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "Scotch 这一族得名于十九世纪二十年代那些 Edinburgh–London 的通讯赛。爱好者仍然喜欢这条线路，因为棋盘会打开，计划很具体，而不是漫长安静的挤压。",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "拿好你的茶。和我一起练习书谱着法——我会让你走在真正的 Scotch Gambit 路上。",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "好——欢迎来到第 1 线。Professor Potato Pie，为你效劳。",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "在这个学习棋包里，我们把弃兵提炼成十条精心挑选的线路。",
    "10 lines from Opening Lab.":
      "来自 Opening Lab 的 10 条线路。",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "学会它们，你就不只是在理论里求生。你会自信地回出正确着法，保持均势，稳稳留在局中。",
    "You get 10 lines from Opening Lab.":
      "你得到来自 Opening Lab 的 10 条线路。",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "当黑方走错时，你会学会看出这一着为什么有毛病，选出精确的续着，把错误变成明显优势，有时还变成相当精妙的将死。",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "当然，黑方的下法不止十种。把这当作一份紧凑的小册子，而不是一本穷尽的百科——要的是着法背后的道理，而不只是一串要背的次序。",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "练完这个棋包，Scotch Gambit 一出现你就会觉得眼熟。你会认出路标，理解计划，并有一个扎实的立足点，把学习继续下去。",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "好好享受。别着急，把每条线路走一遍，棋盘上见。",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "好，现在来看开局陷阱。这些线路很好玩，有时能让没有防备的对手完全措手不及。单凭这一点就值得知道。",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "但还有更要紧的一点。研究陷阱能让你认出警告信号，这样你自己误入的可能就小得多。",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "把每条线路走一遍，抓住它的想法，并享受这些精巧的小战术机关。",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "有判断地使用它们，真正理解它们，机会来临时，让精确来完成工作。",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "试一试，找点乐趣，现在我想该吃一块土豆派了。请享用。",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "好，欢迎来到第 1 线。这是 Legal's Mate，得名于 Monsieur de Légal，一位十八世纪的法国棋手。",
    "White opens with the king's pawn, e4.": "白方用王前兵开局，e4。",
    "Black answers symmetrically with e5.": "黑方用 e5 对称应答。",
    "Knight to f3 attacks that pawn.": "马到 f3，攻击那只兵。",
    "Black defends it with d6, which is the Philidor Defence.":
      "黑方用 d6 防守，这就是 Philidor 防御。",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "白方的象来到 c4，盯着弱小的 f7 格。",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "黑方的象走到 g4，把马牵制在后上。",
    "White calmly develops, knight to c3.": "白方从容出子，马到 c3。",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "黑方走 g6。这是缓慢的一着，陷阱现在准备好了。",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "马吃 e5！那只马只是被牵制在后上，不是牵制在王上，所以完全可以走。",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "黑方抵不住，在 d1 吃掉后。这是贪吃，而且是致命的。",
    "Bishop takes f7, check!": "象吃 f7，将军！",
    "The king has only one square to go to, e7.": "王只剩一格可去，e7。",
    "Knight to d5, and that's checkmate.": "马到 d5，这就是将死。",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "两匹马和一只象打败了整个黑军。黑方的后、车和 d1 的象都还在棋盘上，却谁也帮不上忙。",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "所以记住：这么早有人白送一只后，吃之前先好好看一看周围。",
    "Now over to you. Practise it until your knights know the way.":
      "现在交给你。练习到你的马自己认得路。",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "啊，又见面了。Professor Potato Pie，手里端着茶。今天我们来看 Caro-Kann 防御，一种非常有韧性的开局，举止得体，肘部却出奇地锋利。",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "它以 e4 c6 开始，名称来自 Horatio Caro 和 Marcus Kann，两位十九世纪棋手的分析工作给了这门可敬的防御自己的身份。",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "战略前提十分节省。黑方准备 d5，立刻挑战白方中心，同时让白格象自由，而不是把它关在兵链后面。",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Caro-Kann 扎实、耐心、结构健康，但不要把从容误当成被动。体面的外表下有一套漂亮的反击，尤其是当白方过于雄心勃勃的时候。",
    "You'll study 10 lines from Opening Lab.":
      "你将学习来自 Opening Lab 的 10 条线路。",
    "These are 10 lines from Opening Lab.":
      "这些是来自 Opening Lab 的 10 条线路。",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "在 Practice 里，你需要提示时我会给。在 Test 里，帮助消失，只剩下你、局面和你的判断。",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "每条线路在准备好的书谱线路结束处停止。之后没有对电脑的续战。",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "目的不是漫无目的地接着下，而是吸收着法、理解想法，并在你回到棋盘前时认出这些模式。",
    "Right then. Tea settled, pieces ready. Let's begin.": "好。茶放好了，棋子就绪。我们开始。",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "好，欢迎来到第 1 线，前进变例。白方用 e4 占领中心。",
    "We answer c6, preparing the thematic d5 advance.": "我们应 c6，准备主题性的 d5 挺进。",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "白方用 d4 建立宽阔的中心，我们立刻用 d5 挑战它。",
    "White pushes on to e5, gaining space.": "白方再进到 e5，赢得空间。",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "在用 e6 封闭兵链之前，我们的象先逃到 f5。这其实就是 Caro-Kann 的第一件好家务：门关上之前，先把象放出来。",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "接着是马 f3，然后 e6。象已经安全出动，e6 现在完全舒服。",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "白方选择安静而合理的象 e2 布局，这是英国特级大师 Nigel Short 推广的体系。",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "我们用 c5 打击，攻击白方兵链在 d4 的底座。",
    "White castles, and knight c6 adds another piece to the pressure.":
      "白方王车易位，马 c6 再添一子到压力上。",
    "White reinforces d4 with c3.": "白方用 c3 加固 d4。",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "我们在 d4 兑兵，打开 c 线，给我们的反击一条有用的通道。",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "另一只马出到 e7，前往 f5，到了那里可以再次质疑 d4。",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "白方走马 c3，我们的象从 g4 实施牵制。",
    "White answers with knight e1, breaking the pin.": "白方用马 e1 应答，解开牵制。",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "于是我们兑换白方在 e2 那只有用的象。用马吃回，d4 仍然守得很稳。",
    "Our knight settles on f5, still eyeing d4.": "我们的马落到 f5，仍然盯着 d4。",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "白方用象 e3 保护它，我们从容地把象出到 e7，准备王车易位。",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "结果是均势，计划清楚。保持对 d4 的压力，并有目的地使用 c 线。",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "不需要烟火，只要健康的结构、耐心的压力，以及每只棋子都在干正事。",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "交给你了。把这条线路练到这些着法更像常识，而不像记忆。",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "好，我是 Professor Potato Pie，手里端着茶，今天我们简要看一看伦敦体系。",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "这种开局与1922年的伦敦大赛密切相关，当时这套可靠的布置引起了更广泛的注意。",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "对，通常从兵到 d4、马到 f3、象到 f4 开始。",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "接着是兵到 e3、兵到 c3、马到 d2、象到 d3，以及王翼易位。",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "精确的次序可以改变，但那种熟悉的阵型就是伦敦体系的核心。",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "这是一种扎实、明智的开局，俱乐部棋手和特级大师都下过。",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "好，享受进一步熟悉伦敦体系的过程，我们来看看这些棋子如何配合。",
    "Right then, let's have a look at the first line in our London learning pack.":
      "好，我们来看看伦敦学习棋包里的第一条线路。",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "这就是伦敦钳制，开头很安静，但每一步都有章法。",
    "We play pawn to d4 and black answers pawn to d5.": "我们走兵到 d4，黑方应兵到 d5。",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "象到 f4，马到 f6，兵到 e3，黑方以兵到 c5 反击。",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "我们用兵到 c3 搭起熟悉的金字塔，黑方把马发展到 c6。",
    "Knight to d2 and black plays pawn to e6.": "马到 d2，黑方走兵到 e6。",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "我们另一匹马来到 f3，同时黑方的象来到 d6。",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "我们把象退回 g3，让它既有用又安全。",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "黑方王翼易位，我们把另一只象放在 d3，黑方走兵到 b6，现在我们把马扎在 e5，一个出色的中心前哨。",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "象到 b7，我们王翼易位，黑方把后放到 c7，我们用兵到 f4 完成钳制。",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "就是这样，一个紧凑的伦敦局面，中心牢牢在看管之下，我们的棋子开始朝王翼瞥去。",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "把它练到手上认得这条路，让对手纳闷安静的开局何时变成了进攻。",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "好，这里是 Professor Potato Pie，茶在手中，今天我们来认识国际象棋最古老、最优雅的开局之一，意大利开局。",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "它的思想由意大利大师在四个多世纪前研究过，而这开局今天仍出现在各级国际象棋中。",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "白方以兵到 e4 开始，黑方应以兵到 e5，马到 f3，马到 c6，然后象到 c4。",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "那只象指向 f7，黑方王旁边那块脆弱的小格子。",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "从这里起，黑方通常应以象到 c5，进入 Giuoco Piano，或者马到 f6，到达双马防御。",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "意大利开局古典、生动，建立在自然出子、中心控制与进攻可能之上。",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "好，享受进一步熟悉意大利开局的过程，我们来看看 c4 上的那只象会把我们带到哪里。",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "好，欢迎来到意大利开局学习包的第 1 条变例。",
    "This is the quieter Italian.": "这是更安静的意大利开局。",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "仔细准备就够用了，不必把窗帘点着。",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "我们以兵到 e4 开始，黑方应兵到 e5。",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "马到 f3，马到 c6，象到 c4，黑方出象到 c5。",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "两只象都站上经典岗位，警惕地看着中心。",
    "We play pawn to c3, preparing a future pawn to d4.":
      "我们走兵到 c3，为将来的兵到 d4 做准备。",
    "Black develops knight to f6 and places pressure on e4.":
      "黑方出马到 f6，并对 e4 施压。",
    "Pawn to d3, pawn to d6.": "兵到 d3，兵到 d6。",
    "Both sides secure the centre before making any grand declarations.":
      "双方都先稳住中心，再做任何宏大的宣告。",
    "We castle king side.": "我们王翼易位。",
    "Black plays pawn to a6.": "黑方走兵到 a6。",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "我们应兵到 a4，略微扩大后翼空间，象落在 a7。",
    "Knight to d2 and black castles king side.": "马到 d2，黑方王翼易位。",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "我们走兵到 h3，防止一只象在 g4 上变得麻烦，也给我们的王一格有用的透气格。",
    "Black's knight moves to e7.": "黑方的马走到 e7。",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "车到 e1 加固 e4，马继续走到 g6。",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "就是这样，一个稳健的意大利局面，每枚棋子都在为有用的工作做准备。",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "继续出子，盯住中心，时机合适时准备好 d4 突破。",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "把这条变例练到像烧开水壶一样自然。",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "好，我是 Professor Potato Pie，茶已泡好，今天我们介绍一种伟大的古典开局，后翼弃兵。",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "这种开局自十五世纪末就出现在国际象棋文献中，一代代杰出棋手用它争夺中心。",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "白方以兵到 d4 开始，黑方应兵到 d5。",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "然后白方走兵到 c4，挑战黑方的中心兵，并献出 c 兵。",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "它被称为弃兵，不过如果黑方接受，白方通常能把兵夺回，",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "所以这与其说是鲁莽的赠送，不如说是一次策略上的邀请，礼貌奉上，却另有用意。",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "从这里起，黑方可以接受这枚兵，也可以拒绝并保持坚实的中心。",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "好，享受进一步熟悉后翼弃兵的过程，我们来看看那枚爱冒险的小 c 兵能说服黑方做什么。",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "好，欢迎来到后翼弃兵学习棋包的第 1 线。",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "这是真正的古典国际象棋：基础扎实，发展耐心，没有家具飞过房间。",
    "We begin with pawn to d4 and black answers pawn to d5.": "我们从兵到 d4 开始，黑方应兵到 d5。",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "兵到 c4 挑战中心，黑方应以兵到 e6。",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "这就是后翼弃兵拒绝。黑方支撑 d5 兵，而不是接受我们的献兵。",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "马到 c3，马到 f6，象到 g5 形成牵制，黑方从容地把象出到 e7。",
    "We play pawn to e3 and black castles kingside.": "我们走兵到 e3，黑方王翼易位。",
    "Knight to f3, knight to d7.": "马到 f3，马到 d7。",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "车到 c1，把车放在 c 线，同时黑方走兵到 c6，加固中心结构。",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "象到 d3，黑方现在用 d5 兵吃 c4 来解除张力。",
    "Our bishop takes c4 recovering the pawn with development.": "我们的象吃 c4，在出子的同时把兵夺回。",
    "Black's knight moves to d5 and occupies a strong central square.": "黑方的马走到 d5，占据有力的中心格。",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "我们用象吃 e7 进行兑换，黑方的后在 e7 吃回。",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "就是这样，一个均衡的后翼弃兵局面，出子合理，中心仍有不少内容。",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "学会这种结构，理解这些兑换，让局面告诉你何时向前推进。",
    "Very civilised and quietly ambitious.": "非常文明，又安静地抱有雄心。",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "好，这里是 Professor Potato Pie，先让你准备好，今天我们来认识法兰西防御：面对王兵，黑方最坚韧的应着是什么？",
    "White begins with pawn to e4, we answer pawn to e6.": "白方以兵到 e4 开局，我们应以兵到 e6。",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "白方以兵到 d4 争取更多空间，我们立刻以兵到 d5 反击。",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "这个开局得名于 1834 年伦敦与巴黎的一场通讯赛，当时巴黎队成功地运用了这一防御。",
    "Its character is patient, but hardly passive.": "它的性格是耐心的，但绝非被动。",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "黑方建立起稳固的兵链，请白方先表明意图，再用兵到 c5 之类的着法挑战中心，时机成熟时再兵到 f6。",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "我们的白格象也许需要一点外交手腕，但这正是该开局精妙结构的一部分。",
    "Solid, combative and rich in counterplay.": "稳固、好斗，而且富于反击。",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "法兰西防御不急于争辩，它用一个个精确的问题把局面赢下来。",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "所以安下心来，留意兵的突破，享受对法兰西防御越来越熟悉的过程。",
    "Right then, welcome to Line 1 of our French defence learning pack.": "好，欢迎来到我们法兰西防御学习棋包的第 1 线。",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.": "正式名称是法兰西防御 Winawer 变例、进兵的局面型主线，我们从黑方一侧来演练它。",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.": "白方以兵到 e4 开局，我们应以兵到 e6，白方以兵到 d4 占据中心，我们以兵到 d5 挑战它。",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "马到 c3，然后象到 b4，这就宣告了 Winawer。",
    "We pin the knight and ask white how ambitious they're feeling.": "我们牵制这匹马，并问问白方此刻有多雄心勃勃。",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "白方兵进到 e5，我们立刻以兵到 c5 反击。",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "白方走兵到 a3，挑战我们的象，于是象吃 c3，将军。",
    "White recaptures with the b-pawn to c3.": "白方用 b 兵吃回到 c3。",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.": "白方得到了双象和宽阔的中心，但作为交换接受了叠 c 兵。",
    "That trade-and-balance is the very grammar of the Winawer.": "这种兑换与平衡，正是 Winawer 的语法本身。",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.": "我们把马发展到 e7，白方把马发展到 f3，我们的象走到 d7。",
    "White plays pawn to a4, restraining queen side expansion.": "白方走兵到 a4，限制后翼的扩展。",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.": "我们应以后到 a5，对 c3 施压，并帮助为后翼易位清路。",
    "Bishop to d2 and our knight develops to c6.": "象到 d2，我们的马发展到 c6。",
    "White places the bishop on d3, glancing rather impolitely at h7.": "白方把象放到 d3，颇为失礼地瞄向 h7。",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "我们兵进到 c4，赢得空间，并把那只象送回 e2。",
    "Now comes pawn to f6, the characteristic French lever.": "现在是兵到 f6，法兰西防御特有的杠杆。",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.": "我们不只是在欣赏白方的中心，而是在要求它出示自己的资格。",
    "White castles king side, black castles queen side.": "白方王翼易位，黑方后翼易位。",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.": "双方的王现在分居两翼，局面精彩地不平衡，黑方的计划也很清楚。",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.": "挑战 e5 兵，打开有用的线路，并有目的地在后翼展开活动。",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.": "这就是局面型 Winawer：结构扎实，意图好斗，并藏着相当多的暗电。",
    "Your turn, drill it until the move order feels less like memory and more like common sense.": "轮到你了，反复演练，直到着法顺序不再像记忆，而更像常识。",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "就在这儿，亲爱的们。Big Red 来了。今天我们好好看一看 Ruy Lopez，",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "也叫西班牙开局。这一局里有一段历史。它的名字来自",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "Ruy Lopez de Segura，一位研究过这步开局的西班牙神父兼棋谱作者，时间在",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "16世纪。白方先走兵到 e4。黑方应兵到 e5。马到 f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "攻击那只兵，黑方用马到 c6 来防守。然后象到 b5。于是",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "就有了。Ruy Lopez。这只象并不是立刻赢下 e5 兵。它是在施加",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "压力，压住守卫那只兵的马，给黑方一个安静却持续的问题去想。",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "从这个优雅的小开头，长出国际象棋里最宏大的开局家族之一。",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "有些变例平静而善于调遣，另一些会在你还没来得及坐稳之前就活跃起来",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "你的茶。它古典、细腻，充满真正的战略思想。古老、庄重，却仍然",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "充满可能。有一点像伦敦本身。所以盯住中心，",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "照看好你的棋子，享受更熟悉 Ruy Lopez。Big Red 回头见。",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "好了，亲爱的们，Big Red 回到了棋盘前，这是我们 Ruy Lopez 学习包的第 1 线，Morphy 防御封闭 Breyer 变例。",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "我们执白棋，这是一盘真正的战略杰作。",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "白方以兵到 e4 开始，黑方应兵到 e5，Nf3 攻击那只兵，黑方用 Nc6 来防守。",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5，Ruy Lopez 已经在棋盘上。黑方走兵到 a6，宣告 Morphy 防御",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "并向我们的象提出一个非常直接的问题。我们把象退到 a4。黑方发展 Nf6，",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "我们王翼易位，黑方把象发展到 e7。车到 e1，加强我们的 e4 兵",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "并把车放到黑王对面。黑方以兵到 b5 扩张，于是我们的象落在",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "b3。兵到 d6 给黑方的中心一个结实的基础。我们走兵到 c3，",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "准备宏大的中心挺进，兵到 d4。黑方王翼易位。现在兵到 h3，",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "一步有用的小着，让象或马远离 g4，也给我们的王一点喘息的空间。",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "然后就是那步让 Breyer 一眼就能认出的着法。黑方把马退到 b8。",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "看起来这匹马好像忘了自己为什么出来，可完全不是这样。这是战略上的",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "最高级的回收。我们以兵到 d4 出击，建立起一座壮丽的中心。黑方",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "把那匹马改道到 d7，在那里支持 e5，并解放 c 兵以备日后的反击。",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "我们的后翼马发展到 d2。黑方的象走到 b7，瞄准 e4。象",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "到 c2，保住我们宝贵的西班牙象，并指向王翼。黑方把",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "车放到 e8，进一步支持 e5 兵。最后，我们的马滑到 f1。那匹马",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "有一条出色的路线。从 f1 它可以前往 g3，加大对 f5 的压力，并帮助",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "王翼进攻积聚势头。这就是封闭 Breyer。耐心、精致，而且",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "完全充满生命与能量。白方拥有中心空间。黑方已经建成一个紧凑的",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "局面，并在准备反击。带着信念去下。享受每一次调遣",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "并且记住，安静的着法不是在干等。它们正在给弹簧上弦。",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "交给你了，反复演练，直到那匹马从 b1 到 d2 再到 f1 的旅程，感觉像找到",
    "your way around London.":
      "在伦敦的路一样自然。",
    "Right then, the Sicilian Defence for Black.":
      "好，这是黑方的西西里防御。",
    "White starts with 1. e4, claiming the centre.":
      "白方以 1. e4 开局，争夺中心。",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "黑方应以 1. c5 从侧翼还击，而不是直接照搬白方。",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "其用意是挑战白方的中心野心，积极出子，并从一开始就制造反击。",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "一条常见路线是 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6。",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "就是这样：一种锐利、灵活、很有锋芒的防御。",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "好，欢迎来到 Sicilian 的第 1 线，Najdorf。",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "这是黑方对兵到 e4 最有野心的应着之一。",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "白方以兵到 e4 开局，黑方立刻用兵到 c5 从侧面冲击。",
    "White develops knight to f3.":
      "白方把马发展到 f3。",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "黑方走兵到 d6，白方用兵到 d4 打开中心。",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "黑方用 c 兵在 d4 吃子，白方用马吃 d4 回吃。",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "黑方把马发展到 f6，白方把另一只马带到 c3。",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "现在是著名的 Najdorf 着法，兵到 a6，一步灵活的小棋，背后很有威力。",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "黑方保持局面的弹性，并准备在后翼扩张。",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "这条线的前半是兵到 e4，兵到 c5，马到 f3，兵到 d6，兵到 d4，兵吃 d4，马吃 d4，马到 f6，马到 c3，兵到 a6，象到 e3，兵到 e5，马到 b3，象到 e6。",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "现在这条线继续，兵到 f3，象到 e7，后到 d2，短易位，长易位，马到 bd7，兵到 g4，兵到 b5。",
    "White prepares a kingside assault with pawn to f3.":
      "白方用兵到 f3 准备王翼进攻。",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "黑方从容地把象发展到 e7，然后白方把后带到 d2。",
    "Black castles kingside and White castles queenside.":
      "黑方短易位，白方长易位。",
    "Now the battle lines are drawn.":
      "现在双方的战线已经划开。",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "黑方把马发展到 bd7，白方用兵到 g4 开始著名的兵冲。",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "黑方以兵到 b5 回应，Najdorf 就此活了起来。",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "白方在王翼集结兵力，黑方沿后翼推进，双方都在准备相当危险的一手。",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "好，紧跟这些着法，保持清醒，享受这条精彩的 Sicilian 线路。",
  },
  fr: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Bien — Scotch Gambit. Cela commence comme une vraie partie ouverte : e4, e5, les cavaliers sortent, puis les Blancs frappent le centre avec d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Quand les Noirs prennent en d4, les Blancs peuvent laisser le pion et poser le fou en c4. C'est le gambit : développer vite, viser f7, et mettre les Noirs sous pression avant qu'ils ne rangent la position.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "La famille Scotch doit son nom à ces parties par correspondance Edinburgh–London des années 1820. Les amateurs aiment encore cette ligne parce que l'échiquier s'ouvre et que les plans sont concrets — pas un long étau silencieux.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Prends ton thé. Pratique les coups du livre avec moi — je te garderai sur le vrai chemin du Scotch Gambit.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Bien — bienvenue à la Ligne 1. Professor Potato Pie, à ton service.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "Dans ce pack, nous avons distillé le gambit en dix lignes choisies avec soin.",
    "10 lines from Opening Lab.":
      "10 lignes d'Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Apprends-les et tu ne feras pas que survivre à la théorie. Tu rendras les bons coups avec assurance, tu garderas l'équilibre et tu resteras fermement dans la partie.",
    "You get 10 lines from Opening Lab.":
      "Tu as 10 lignes d'Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Quand les Noirs se trompent, tu apprendras à voir pourquoi le coup est fautif, à choisir la suite précise, à transformer l'erreur en avantage clair et, parfois, en un échec et mat fort élégant.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Naturellement, les Noirs ont plus de dix façons de jouer. Vois ceci comme un petit manuel, pas comme une encyclopédie — la logique des coups, pas seulement une suite à mémoriser.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Termine le pack et le Scotch Gambit te sera familier dès qu'il apparaît. Tu reconnaîtras les repères, tu comprendras les plans, et tu auras un vrai point d'appui pour aller plus loin.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Profites-en. Prends ton temps, parcours chaque ligne, et je te retrouve à l'échiquier.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Bien, place aux pièges d'ouverture. Ces lignes sont très amusantes et, parfois, elles prennent un adversaire sans méfiance tout à fait au dépourvu. Rien que pour cela, elles valent d'être connues.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Mais il y a un point plus sérieux. Étudier les pièges apprend à reconnaître les signes d'alerte, et tu as bien moins de chances d'y tomber toi-même.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Parcours chaque ligne, saisis l'idée, et savoure les petits mécanismes tactiques, si élégants.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Sers-t'en avec jugement, comprends-les vraiment, et quand l'occasion se présente, laisse la précision faire le travail.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Essaie, amuse-toi, et je crois qu'il est l'heure d'une tourte aux pommes de terre. Profite.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Bien, bienvenue à la Ligne 1. Voici Legal's Mate, nommé d'après Monsieur de Légal, un joueur français du XVIIIe siècle.",
    "White opens with the king's pawn, e4.": "Les Blancs ouvrent avec le pion du roi, e4.",
    "Black answers symmetrically with e5.": "Les Noirs répondent de façon symétrique avec e5.",
    "Knight to f3 attacks that pawn.": "Cavalier en f3 attaque ce pion.",
    "Black defends it with d6, which is the Philidor Defence.":
      "Les Noirs le défendent avec d6, ce qui est la défense Philidor.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "Le fou des Blancs vient en c4 et vise la petite case faible f7.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "Le fou des Noirs va en g4 et cloue le cavalier contre la dame.",
    "White calmly develops, knight to c3.": "Les Blancs développent calmement, cavalier en c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "Les Noirs jouent g6. C'est un coup lent, et le piège est maintenant prêt.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "Le cavalier prend en e5 ! Ce cavalier n'était cloué que contre la dame, pas contre le roi, il est donc tout à fait libre de bouger.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "Les Noirs ne résistent pas et prennent la dame en d1. C'est la capture gourmande, et elle est fatale.",
    "Bishop takes f7, check!": "Le fou prend en f7, échec !",
    "The king has only one square to go to, e7.": "Le roi n'a plus qu'une case, e7.",
    "Knight to d5, and that's checkmate.": "Cavalier en d5, et c'est échec et mat.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "Deux cavaliers et un fou ont battu toute l'armée noire. La dame, les tours et le fou en d1 des Noirs sont encore sur l'échiquier, et aucun ne peut aider.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Souviens-toi : quand on t'offre une dame gratuitement si tôt, regarde bien autour avant de la prendre.",
    "Now over to you. Practise it until your knights know the way.":
      "À toi maintenant. Pratique jusqu'à ce que tes cavaliers connaissent le chemin.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "Ah, rebonjour. Professor Potato Pie, thé en main. Aujourd'hui, la défense Caro-Kann, une ouverture solidement résistante, aux excellentes manières et aux coudes étonnamment pointus.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "Elle commence par e4 c6, et tient son nom de Horatio Caro et Marcus Kann, deux joueurs du XIXe siècle dont le travail d'analyse a donné son identité à cette vénérable défense.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "Le principe stratégique est admirablement économique. Les Noirs préparent d5, contestant tout de suite le centre des Blancs, tout en laissant libre le fou des cases claires au lieu de l'enfermer derrière la chaîne de pions.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "La Caro-Kann est solide, patiente et saine de structure, mais ne prends pas le calme pour de la passivité. Sous cet extérieur respectable se cache une belle collection de contre-coups, surtout si les Blancs deviennent trop ambitieux.",
    "You'll study 10 lines from Opening Lab.":
      "Tu étudieras 10 lignes d'Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "Ce sont 10 lignes d'Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "En Practice, je donnerai des indices partout où tu en as besoin. En Test, l'aide disparaît : il n'y a plus que toi, la position et ton jugement.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Chaque ligne s'arrête là où s'arrête la ligne du livre préparée. Il n'y a pas de suite contre l'ordinateur ensuite.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "Le but n'est pas de continuer au hasard, mais d'absorber les coups, de comprendre les idées et de reconnaître les schémas quand tu reviens à l'échiquier.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Bien. Le thé est servi, les pièces sont prêtes. Commençons.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Bien, bienvenue à la Ligne 1, la variante de l'avance. Les Blancs revendiquent le centre avec e4.",
    "We answer c6, preparing the thematic d5 advance.":
      "Nous répondons c6, en préparant l'avance thématique d5.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "Les Blancs établissent un large centre avec d4, et nous le contestons tout de suite avec d5.",
    "White pushes on to e5, gaining space.":
      "Les Blancs poussent jusqu'à e5 et gagnent de l'espace.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Avant de fermer la chaîne de pions avec e6, notre fou s'échappe en f5. C'est, au fond, le premier bon ménage de la Caro-Kann. Le fou sort avant que la porte se ferme.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "Suit cavalier f3, puis e6. Le fou étant développé en sûreté, e6 est maintenant tout à fait confortable.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "Les Blancs choisissent le dispositif calme et sensé du fou en e2, un système popularisé par le grand maître anglais Nigel Short.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "Nous frappons avec c5, en attaquant la base de la chaîne de pions blanche en d4.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "Les Blancs roquent, et cavalier c6 ajoute une pièce à la pression.",
    "White reinforces d4 with c3.": "Les Blancs renforcent d4 avec c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "Nous échangeons les pions en d4, ouvrant la colonne c et donnant à notre contre-jeu une voie utile.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "L'autre cavalier se développe en e7, en route vers f5, où il peut de nouveau questionner d4.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "Les Blancs jouent cavalier c3, et notre fou applique le clouage depuis g4.",
    "White answers with knight e1, breaking the pin.":
      "Les Blancs répondent avec cavalier e1, et rompent le clouage.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Nous échangeons donc l'utile fou blanc en e2. Reprendre avec le cavalier garde d4 solidement défendu.",
    "Our knight settles on f5, still eyeing d4.":
      "Notre cavalier s'installe en f5, l'œil toujours sur d4.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "Les Blancs le protègent avec fou e3, et nous développons calmement le fou en e7, prêts à roquer.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "Le résultat est une position égale avec un plan cohérent. Maintiens la pression sur d4 et sers-toi de la colonne c avec intention.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "Pas besoin de feu d'artifice : juste une structure saine, une pression patiente, et chaque pièce utilement employée.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "À toi. Répète la ligne jusqu'à ce que les coups ressemblent moins à de la mémoire et plus à du bon sens.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Bien, Professor Potato Pie ici, thé en main, et aujourd'hui nous jetons un bref regard sur le système de Londres.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "Cette ouverture est devenue étroitement associée au grand Tournoi de Londres de 1922, où ce dispositif fiable a attiré une attention plus large.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Bien, elle commence d'ordinaire par le pion en d4, le cavalier en f3 et le fou en f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Viennent ensuite le pion en e3, le pion en c3, le cavalier en d2, le fou en d3 et le petit roque.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "L'ordre précis peut changer, mais cette formation familière est le cœur du système de Londres.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "C'est une ouverture solide et sensée, jouée aussi bien par les joueurs de club que par les grands maîtres.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Bien, prenez plaisir à mieux connaître le système de Londres, et voyons comment les pièces s'assemblent.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Bien, regardons la première ligne de notre pack d'apprentissage du Londres.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Voici la pince de Londres, calme au départ, mais il y a de la méthode dans chaque coup.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Nous jouons le pion en d4 et les Noirs répondent par le pion en d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Fou en f4, cavalier en f6, pion en e3, et les Noirs frappent avec le pion en c5.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Nous bâtissons la pyramide familière avec le pion en c3, les Noirs développent le cavalier en c6.",
    "Knight to d2 and black plays pawn to e6.":
      "Cavalier en d2 et les Noirs jouent le pion en e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "Notre autre cavalier vient en f3, tandis que le fou noir vient en d6.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Nous ramenons notre fou en g3, pour le garder utile et sûr.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "Les Noirs roquent côté roi, nous plaçons notre autre fou en d3, les Noirs jouent le pion en b6 et maintenant nous plantons le cavalier en e5, un splendide avant-poste central.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Fou en b7, nous roquons côté roi, les Noirs placent la dame en c7 et nous achevons la pince avec le pion en f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "La voilà, une position de Londres compacte, le centre fermement sous surveillance et nos pièces qui commencent à regarder vers le flanc roi.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Répète-la jusqu'à ce que ta main connaisse la route et que ton adversaire se demande quand l'ouverture calme est devenue une attaque.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Bien, ici Professor Potato Pie, thé en main, et aujourd'hui nous rencontrons l'une des ouvertures les plus anciennes et les plus élégantes des échecs, la partie italienne.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "Ses idées ont été étudiées par les maîtres italiens il y a plus de quatre siècles, et l'ouverture apparaît encore aujourd'hui à tous les niveaux des échecs.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "Les Blancs commencent par le pion en e4, et les Noirs répondent pion en e5, cavalier en f3, cavalier en c6, puis fou en c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "Ce fou vise f7, la petite case délicate à côté du roi noir.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "D'ici, les Noirs répondent souvent par le fou en c5, entrant dans le Giuoco Piano, ou par le cavalier en f6, pour atteindre la défense des deux cavaliers.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "La partie italienne est classique, vive, et bâtie sur le développement naturel, le contrôle du centre et les possibilités d'attaque.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Bien, prenez plaisir à mieux connaître la partie italienne, et voyons où ce fou en c4 nous mène.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Bien, bienvenue dans la ligne 1 de notre pack d'apprentissage de la partie italienne.",
    "This is the quieter Italian.": "Voici l'italienne plus calme.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "Inutile de mettre le feu aux rideaux quand une préparation soigneuse suffit très bien.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Nous commençons par le pion en e4, et les Noirs répondent par le pion en e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "Cavalier en f3, cavalier en c6, fou en c4, et les Noirs développent le fou en c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "Les deux fous occupent leurs postes classiques et gardent un œil vigilant sur le centre.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Nous jouons le pion en c3, préparant un futur pion en d4.",
    "Black develops knight to f6 and places pressure on e4.":
      "Les Noirs développent le cavalier en f6 et exercent une pression sur e4.",
    "Pawn to d3, pawn to d6.": "Pion en d3, pion en d6.",
    "Both sides secure the centre before making any grand declarations.":
      "Les deux camps sécurisent le centre avant toute grande déclaration.",
    "We castle king side.": "Nous roquons côté roi.",
    "Black plays pawn to a6.": "Les Noirs jouent le pion en a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Nous répondons par le pion en a4, gagnant un peu d'espace côté dame, et le fou s'installe en a7.",
    "Knight to d2 and black castles king side.": "Cavalier en d2 et les Noirs roquent côté roi.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Nous jouons le pion en h3, empêchant un fou de devenir gênant en g4, et donnant à notre roi une case utile pour respirer.",
    "Black's knight moves to e7.": "Le cavalier noir se déplace en e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "La tour en e1 renforce le e4, et le cavalier poursuit vers g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "Nous y voilà, une position italienne saine, chaque pièce se préparant à un travail utile.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Continue à développer, surveille le centre et sois prêt pour la rupture d4 quand le moment sera venu.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Répète la ligne jusqu'à ce que les coups semblent aussi naturels que de mettre la bouilloire.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Bien, ici Professor Potato Pie, thé correctement infusé, et aujourd'hui nous présentons l'une des grandes ouvertures classiques, le gambit dame.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "L'ouverture apparaît dans les écrits échiquéens depuis la fin du XVe siècle, et des générations de joueurs distingués l'ont utilisée pour disputer le centre.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "Les Blancs commencent par pion en d4, et les Noirs répondent pion en d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Puis les Blancs jouent pion en c4, défiant le pion central noir et offrant le pion c.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "On l'appelle un gambit, bien que les Blancs puissent d'habitude récupérer le pion si les Noirs l'acceptent,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Donc ceci est moins un don irréfléchi qu'une invitation stratégique, servie poliment mais avec des arrière-pensées.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "À partir d'ici, les Noirs peuvent accepter le pion ou le refuser et garder un centre solide.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Bien, prends plaisir à te familiariser davantage avec le gambit dame et voyons ce que ce petit pion c aventureux peut persuader les Noirs de faire.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Bien, bienvenue à la Ligne 1 de notre pack d'apprentissage du gambit dame.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "C'est du vrai jeu classique : des fondations fermes, un développement patient, et aucun meuble lancé à travers la pièce.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Nous commençons par pion en d4 et les Noirs répondent pion en d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Pion en c4 défie le centre et les Noirs répondent pion en e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "C'est le gambit dame refusé. Les Noirs soutiennent le pion d5 au lieu d'accepter notre offre.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "Cavalier en c3, cavalier en f6, fou en g5 crée le clouage et les Noirs développent calmement le fou en e7.",
    "We play pawn to e3 and black castles kingside.":
      "Nous jouons pion en e3 et les Noirs roquent du côté roi.",
    "Knight to f3, knight to d7.": "Cavalier en f3, cavalier en d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Tour en c1 place la tour sur la colonne c pendant que les Noirs jouent pion en c6 et renforcent la structure centrale.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Fou en d3 et les Noirs résolvent maintenant la tension avec pion de d5 prend c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "Notre fou prend c4, récupérant le pion tout en développant.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "Le cavalier noir va en d5 et occupe une forte case centrale.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Nous échangeons avec fou prend e7 et la dame noire reprend en e7.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "Voilà, une position équilibrée du gambit dame, avec un développement sensé et encore beaucoup de jeu au centre.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Apprends la structure, comprends les échanges et laisse la position te dire quand il est temps d'avancer.",
    "Very civilised and quietly ambitious.": "Très civilisé, et discrètement ambitieux.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Bien, ici Professor Potato Pie, je vous mets en place, et aujourd'hui nous rencontrons la défense française : quelles sont les réponses les plus résilientes des Noirs au pion du roi ?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "Les Blancs commencent par pion en e4, nous répondons pion en e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "Les Blancs prennent plus d'espace avec pion en d4 et nous frappons aussitôt avec pion en d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "L'ouverture tire son nom d'une partie par correspondance entre Londres et Paris en 1834, lorsque l'équipe de Paris employa la défense avec succès.",
    "Its character is patient, but hardly passive.": "Son caractère est patient, mais guère passif.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "Les Noirs bâtissent une solide chaîne de pions, invitent les Blancs à déclarer leurs intentions, puis contestent le centre par des coups tels que pion en c5 et, le moment venu, pion en f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "Notre fou de cases claires peut demander un peu de diplomatie, mais cela fait partie de l'architecture subtile de l'ouverture.",
    "Solid, combative and rich in counterplay.": "Solide, combative et riche en contre-jeu.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "La française ne précipite pas le débat : elle le gagne, une question précise à la fois.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "Alors installez-vous, gardez l'œil sur les ruptures de pions et prenez plaisir à mieux connaître la défense française.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "Bien, bienvenue à la ligne 1 de notre pack d'apprentissage de la défense française.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "Le titre exact est la défense française, variante Winawer, ligne principale positionnelle de l'avance, et nous la travaillons du côté des Noirs.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "Les Blancs commencent par pion en e4, nous répondons pion en e6, les Blancs prennent le centre avec pion en d4 et nous le contestons avec pion en d5.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "Cavalier en c3, puis fou en b4 : cela annonce la Winawer.",
    "We pin the knight and ask white how ambitious they're feeling.": "Nous clouons le cavalier et demandons aux Blancs à quel point ils se sentent ambitieux.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "Les Blancs avancent le pion en e5, nous contre-attaquons aussitôt avec pion en c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "Les Blancs jouent pion en a3, défiant notre fou, donc le fou prend c3, échec.",
    "White recaptures with the b-pawn to c3.": "Les Blancs reprennent avec le pion b vers c3.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "Les Blancs ont gagné la paire de fous et un large centre, mais ont accepté en échange des pions c doublés.",
    "That trade-and-balance is the very grammar of the Winawer.": "Cet échange et cet équilibre sont la grammaire même de la Winawer.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.":
      "Nous développons le cavalier en e7, les Blancs développent le cavalier en f3 et notre fou va en d7.",
    "White plays pawn to a4, restraining queen side expansion.": "Les Blancs jouent pion en a4, freinant l'expansion à l'aile dame.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Nous répondons dame en a5, en pressant c3 et en aidant à dégager la voie pour le roque à l'aile dame.",
    "Bishop to d2 and our knight develops to c6.": "Fou en d2 et notre cavalier se développe en c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "Les Blancs placent le fou en d3, jetant un regard plutôt impoli vers h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "Nous avançons le pion en c4, gagnant de l'espace et renvoyant ce fou en e2.",
    "Now comes pawn to f6, the characteristic French lever.": "Vient alors pion en f6, le levier caractéristique de la française.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.":
      "Nous ne nous contentons pas d'admirer le centre des Blancs : nous lui demandons de présenter ses titres.",
    "White castles king side, black castles queen side.": "Les Blancs roquent à l'aile roi, les Noirs roquent à l'aile dame.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "Les rois sont maintenant installés sur des ailes opposées, la position est splendidement déséquilibrée et le plan des Noirs est clair.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "Conteste le pion e5, ouvre des lignes utiles et crée de l'activité à l'aile dame avec un vrai dessein.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Voilà la Winawer positionnelle : solide dans sa construction, combative dans son intention, et porteuse d'une bonne dose d'électricité cachée.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.":
      "À toi : répète-la jusqu'à ce que l'ordre des coups ressemble moins à de la mémoire et davantage au bon sens.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Juste là, mes amours. Big Red ici. Et aujourd'hui nous regardons comme il faut la Ruy Lopez,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "aussi appelée ouverture espagnole. Il y a de l'histoire dans celle-ci. Elle tient son nom",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "de Ruy Lopez de Segura, un prêtre espagnol et auteur d'échecs qui étudia l'ouverture au",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "XVIe siècle. Les Blancs commencent par le pion en e4. Les Noirs répondent pion en e5. Cavalier en f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "attaque ce pion et les Noirs le défendent avec le cavalier en c6. Puis vient le fou en b5. Et voilà",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "vous l'avez. La Ruy Lopez. Le fou ne gagne pas tout de suite le pion e5. Il applique",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "une pression sur le cavalier qui le garde, et laisse aux Noirs un problème discret mais tenace.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "De ce petit début élégant grandit l'une des plus grandes familles d'ouvertures aux échecs.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Certaines lignes sont calmes et manœuvrières, d'autres peuvent s'animer avant que vous ayez eu le temps de poser",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "votre thé. Elle est classique, subtile et pleine d'idées stratégiques sérieuses. Vieille, digne et encore",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "pleine de possibilités. Un peu comme Londres elle-même. Alors gardez l'œil sur le centre,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "soignez vos pièces et prenez plaisir à mieux connaître la Ruy Lopez. Big Red vous reverra.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "Bien alors mes amours, Big Red est de retour à l'échiquier et voici la ligne 1 de notre pack d'apprentissage de la Ruy Lopez, la défense Morphy, variante fermée Breyer.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Nous jouons les pièces blanches et c'est un vrai chef-d'œuvre stratégique.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "Les Blancs commencent par le pion en e4, les Noirs répondent pion en e5, Nf3 attaque le pion et les Noirs le défendent avec Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 et la Ruy Lopez est sur l'échiquier. Les Noirs jouent le pion en a6, annonçant la défense Morphy",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "et posent à notre fou une question très directe. Nous reculons le fou en a4. Les Noirs développent Nf6,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "nous roquons côté roi et les Noirs développent le fou en e7. La tour en e1 renforce notre pion e4",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "et place la tour en face du roi noir. Les Noirs s'étendent avec le pion en b5, alors notre fou s'installe",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "en b3. Le pion en d6 donne au centre noir une base solide. Nous jouons le pion en c3,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "préparant la grande avance centrale, le pion en d4. Les Noirs roquent côté roi. Maintenant le pion en h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "un petit coup utile qui tient un fou ou un cavalier loin de g4 et donne à notre roi un peu d'air.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Vient alors le coup qui rend la Breyer impossible à confondre. Les Noirs reculent le cavalier en b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "On dirait que le cavalier a oublié pourquoi il est sorti, mais pas du tout. C'est stratégique",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "recyclage du plus haut ordre. Nous frappons avec le pion en d4, établissant un centre magnifique. Les Noirs",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "réacheminent ce cavalier en d7, où il soutient e5 et libère le pion c pour un futur contre-jeu.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "Notre cavalier de l'aile dame se développe en d2. Le fou noir va en b7 et vise e4. Le fou",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "en c2 préserve notre précieux fou espagnol et pointe vers l'aile roi. Les Noirs placent la",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "tour en e8, ajoutant encore du soutien au pion e5. Enfin, notre cavalier glisse en f1. Ce cavalier",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "a un itinéraire splendide. Depuis f1 il peut aller en g3, augmentant la pression sur f5 et aidant",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "l'attaque côté roi à prendre de l'élan. Voilà la Breyer fermée. Patiente, sophistiquée et",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "absolument débordante de vie et d'énergie. Les Blancs possèdent l'espace central. Les Noirs ont construit une position compacte",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "et préparent la contre-attaque. Jouez-la avec conviction. Savourez chaque manœuvre",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "et souvenez-vous : les coups tranquilles n'attendent pas. Ils arment le ressort.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "À vous : répétez-la jusqu'à ce que ce voyage du cavalier de b1 à d2 puis à f1 semble aussi naturel que de trouver",
    "your way around London.":
      "votre chemin dans Londres.",
    "Right then, the Sicilian Defence for Black.":
      "Bien alors, la défense sicilienne pour les Noirs.",
    "White starts with 1. e4, claiming the centre.":
      "Les Blancs commencent par un point e4 et revendiquent le centre.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "Les Noirs répondent un point c5, en frappant de côté plutôt qu'en copiant directement les Blancs.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "L'idée est de contester les ambitions centrales des Blancs, de se développer activement et de créer du contre-jeu dès le début.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Une voie courante est 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "Vous y voilà : une défense aiguë et souple, avec beaucoup de mordant.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Bien, bienvenue à la ligne 1 de la Sicilian, la Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "C'est l'une des réponses les plus ambitieuses des Noirs au pion en e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "Les Blancs ouvrent par le pion en e4, et les Noirs frappent aussitôt par le pion en c5.",
    "White develops knight to f3.":
      "Les Blancs développent le cavalier en f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "Les Noirs jouent le pion en d6, et les Blancs ouvrent le centre par le pion en d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "Les Noirs prennent en d4 avec le pion c, les Blancs reprennent par cavalier prend d4.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "Les Noirs développent le cavalier en f6, et les Blancs amènent l'autre cavalier en c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Voici le fameux coup Najdorf, pion en a6, un petit coup souple avec beaucoup de venin.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "Les Noirs gardent la position adaptable et se préparent à s'étendre à l'aile dame.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "La première partie de la ligne est pion en e4, pion en c5, cavalier en f3, pion en d6, pion en d4, pion prend d4, cavalier prend d4, cavalier en f6, cavalier en c3, pion en a6, fou en e3, pion en e5, cavalier en b3, fou en e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "La ligne continue, pion en f3, fou en e7, dame en d2, petit roque, grand roque, cavalier en bd7, pion en g4, pion en b5.",
    "White prepares a kingside assault with pawn to f3.":
      "Les Blancs préparent un assaut à l'aile roi avec le pion en f3.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "Les Noirs développent calmement le fou en e7, puis les Blancs amènent la dame en d2.",
    "Black castles kingside and White castles queenside.":
      "Les Noirs roquent côté roi et les Blancs roquent côté dame.",
    "Now the battle lines are drawn.":
      "Les lignes de bataille sont maintenant tracées.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "Les Noirs développent le cavalier en bd7 et les Blancs lancent la fameuse tempête de pions avec le pion en g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "Les Noirs répondent par le pion en b5 et voilà, la Najdorf s'anime.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "Les Blancs rassemblent leurs forces à l'aile roi, les Noirs chargent à l'aile dame, et les deux préparent quelque chose de plutôt dangereux.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Bien, suivez les coups de près, gardez votre sang-froid et profitez de cette belle ligne Sicilian.",
  },
  de: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Also — Scotch Gambit. Es beginnt wie eine richtige offene Partie: e4, e5, Springer heraus, dann trifft Weiß das Zentrum mit d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Wenn Schwarz auf d4 nimmt, kann Weiß den Bauern stehen lassen und den Läufer auf c4 stellen. Das ist das Gambit — schnell entwickeln, auf f7 zielen und Schwarz unter Druck setzen, bevor die Stellung aufgeräumt ist.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "Die Scotch-Familie hat ihren Namen von jenen Fernpartien Edinburgh–London in den 1820er Jahren. Liebhaber mögen diese Linie noch immer, weil das Brett sich öffnet und die Pläne konkret sind — kein langes stilles Würgen.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Hol deinen Tee. Übe die Buchzüge mit mir — ich halte dich auf dem echten Weg des Scotch Gambit.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Also dann — willkommen bei Linie 1. Professor Potato Pie, zu Diensten.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "In diesem Lernpack haben wir das Gambit in zehn sorgfältig gewählte Linien gefasst.",
    "10 lines from Opening Lab.":
      "10 Linien von Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Lerne sie, und du überstehst die Theorie nicht nur. Du gibst die richtigen Züge mit Ruhe zurück, hältst das Gleichgewicht und bleibst fest in der Partie.",
    "You get 10 lines from Opening Lab.":
      "Du bekommst 10 Linien von Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Wenn Schwarz danebengreift, lernst du zu erkennen, warum der Zug fehlerhaft ist, die genaue Fortsetzung zu wählen, den Fehler in klaren Vorteil zu verwandeln und gelegentlich in ein recht erlesenes Matt.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Natürlich hat Schwarz mehr als zehn Arten zu spielen. Sieh dies als kompakten kleinen Leitfaden, nicht als erschöpfende Enzyklopädie — die Logik hinter den Zügen, nicht bloß eine Folge zum Auswendiglernen.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Schließe das Pack ab, und das Scotch Gambit wird vertraut aussehen, wann immer es auftaucht. Du erkennst die Wegmarken, verstehst die Pläne und hast einen festen Stand, um weiterzustudieren.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Viel Freude. Nimm dir Zeit, geh jede Linie durch, und wir sehen uns am Brett.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Also dann, nun zu den Eröffnungsfallen. Diese Linien machen großen Spaß und können einen ahnungslosen Gegner gelegentlich völlig überrumpeln. Schon deshalb sind sie es wert.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Es gibt aber einen ernsteren Punkt. Fallen zu studieren lehrt dich, die Warnzeichen zu erkennen, sodass du selbst viel seltener hineintappst.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Geh jede Linie durch, fasse die Idee, und genieße die eleganten kleinen taktischen Mechanismen.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Setze sie mit Urteil ein, verstehe sie richtig, und wenn die Gelegenheit kommt, lass die Präzision die Arbeit tun.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Probier es, hab Spaß, und jetzt ist wohl Zeit für einen Kartoffelkuchen. Viel Freude.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Also dann, willkommen bei Linie 1. Das ist Legal's Mate, benannt nach Monsieur de Légal, einem französischen Spieler des 18. Jahrhunderts.",
    "White opens with the king's pawn, e4.": "Weiß eröffnet mit dem Königsbauern, e4.",
    "Black answers symmetrically with e5.": "Schwarz antwortet symmetrisch mit e5.",
    "Knight to f3 attacks that pawn.": "Springer nach f3 greift diesen Bauern an.",
    "Black defends it with d6, which is the Philidor Defence.":
      "Schwarz deckt ihn mit d6, das ist die Philidor-Verteidigung.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "Der Läufer von Weiß kommt nach c4 und schaut auf das schwache Feld f7.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "Der Läufer von Schwarz geht nach g4 und fesselt den Springer gegen die Dame.",
    "White calmly develops, knight to c3.": "Weiß entwickelt ruhig, Springer nach c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "Schwarz spielt g6. Ein langsamer Zug, und nun ist die Falle bereit.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "Springer nimmt auf e5! Dieser Springer war nur gegen die Dame gefesselt, nicht gegen den König, er darf sich also ganz frei bewegen.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "Schwarz kann nicht widerstehen und nimmt die Dame auf d1. Das ist der gierige Schlag, und er ist tödlich.",
    "Bishop takes f7, check!": "Läufer nimmt auf f7, Schach!",
    "The king has only one square to go to, e7.": "Der König hat nur noch ein Feld, e7.",
    "Knight to d5, and that's checkmate.": "Springer nach d5, und das ist Matt.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "Zwei Springer und ein Läufer haben das ganze schwarze Heer geschlagen. Dame, Türme und der Läufer auf d1 von Schwarz stehen noch auf dem Brett, und keiner kann helfen.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Denk daran: wenn so früh eine Dame umsonst angeboten wird, schau dich gut um, bevor du sie nimmst.",
    "Now over to you. Practise it until your knights know the way.":
      "Nun du. Übe es, bis deine Springer den Weg kennen.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "Ah, hallo wieder. Professor Potato Pie, Tee in der Hand. Heute wenden wir uns der Caro-Kann-Verteidigung zu, einer wunderbar zähen Eröffnung mit guten Manieren und überraschend spitzen Ellbogen.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "Sie beginnt mit e4 c6 und trägt den Namen von Horatio Caro und Marcus Kann, zwei Spielern des 19. Jahrhunderts, deren Analyse dieser ehrwürdigen Verteidigung ihre Identität gab.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "Der strategische Gedanke ist bewundernswert sparsam. Schwarz bereitet d5 vor, fordert das Zentrum von Weiß sofort heraus und hält den weißfeldrigen Läufer frei, statt ihn hinter der Bauernkette einzusperren.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Die Caro-Kann ist solide, geduldig und strukturell gesund, aber verwechsle Gelassenheit nicht mit Passivität. Unter der anständigen Oberfläche liegt eine feine Sammlung von Kontern, besonders wenn Weiß zu ehrgeizig wird.",
    "You'll study 10 lines from Opening Lab.":
      "Du studierst 10 Linien von Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "Das sind 10 Linien von Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "In Practice gebe ich Hinweise, wo du sie brauchst. In Test verschwindet die Hilfe, und es bleiben nur du, die Stellung und dein Urteil.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Jede Linie endet dort, wo die vorbereitete Buchlinie endet. Danach gibt es keine Fortsetzung gegen den Computer.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "Es geht nicht darum, ziellos weiterzuspielen, sondern die Züge aufzunehmen, die Ideen zu verstehen und die Muster zu erkennen, wenn du wieder am Brett sitzt.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Also dann. Tee steht, Figuren bereit. Fangen wir an.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Also dann, willkommen bei Linie 1, der Vorstoßvariante. Weiß beansprucht das Zentrum mit e4.",
    "We answer c6, preparing the thematic d5 advance.":
      "Wir antworten c6 und bereiten den thematischen Vorstoß d5 vor.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "Weiß errichtet mit d4 ein breites Zentrum, und wir fordern es sofort mit d5 heraus.",
    "White pushes on to e5, gaining space.": "Weiß stößt weiter nach e5 und gewinnt Raum.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Bevor die Bauernkette mit e6 geschlossen wird, entkommt unser Läufer nach f5. Das ist im Kern die erste gute Ordnung der Caro-Kann. Der Läufer kommt hinaus, bevor die Tür zugeht.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "Springer f3 folgt, dann e6. Mit dem sicher entwickelten Läufer ist e6 nun ganz bequem.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "Weiß wählt den ruhigen, vernünftigen Aufbau Läufer e2, ein System, das der englische Großmeister Nigel Short bekannt machte.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "Wir schlagen mit c5 zu und greifen die Basis der weißen Bauernkette auf d4 an.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "Weiß rochiert, und Springer c6 legt eine weitere Figur auf den Druck.",
    "White reinforces d4 with c3.": "Weiß verstärkt d4 mit c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "Wir tauschen Bauern auf d4, öffnen die c-Linie und geben unserem Gegenspiel einen nützlichen Weg.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "Der andere Springer entwickelt sich nach e7, auf dem Weg nach f5, wo er d4 erneut infrage stellen kann.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "Weiß spielt Springer c3, und unser Läufer setzt die Fesselung von g4 aus an.",
    "White answers with knight e1, breaking the pin.":
      "Weiß antwortet mit Springer e1 und löst die Fesselung.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Deshalb tauschen wir den nützlichen Läufer von Weiß auf e2. Das Zurückschlagen mit dem Springer hält d4 sicher gedeckt.",
    "Our knight settles on f5, still eyeing d4.":
      "Unser Springer setzt sich auf f5 fest und behält d4 im Auge.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "Weiß deckt es mit Läufer e3, und wir entwickeln ruhig den Läufer nach e7, bereit zur Rochade.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "Das Ergebnis ist eine ausgeglichene Stellung mit einem klaren Plan. Halte den Druck auf d4 und nutze die c-Linie mit Absicht.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "Kein Feuerwerk nötig, nur gesunde Struktur, geduldiger Druck und jede Figur sinnvoll beschäftigt.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "Nun du. Übe die Linie, bis die Züge sich weniger nach Gedächtnis und mehr nach gesundem Urteil anfühlen.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Also dann, hier ist Professor Potato Pie, Tee in der Hand, und heute werfen wir einen kurzen Blick auf das Londoner System.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "Die Eröffnung wurde eng mit dem großen Londoner Turnier von 1922 verbunden, wo dieser verlässliche Aufbau weitere Aufmerksamkeit fand.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Richtig, sie beginnt gewöhnlich mit Bauer nach d4, Springer nach f3 und Läufer nach f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Dann folgen Bauer nach e3, Bauer nach c3, Springer nach d2, Läufer nach d3 und die kurze Rochade.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "Die genaue Reihenfolge kann sich ändern, aber diese vertraute Formation ist das Herz des Londoner Systems.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "Es ist eine solide, vernünftige Eröffnung, die sowohl Vereinsspieler als auch Großmeister gespielt haben.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Also, genieße es, das Londoner System besser kennenzulernen, und schauen wir, wie die Figuren zusammenpassen.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Also dann, sehen wir uns die erste Linie in unserem London-Lernpaket an.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Das ist die Londoner Klammer, anfangs ruhig, aber in jedem Zug steckt Methode.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Wir spielen Bauer nach d4 und Schwarz antwortet mit Bauer nach d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Läufer nach f4, Springer nach f6, Bauer nach e3, und Schwarz schlägt mit Bauer nach c5 zu.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Wir bauen die vertraute Pyramide mit Bauer nach c3, Schwarz entwickelt den Springer nach c6.",
    "Knight to d2 and black plays pawn to e6.":
      "Springer nach d2 und Schwarz spielt Bauer nach e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "Unser anderer Springer kommt nach f3, während der schwarze Läufer nach d6 kommt.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Wir ziehen unseren Läufer zurück nach g3 und halten ihn nützlich und sicher.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "Schwarz rochiert kurz, wir stellen unseren anderen Läufer auf d3, Schwarz spielt Bauer nach b6, und nun pflanzen wir den Springer auf e5, ein prächtiger Zentralvorposten.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Läufer nach b7, wir rochieren kurz, Schwarz stellt die Dame auf c7, und wir vollenden die Klammer mit Bauer nach f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "Da ist sie, eine kompakte Londoner Stellung, das Zentrum fest unter Aufsicht und unsere Figuren beginnen zum Königsflügel zu blicken.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Übe sie, bis deine Hand den Weg kennt und dein Gegner sich fragt, wann die ruhige Eröffnung zum Angriff wurde.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Also dann, hier ist Professor Potato Pie, Tee in der Hand, und heute begegnen wir einer der ältesten und elegantesten Eröffnungen des Schachs, der italienischen Partie.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "Ihre Ideen wurden von den italienischen Meistern vor mehr als vier Jahrhunderten studiert, und die Eröffnung erscheint noch heute auf jeder Ebene des Schachs.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "Weiß beginnt mit Bauer nach e4, und Schwarz antwortet mit Bauer nach e5, Springer nach f3, Springer nach c6 und dann Läufer nach c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "Dieser Läufer zeigt auf f7, das zarte kleine Feld neben dem schwarzen König.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "Von hier antwortet Schwarz gewöhnlich mit Läufer nach c5 und betritt das Giuoco Piano, oder mit Springer nach f6 und erreicht die Zweispringer-Verteidigung.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "Die italienische Partie ist klassisch, lebendig und auf natürliche Entwicklung, Zentrumskontrolle und Angriffsmöglichkeiten gebaut.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Also, genieße es, die italienische Partie besser kennenzulernen, und schauen wir, wohin uns dieser Läufer auf c4 führt.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Also, willkommen bei Linie 1 unseres Lernpakets zur italienischen Partie.",
    "This is the quieter Italian.": "Das ist die ruhigere italienische Partie.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "Kein Grund, die Vorhänge anzuzünden, wenn sorgfältige Vorbereitung völlig ausreicht.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Wir beginnen mit Bauer nach e4, und Schwarz antwortet mit Bauer nach e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "Springer nach f3, Springer nach c6, Läufer nach c4, und Schwarz entwickelt den Läufer nach c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "Beide Läufer beziehen ihre klassischen Posten und behalten das Zentrum wachsam im Blick.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Wir spielen Bauer nach c3 und bereiten einen künftigen Bauer nach d4 vor.",
    "Black develops knight to f6 and places pressure on e4.":
      "Schwarz entwickelt den Springer nach f6 und setzt e4 unter Druck.",
    "Pawn to d3, pawn to d6.": "Bauer nach d3, Bauer nach d6.",
    "Both sides secure the centre before making any grand declarations.":
      "Beide Seiten sichern das Zentrum, bevor sie große Erklärungen abgeben.",
    "We castle king side.": "Wir rochieren kurz.",
    "Black plays pawn to a6.": "Schwarz spielt Bauer nach a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Wir antworten mit Bauer nach a4, gewinnen etwas Raum am Damenflügel, und der Läufer lässt sich auf a7 nieder.",
    "Knight to d2 and black castles king side.": "Springer nach d2, und Schwarz rochiert kurz.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Wir spielen Bauer nach h3, damit ein Läufer auf g4 nicht lästig wird, und geben unserem König ein nützliches Luftfeld.",
    "Black's knight moves to e7.": "Der schwarze Springer zieht nach e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "Turm nach e1 verstärkt den e4, und der Springer zieht weiter nach g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "Da sind wir, eine gesunde italienische Stellung, in der jede Figur sich auf nützliche Arbeit vorbereitet.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Entwickle weiter, beobachte das Zentrum und sei bereit für den d4-Durchbruch, wenn der Moment stimmt.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Übe die Linie, bis sich die Züge so natürlich anfühlen wie das Aufsetzen des Kessels.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Also dann, hier ist Professor Potato Pie, Tee richtig gebrüht, und heute stellen wir eine der großen klassischen Eröffnungen vor, das Damengambit.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "Die Eröffnung erscheint in Schachschriften seit dem späten fünfzehnten Jahrhundert, und Generationen ausgezeichneter Spieler haben sie genutzt, um das Zentrum zu bestreiten.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "Weiß beginnt mit Bauer nach d4, und Schwarz antwortet mit Bauer nach d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Dann spielt Weiß Bauer nach c4, fordert den zentralen Bauern von Schwarz heraus und bietet den c-Bauern an.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "Man nennt es ein Gambit, obwohl Weiß den Bauern meist zurückholen kann, wenn Schwarz annimmt,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Dies ist also weniger eine leichtsinnige Spende als eine strategische Einladung, höflich serviert, aber mit Hintergedanken.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "Von hier aus kann Schwarz den Bauern annehmen oder ablehnen und ein solides Zentrum behalten.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Gut, hab Freude daran, das Damengambit näher kennenzulernen, und sehen wir, wozu dieser abenteuerlustige kleine c-Bauer Schwarz überreden kann.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Also dann, willkommen zu Linie 1 unseres Damengambit-Lernpacks.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "Das ist richtiges klassisches Schach: feste Grundlagen, geduldige Entwicklung und keine Möbel, die durch den Raum fliegen.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Wir beginnen mit Bauer nach d4 und Schwarz antwortet mit Bauer nach d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Bauer nach c4 fordert das Zentrum heraus und Schwarz antwortet mit Bauer nach e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "Das ist das abgelehnte Damengambit. Schwarz stützt den Bauern auf d5, statt unser Angebot anzunehmen.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "Springer nach c3, Springer nach f6, Läufer nach g5 erzeugt die Fesselung und Schwarz entwickelt ruhig den Läufer nach e7.",
    "We play pawn to e3 and black castles kingside.":
      "Wir spielen Bauer nach e3 und Schwarz rochiert kurz.",
    "Knight to f3, knight to d7.": "Springer nach f3, Springer nach d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Turm nach c1 stellt den Turm auf die c-Linie, während Schwarz Bauer nach c6 spielt und die Zentrumsstruktur stärkt.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Läufer nach d3 und Schwarz löst nun die Spannung mit Bauer von d5 schlägt c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "Unser Läufer schlägt c4 und holt den Bauern mit Entwicklung zurück.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "Schwarz' Springer zieht nach d5 und besetzt ein starkes Zentrumsfeld.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Wir tauschen mit Läufer schlägt e7 und Schwarz' Dame schlägt auf e7 zurück.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "Da ist sie, eine ausgeglichene Damengambit-Stellung mit vernünftiger Entwicklung und noch viel Spiel im Zentrum.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Lerne die Struktur, verstehe die Abtäusche und lass die Stellung dir sagen, wann es Zeit ist vorzugehen.",
    "Very civilised and quietly ambitious.": "Sehr gesittet und still ehrgeizig.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Also dann, hier ist Professor Potato Pie, ich mache Sie bereit, und heute begegnen wir der Französischen Verteidigung: Welches sind die widerstandsfähigsten Antworten von Schwarz auf den Königsbauern?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "Weiß beginnt mit Bauer nach e4, wir antworten mit Bauer nach e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "Weiß beansprucht mehr Raum mit Bauer nach d4, und wir schlagen sofort mit Bauer nach d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "Die Eröffnung erhielt ihren Namen von einem Fernschachwettkampf zwischen London und Paris im Jahr 1834, als die Pariser Mannschaft die Verteidigung erfolgreich einsetzte.",
    "Its character is patient, but hardly passive.": "Ihr Charakter ist geduldig, aber kaum passiv.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "Schwarz baut eine solide Bauernkette, lädt Weiß ein, die Absichten zu erklären, und stellt dann das Zentrum mit Zügen wie Bauer nach c5 in Frage und, wenn der Augenblick reif ist, Bauer nach f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "Unser Läufer auf hellen Feldern mag ein wenig Diplomatie verlangen, doch das gehört zur feinen Architektur der Eröffnung.",
    "Solid, combative and rich in counterplay.": "Solide, kämpferisch und reich an Gegenspiel.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "Die Französische drängt das Gespräch nicht: sie gewinnt es, eine präzise Frage nach der anderen.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "Also machen Sie es sich bequem, behalten Sie die Bauernhebel im Auge und genießen Sie, die Französische Verteidigung besser kennenzulernen.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "Also dann, willkommen bei Linie 1 unseres Lernpakets zur Französischen Verteidigung.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "Der eigentliche Titel ist die Französische Verteidigung, Winawer-Variante, positionelle Hauptlinie des Vorstoßes, und wir üben sie von der Seite von Schwarz.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "Weiß beginnt mit Bauer nach e4, wir antworten mit Bauer nach e6, Weiß nimmt das Zentrum mit Bauer nach d4 und wir stellen es mit Bauer nach d5 in Frage.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "Springer nach c3, dann Läufer nach b4: das kündigt die Winawer an.",
    "We pin the knight and ask white how ambitious they're feeling.": "Wir fesseln den Springer und fragen Weiß, wie ehrgeizig sie sich fühlen.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "Weiß zieht den Bauern nach e5 vor, wir kontern sofort mit Bauer nach c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.":
      "Weiß spielt Bauer nach a3, fordert unseren Läufer heraus, also nimmt der Läufer c3, Schach.",
    "White recaptures with the b-pawn to c3.": "Weiß schlägt mit dem b-Bauern nach c3 zurück.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "Weiß hat das Läuferpaar und ein breites Zentrum gewonnen, dafür aber doppelte c-Bauern in Kauf genommen.",
    "That trade-and-balance is the very grammar of the Winawer.": "Dieser Tausch und Ausgleich ist die eigentliche Grammatik der Winawer.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.":
      "Wir entwickeln den Springer nach e7, Weiß entwickelt den Springer nach f3 und unser Läufer geht nach d7.",
    "White plays pawn to a4, restraining queen side expansion.": "Weiß spielt Bauer nach a4 und bremst die Erweiterung am Damenflügel.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Wir antworten mit Dame nach a5, setzen c3 unter Druck und helfen, den Weg für die Rochade am Damenflügel freizumachen.",
    "Bishop to d2 and our knight develops to c6.": "Läufer nach d2 und unser Springer entwickelt sich nach c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "Weiß stellt den Läufer auf d3 und blickt ziemlich unhöflich nach h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.":
      "Wir ziehen den Bauern nach c4 vor, gewinnen Raum und schicken diesen Läufer zurück nach e2.",
    "Now comes pawn to f6, the characteristic French lever.": "Nun kommt Bauer nach f6, der charakteristische Hebel der Französischen.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.":
      "Wir bewundern das Zentrum von Weiß nicht nur, wir verlangen, dass es seine Berechtigung vorlegt.",
    "White castles king side, black castles queen side.": "Weiß rochiert kurz, Schwarz rochiert lang.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "Die Könige stehen nun auf entgegengesetzten Flügeln, die Stellung ist prächtig unausgeglichen und der Plan von Schwarz ist klar.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "Stelle den Bauern e5 in Frage, öffne nützliche Linien und erzeuge mit klarer Absicht Spiel am Damenflügel.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Das ist die positionelle Winawer: solide gebaut, kämpferisch in der Absicht und mit einer beträchtlichen Menge verborgener Elektrizität.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.":
      "Du bist dran: übe sie, bis die Zugfolge sich weniger wie Gedächtnis und mehr wie gesunder Menschenverstand anfühlt.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Genau da, meine Lieben. Big Red hier. Und heute schauen wir uns die Ruy Lopez richtig an,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "auch bekannt als spanische Eröffnung. In dieser steckt Geschichte. Sie trägt ihren Namen",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "von Ruy Lopez de Segura, einem spanischen Priester und Schachautor, der die Eröffnung im",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "16. Jahrhundert studierte. Weiß beginnt mit Bauer nach e4. Schwarz antwortet Bauer nach e5. Springer nach f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "greift diesen Bauern an, und Schwarz verteidigt ihn mit Springer nach c6. Dann kommt Läufer nach b5. Und da",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "habt ihr sie. Die Ruy Lopez. Der Läufer gewinnt den e5-Bauern nicht sofort. Er übt",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "Druck auf den Springer aus, der ihn deckt, und gibt Schwarz ein stilles, aber hartnäckiges Problem.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "Aus diesem eleganten kleinen Anfang wächst eine der größten Eröffnungsfamilien im Schach.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Manche Varianten sind ruhig und manövrierend, andere können lebhaft werden, bevor ihr Zeit hattet,",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "den Tee abzustellen. Sie ist klassisch, fein und voll echter strategischer Ideen. Alt, würdevoll und immer noch",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "voller Möglichkeiten. Ein wenig wie London selbst. Also behaltet die Mitte im Auge,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "passt auf eure Figuren auf und freut euch, die Ruy Lopez besser kennenzulernen. Big Red sieht euch wieder.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "So, meine Lieben, Big Red ist wieder am Brett und das ist Linie 1 unseres Lernpakets zur Ruy Lopez, die Morphy-Verteidigung, geschlossene Breyer-Variante.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Wir spielen mit den weißen Figuren und das ist ein echtes strategisches Meisterwerk.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "Weiß beginnt mit Bauer nach e4, Schwarz antwortet Bauer nach e5, Nf3 greift den Bauern an und Schwarz verteidigt ihn mit Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 und die Ruy Lopez steht auf dem Brett. Schwarz spielt Bauer nach a6 und kündigt die Morphy-Verteidigung an",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "und stellt unserem Läufer eine sehr direkte Frage. Wir ziehen den Läufer zurück nach a4. Schwarz entwickelt Nf6,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "wir rochieren kurz und Schwarz entwickelt den Läufer nach e7. Turm nach e1 verstärkt unseren e4-Bauern",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "und stellt den Turm dem schwarzen König gegenüber. Schwarz erweitert mit Bauer nach b5, also lässt sich unser Läufer nieder",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "auf b3. Bauer nach d6 gibt dem Zentrum von Schwarz ein solides Fundament. Wir spielen Bauer nach c3,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "und bereiten den großen zentralen Vorstoß vor, Bauer nach d4. Schwarz rochiert kurz. Nun Bauer nach h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "ein nützliches kleines Züglein, das einen Läufer oder Springer von g4 fernhält und unserem König etwas Luft gibt.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Dann kommt der Zug, der die Breyer unverwechselbar macht. Schwarz zieht den Springer zurück nach b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "Es sieht so aus, als hätte der Springer vergessen, warum er herauskam, aber keineswegs. Das ist strategisches",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "Recycling höchster Ordnung. Wir schlagen mit Bauer nach d4 zu und errichten ein großartiges Zentrum. Schwarz",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "lenkt diesen Springer nach d7 um, wo er e5 stützt und den c-Bauern für späteres Gegenspiel freimacht.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "Unser Damenspringer entwickelt sich nach d2. Der Läufer von Schwarz geht nach b7 und zielt auf e4. Der Läufer",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "nach c2 bewahrt unseren wertvollen spanischen Läufer und zeigt zur Königsseite. Schwarz stellt den",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "Turm auf e8 und stützt den e5-Bauern zusätzlich. Schließlich gleitet unser Springer nach f1. Dieser Springer",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "hat eine prächtige Reiseroute. Von f1 kann er nach g3 ziehen, den Druck auf f5 erhöhen und dabei helfen,",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "dass der Angriff auf der Königsseite Schwung aufnimmt. Das ist die geschlossene Breyer. Geduldig, raffiniert und",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "voller Leben und Energie. Weiß besitzt den zentralen Raum. Schwarz hat eine kompakte",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "Stellung aufgebaut und bereitet den Gegenschlag vor. Spielt sie mit Überzeugung. Genießt jedes Manöver",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "und denkt daran: die stillen Züge warten nicht herum. Sie spannen die Feder.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "Ihr seid dran: übt sie, bis diese Springerreise von b1 nach d2 und weiter nach f1 sich so natürlich anfühlt wie",
    "your way around London.":
      "den Weg durch London zu finden.",
    "Right then, the Sicilian Defence for Black.":
      "Also dann, die sizilianische Verteidigung für Schwarz.",
    "White starts with 1. e4, claiming the centre.":
      "Weiß beginnt mit einem Punkt e4 und beansprucht das Zentrum.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "Schwarz antwortet mit einem Punkt c5 und schlägt von der Seite zu, statt Weiß direkt zu kopieren.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "Die Idee ist, die zentralen Ambitionen von Weiß herauszufordern, aktiv zu entwickeln und von Anfang an Gegenspiel zu schaffen.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Ein üblicher Weg ist 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "Da sind Sie: eine scharfe, flexible Verteidigung mit ordentlich Biss.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Also dann, willkommen bei Linie 1 der Sicilian, der Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "Das ist eine der ehrgeizigsten Antworten von Schwarz auf Bauer nach e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "Weiß eröffnet mit Bauer nach e4, und Schwarz schlägt sofort mit Bauer nach c5.",
    "White develops knight to f3.":
      "Weiß entwickelt den Springer nach f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "Schwarz spielt Bauer nach d6, und Weiß öffnet das Zentrum mit Bauer nach d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "Schwarz nimmt auf d4 mit dem c-Bauern, Weiß schlägt mit Springer nimmt d4 zurück.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "Schwarz entwickelt den Springer nach f6, und Weiß bringt den anderen Springer nach c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Jetzt kommt der berühmte Najdorf-Zug, Bauer nach a6, ein kleiner flexibler Zug mit viel Gift.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "Schwarz hält die Stellung anpassungsfähig und bereitet die Erweiterung am Damenflügel vor.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "Der erste Teil der Linie ist Bauer nach e4, Bauer nach c5, Springer nach f3, Bauer nach d6, Bauer nach d4, Bauer nimmt d4, Springer nimmt d4, Springer nach f6, Springer nach c3, Bauer nach a6, Läufer nach e3, Bauer nach e5, Springer nach b3, Läufer nach e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "Nun geht die Linie weiter, Bauer nach f3, Läufer nach e7, Dame nach d2, kurze Rochade, lange Rochade, Springer nach bd7, Bauer nach g4, Bauer nach b5.",
    "White prepares a kingside assault with pawn to f3.":
      "Weiß bereitet einen Angriff am Königsflügel mit Bauer nach f3 vor.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "Schwarz entwickelt ruhig den Läufer nach e7, dann bringt Weiß die Dame nach d2.",
    "Black castles kingside and White castles queenside.":
      "Schwarz rochiert kurz und Weiß rochiert lang.",
    "Now the battle lines are drawn.":
      "Jetzt sind die Fronten gezogen.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "Schwarz entwickelt den Springer nach bd7 und Weiß beginnt den berühmten Bauernsturm mit Bauer nach g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "Schwarz antwortet mit Bauer nach b5, und da ist sie, die Najdorf ist zum Leben erwacht.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "Weiß sammelt Kräfte am Königsflügel, Schwarz stürmt am Damenflügel, und beide bereiten etwas ziemlich Gefährliches vor.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Also dann, folgt den Zügen genau, bleibt wachsam und genießt diese prächtige Sicilian-Linie.",
  },
  pt: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Certo — Scotch Gambit. Começa como uma abertura aberta a sério: e4, e5, cavalos para fora, e as Brancas batem no centro com d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Quando as Pretas tomam em d4, as Brancas podem deixar o peão e plantar o bispo em c4. É o gambito — desenvolver depressa, apontar a f7 e pôr as Pretas sob pressão antes de arrumarem a posição.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "A família Scotch recebeu o nome daquelas partidas por correspondência Edinburgh–London dos anos 1820. Os amadores ainda gostam desta linha porque o tabuleiro abre e os planos são concretos — não um longo aperto silencioso.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Pega no chá. Pratica comigo os lances de livro — eu mantenho-te no verdadeiro caminho do Scotch Gambit.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Muito bem — bem-vindo à Linha 1. Professor Potato Pie, ao teu serviço.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "Neste pack destilámos o gambito em dez linhas escolhidas com cuidado.",
    "10 lines from Opening Lab.":
      "10 linhas do Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Aprende-os e não vais apenas sobreviver à teoria. Vais devolver os lances certos com confiança, manter o equilíbrio e ficar firme na partida.",
    "You get 10 lines from Opening Lab.":
      "Recebes 10 linhas do Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Quando as Pretas falham, vais aprender a ver porque o lance é defeituoso, escolher a continuação precisa, converter o erro numa vantagem clara e, por vezes, num xeque-mate requintado.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Naturalmente, as Pretas têm mais de dez formas de jogar. Vê isto como um manual curto, não como uma enciclopédia — a lógica dos lances, não apenas uma sequência para memorizar.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Completa o pack e o Scotch Gambit vai parecer familiar sempre que aparecer. Vais reconhecer os marcos, entender os planos e ter uma base firme para levar o estudo mais longe.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Aproveita. Leva o teu tempo, percorre cada linha, e encontro-te no tabuleiro.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Muito bem, agora as armadilhas de abertura. Estas linhas são muito divertidas e, por vezes, apanham um adversário desprevenido completamente de surpresa. Só por isso vale a pena conhecê-las.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Mas há um ponto mais sério. Estudar armadilhas ensina a reconhecer os sinais de alerta, e ficas muito menos propenso a cair numa tu mesmo.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Percorre cada linha, capta a ideia e desfruta dos pequenos mecanismos táticos, tão elegantes.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Usa-as com critério, compreende-as a sério e, quando a ocasião surgir, deixa a precisão fazer o trabalho.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Experimenta, diverte-te, e agora acho que é hora de uma empada de batata. Aproveita.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Muito bem, bem-vindo à Linha 1. Isto é Legal's Mate, com o nome de Monsieur de Légal, um jogador francês do século XVIII.",
    "White opens with the king's pawn, e4.": "As Brancas abrem com o peão de rei, e4.",
    "Black answers symmetrically with e5.": "As Pretas respondem de forma simétrica com e5.",
    "Knight to f3 attacks that pawn.": "Cavalo para f3 ataca esse peão.",
    "Black defends it with d6, which is the Philidor Defence.":
      "As Pretas defendem-no com d6, que é a Defesa Philidor.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "O bispo das Brancas vem a c4 e olha a casinha fraca f7.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "O bispo das Pretas vai a g4 e crava o cavalo contra a dama.",
    "White calmly develops, knight to c3.": "As Brancas desenvolvem com calma, cavalo para c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "As Pretas jogam g6. É um lance lento, e agora a armadilha está pronta.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "O cavalo toma em e5! Esse cavalo só estava cravado contra a dama, não contra o rei, por isso está perfeitamente livre para mover-se.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "As Pretas não resistem e tomam a dama em d1. É a captura gananciosa, e é fatal.",
    "Bishop takes f7, check!": "O bispo toma em f7, xeque!",
    "The king has only one square to go to, e7.": "O rei só tem uma casa, e7.",
    "Knight to d5, and that's checkmate.": "Cavalo para d5, e isso é xeque-mate.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "Dois cavalos e um bispo venceram todo o exército preto. A dama, as torres e o bispo em d1 das Pretas continuam no tabuleiro, e nenhum pode ajudar.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Lembra-te: quando oferecem uma dama de graça tão cedo, olha bem à volta antes de a tomar.",
    "Now over to you. Practise it until your knights know the way.":
      "Agora és tu. Pratica até os teus cavalos saberem o caminho.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "Ah, olá outra vez. Professor Potato Pie, chá na mão. Hoje olhamos para a Defesa Caro-Kann, uma abertura esplendidamente resistente, de excelentes maneiras e com cotovelos surpreendentemente afiados.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "Começa com e4 c6, e toma o nome de Horatio Caro e Marcus Kann, dois jogadores do século XIX cujo trabalho analítico deu identidade a esta defesa venerável.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "A premissa estratégica é admiravelmente económica. As Pretas preparam d5, desafiando de imediato o centro das Brancas, e deixam livre o bispo de casas claras em vez de o prender atrás da cadeia de peões.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "A Caro-Kann é sólida, paciente e sã de estrutura, mas não confundas compostura com passividade. Por baixo desse exterior respeitável há uma bela coleção de contragolpes, sobretudo quando as Brancas ficam ambiciosas demais.",
    "You'll study 10 lines from Opening Lab.":
      "Vais estudar 10 linhas do Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "Estas são 10 linhas do Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "Em Practice dou dicas onde precisares. Em Test a ajuda desaparece: ficas só tu, a posição e o teu critério.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Cada linha termina onde acaba a linha de livro preparada. Depois não há continuação contra o computador.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "O objetivo não é continuar sem rumo, mas absorver os lances, compreender as ideias e reconhecer os padrões quando voltares ao tabuleiro.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Muito bem. Chá servido, peças prontas. Vamos começar.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Muito bem, bem-vindo à Linha 1, a Variante do Avanço. As Brancas reclamam o centro com e4.",
    "We answer c6, preparing the thematic d5 advance.":
      "Respondemos c6, a preparar o avanço temático d5.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "As Brancas estabelecem um centro largo com d4, e desafiamo-lo de imediato com d5.",
    "White pushes on to e5, gaining space.": "As Brancas avançam até e5 e ganham espaço.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Antes de fechar a cadeia de peões com e6, o nosso bispo escapa para f5. Isso, no fundo, é a primeira boa arrumação da Caro-Kann. O bispo sai antes de a porta fechar.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "Segue-se cavalo f3, depois e6. Com o bispo já desenvolvido em segurança, e6 fica inteiramente confortável.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "As Brancas escolhem a montagem calma e sensata de bispo e2, um sistema popularizado pelo grande mestre inglês Nigel Short.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "Atacamos com c5, a golpear a base da cadeia de peões branca em d4.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "As Brancas rocam, e cavalo c6 junta mais uma peça à pressão.",
    "White reinforces d4 with c3.": "As Brancas reforçam d4 com c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "Trocamos peões em d4, abrimos a coluna c e damos ao nosso contrajogo uma via útil.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "O outro cavalo desenvolve-se para e7, a caminho de f5, onde pode voltar a questionar d4.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "As Brancas jogam cavalo c3, e o nosso bispo aplica a cravada a partir de g4.",
    "White answers with knight e1, breaking the pin.":
      "As Brancas respondem com cavalo e1 e quebram a cravada.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Por isso trocamos o útil bispo branco em e2. Recapturar com o cavalo mantém d4 bem defendido.",
    "Our knight settles on f5, still eyeing d4.":
      "O nosso cavalo instala-se em f5, ainda de olho em d4.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "As Brancas protegem-no com bispo e3, e nós desenvolvemos com calma o bispo para e7, prontos para rocar.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "O resultado é uma posição igualada com um plano coerente. Mantém a pressão sobre d4 e usa a coluna c com propósito.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "Não é preciso fogo de artifício: só estrutura sã, pressão paciente e cada peça bem empregue.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "Agora és tu. Repete a linha até os lances parecerem menos memória e mais bom senso.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Muito bem, aqui é o Professor Potato Pie, chá na mão, e hoje damos uma breve olhada no Sistema de Londres.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "A abertura ficou intimamente ligada ao Grande Torneio de Londres de 1922, onde esta estrutura fiável chamou mais atenção.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Certo, normalmente começa com peão a d4, cavalo a f3 e bispo a f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Depois vem peão a e3, peão a c3, cavalo a d2, bispo a d3 e o roque pequeno.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "A ordem exacta pode mudar, mas essa formação familiar é o coração do Sistema de Londres.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "É uma abertura sólida e sensata, jogada tanto por jogadores de clube como por grandes mestres.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Certo, aproveita para te familiarizares mais com o Sistema de Londres e vamos ver como as peças encaixam.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Muito bem, vamos ver a primeira linha do nosso pack de aprendizagem do Londres.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Esta é a pinça de Londres, calma no início, mas há método em cada lance.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Jogamos peão a d4 e as pretas respondem com peão a d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Bispo a f4, cavalo a f6, peão a e3, e as pretas golpeiam com peão a c5.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Construímos a pirâmide familiar com peão a c3, as pretas desenvolvem o cavalo a c6.",
    "Knight to d2 and black plays pawn to e6.": "Cavalo a d2 e as pretas jogam peão a e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "O nosso outro cavalo chega a f3, enquanto o bispo das pretas chega a d6.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Recolhemos o nosso bispo a g3, mantendo-o útil e seguro.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "As pretas rocam no flanco do rei, colocamos o outro bispo em d3, as pretas jogam peão a b6 e agora plantamos o cavalo em e5, um esplêndido posto avançado central.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Bispo a b7, rocamos no flanco do rei, as pretas colocam a dama em c7 e completamos a pinça com peão a f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "Aí está, uma posição compacta de Londres, com o centro firmemente vigiado e as nossas peças a começar a olhar para o flanco do rei.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Repete-a até a tua mão conhecer o caminho e o teu adversário se perguntar quando a abertura calma se tornou um ataque.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Muito bem, aqui está Professor Potato Pie, chá na mão, e hoje encontramos uma das aberturas mais antigas e elegantes do xadrez, a abertura italiana.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "As suas ideias foram estudadas pelos mestres italianos há mais de quatro séculos, e a abertura ainda aparece hoje em todos os níveis do xadrez.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "As Brancas começam com peão para e4, e as Pretas respondem peão para e5, cavalo para f3, cavalo para c6, e depois bispo para c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "Esse bispo aponta para f7, a casinha delicada ao lado do rei preto.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "Daqui, as Pretas respondem habitualmente com bispo para c5, entrando no Giuoco Piano, ou cavalo para f6, chegando à Defesa dos Dois Cavalos.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "A abertura italiana é clássica, viva, e assenta no desenvolvimento natural, no controlo do centro e nas possibilidades de ataque.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Certo, aproveita para te familiarizares mais com a abertura italiana, e vamos ver para onde nos leva aquele bispo em c4.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Muito bem, bem-vindo à Linha 1 do nosso pack de aprendizagem da abertura italiana.",
    "This is the quieter Italian.": "Esta é a italiana mais calma.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "Não é preciso pegar fogo às cortinas quando uma preparação cuidadosa chega perfeitamente.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Começamos com peão a e4, e as pretas respondem peão a e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "Cavalo a f3, cavalo a c6, bispo a c4, e as pretas desenvolvem o bispo a c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "Os dois bispos ocupam os seus postos clássicos e vigiam o centro.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Jogamos peão a c3, a preparar um futuro peão a d4.",
    "Black develops knight to f6 and places pressure on e4.":
      "As pretas desenvolvem o cavalo a f6 e pressionam e4.",
    "Pawn to d3, pawn to d6.": "Peão a d3, peão a d6.",
    "Both sides secure the centre before making any grand declarations.":
      "Ambos os lados asseguram o centro antes de quaisquer grandes declarações.",
    "We castle king side.": "Rocamos no flanco do rei.",
    "Black plays pawn to a6.": "As pretas jogam peão a a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Respondemos peão a a4, ganhando um pouco de espaço no flanco da dama, e o bispo instala-se em a7.",
    "Knight to d2 and black castles king side.":
      "Cavalo a d2 e as pretas rocam no flanco do rei.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Jogamos peão a h3, impedindo que um bispo se torne incómodo em g4, e dando ao nosso rei uma casa útil para respirar.",
    "Black's knight moves to e7.": "O cavalo das pretas move-se para e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "Torre a e1 reforça o e4, e o cavalo continua até g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "Aqui estamos, uma posição italiana sólida, com cada peça a preparar-se para um trabalho útil.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Continua a desenvolver, vigia o centro e fica pronto para a ruptura d4 quando chegar o momento.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Repete a linha até as jogadas parecerem tão naturais como pôr a chaleira ao lume.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Muito bem, aqui está Professor Potato Pie, chá bem feito, e hoje apresentamos uma das grandes aberturas clássicas, o gambito da dama.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "A abertura aparece em escritos de xadrez desde o final do século XV, e gerações de jogadores distintos usaram-na para disputar o centro.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "As brancas começam com peão a d4, e as negras respondem peão a d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Depois as brancas jogam peão a c4, desafiando o peão central negro e oferecendo o peão de c.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "Chama-se gambito, embora as brancas possam normalmente recuperar o peão se as negras o aceitarem,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Portanto isto é menos uma doação imprudente e mais um convite estratégico, servido com educação mas com segundas intenções.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "A partir daqui, as negras podem aceitar o peão ou recusá-lo e manter um centro sólido.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Bem, desfruta de te familiarizares mais com o gambito da dama e vejamos o que esse pequeno peão de c aventureiro pode persuadir as negras a fazer.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Muito bem, bem-vindo à Linha 1 do nosso pack de aprendizagem do gambito da dama.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "Isto é xadrez clássico a sério: bases firmes, desenvolvimento paciente e nenhuma mobília a voar pela sala.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Começamos com peão a d4 e as negras respondem peão a d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Peão a c4 desafia o centro e as negras respondem peão a e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "Isto é o gambito da dama recusado. As negras sustentam o peão de d5 em vez de aceitar a nossa oferta.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "Cavalo a c3, cavalo a f6, bispo a g5 cria o cravamento e as negras desenvolvem com calma o bispo a e7.",
    "We play pawn to e3 and black castles kingside.":
      "Jogamos peão a e3 e as negras rocam no flanco do rei.",
    "Knight to f3, knight to d7.": "Cavalo a f3, cavalo a d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Torre a c1 coloca a torre na coluna c enquanto as negras jogam peão a c6 e reforçam a estrutura central.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Bispo a d3 e as negras resolvem agora a tensão com peão de d5 toma c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "O nosso bispo toma c4, recuperando o peão com desenvolvimento.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "O cavalo negro vai a d5 e ocupa uma casa central forte.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Trocamos com bispo toma e7 e a dama negra recaptura em e7.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "Aí está, uma posição equilibrada do gambito da dama, com desenvolvimento sensato e ainda muito jogo no centro.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Aprende a estrutura, entende as trocas e deixa a posição dizer-te quando é hora de avançar.",
    "Very civilised and quietly ambitious.": "Muito civilizado e discretamente ambicioso.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Muito bem, aqui Professor Potato Pie, deixo-te a postos, e hoje encontramos a defesa francesa: quais são as respostas mais resistentes das Negras ao peão do rei?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "As Brancas começam com peão para e4, nós respondemos peão para e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "As Brancas reclamam mais espaço com peão para d4 e nós golpeamos de imediato com peão para d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "A abertura tirou o nome de uma partida por correspondência entre Londres e Paris em 1834, quando a equipa de Paris empregou a defesa com sucesso.",
    "Its character is patient, but hardly passive.": "O seu carácter é paciente, mas dificilmente passivo.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "As Negras constroem uma sólida cadeia de peões, convidam as Brancas a declarar as intenções e depois desafiam o centro com lances como peão para c5 e, quando o momento chega, peão para f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "O nosso bispo de casas claras pode exigir um pouco de diplomacia, mas isso faz parte da arquitectura subtil da abertura.",
    "Solid, combative and rich in counterplay.": "Sólida, combativa e rica em contrajogo.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "A francesa não precipita a discussão: ganha-a, uma pergunta precisa de cada vez.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "Portanto acomoda-te, fica de olho nas rupturas de peão e aproveita para te familiarizares mais com a defesa francesa.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "Muito bem, bem-vindo à Linha 1 do nosso pacote de aprendizagem da defesa francesa.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "O título correcto é a defesa francesa, variante Winawer, linha principal posicional do avanço, e estamos a treiná-la do lado das Negras.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "As Brancas começam com peão para e4, nós respondemos peão para e6, as Brancas tomam o centro com peão para d4 e nós desafiamo-lo com peão para d5.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "Cavalo para c3, depois bispo para b4: isso anuncia a Winawer.",
    "We pin the knight and ask white how ambitious they're feeling.": "Cravamos o cavalo e perguntamos às Brancas quão ambiciosas se sentem.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "As Brancas avançam o peão para e5, nós contra-atacamos de imediato com peão para c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "As Brancas jogam peão para a3, desafiando o nosso bispo, por isso bispo toma c3, xeque.",
    "White recaptures with the b-pawn to c3.": "As Brancas recapturam com o peão de b para c3.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "As Brancas ganharam o par de bispos e um centro amplo, mas aceitaram peões de c dobrados em troca.",
    "That trade-and-balance is the very grammar of the Winawer.": "Essa troca e esse equilíbrio são a própria gramática da Winawer.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.":
      "Desenvolvemos o cavalo para e7, as Brancas desenvolvem o cavalo para f3 e o nosso bispo vai para d7.",
    "White plays pawn to a4, restraining queen side expansion.": "As Brancas jogam peão para a4, contendo a expansão na ala da dama.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Respondemos dama para a5, aplicando pressão sobre c3 e ajudando a abrir caminho para o roque na ala da dama.",
    "Bishop to d2 and our knight develops to c6.": "Bispo para d2 e o nosso cavalo desenvolve-se para c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "As Brancas colocam o bispo em d3, olhando de forma bastante indelicada para h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "Avançamos o peão para c4, ganhando espaço e mandando esse bispo de volta para e2.",
    "Now comes pawn to f6, the characteristic French lever.": "Agora vem peão para f6, a alavanca característica da francesa.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.":
      "Não estamos apenas a admirar o centro das Brancas: estamos a pedir-lhe que apresente as suas credenciais.",
    "White castles king side, black castles queen side.": "As Brancas rocam na ala do rei, as Negras rocam na ala da dama.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "Os reis estão agora instalados em alas opostas, a posição está esplendidamente desequilibrada e o plano das Negras está claro.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "Desafia o peão de e5, abre linhas úteis e gera actividade na ala da dama com verdadeiro propósito.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Essa é a Winawer posicional: sólida na construção, combativa na intenção e com uma dose considerável de electricidade oculta.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.": "A tua vez: treina-a até a ordem dos lances parecer menos memória e mais senso comum.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Bem aí, meus amores. Big Red aqui. E hoje vamos olhar a sério para a Ruy Lopez,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "também conhecida como a abertura espanhola. Há história nesta. Ela toma o nome",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "de Ruy Lopez de Segura, um padre espanhol e escritor de xadrez que estudou a abertura no",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "século XVI. As Brancas começam com peão para e4. As Negras respondem peão para e5. Cavalo para f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "ataca esse peão e as Negras defendem-no com cavalo para c6. Depois vem o bispo para b5. E aí",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "está. A Ruy Lopez. O bispo não ganha de imediato o peão de e5. Está a aplicar",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "pressão ao cavalo que o guarda, deixando às Negras um problema quieto mas persistente.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "Deste começo elegante cresce uma das maiores famílias de aberturas do xadrez.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Algumas linhas são calmas e de manobra, outras podem animar-se antes de teres tempo de pousar",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "o chá. É clássica, subtil e cheia de ideias estratégicas a sério. Velha, digna e ainda",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "cheia de possibilidades. Um pouco como a própria Londres. Por isso fica de olho no centro,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "cuida das tuas peças e disfruta de ficar mais familiar com a Ruy Lopez. Big Red vê-te por aí.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "Muito bem, meus amores, Big Red está de volta ao tabuleiro e esta é a linha 1 do nosso pack de aprendizagem da Ruy Lopez, a Defesa Morphy, variante fechada Breyer.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Jogamos com as peças brancas e isto é uma verdadeira obra-prima estratégica.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "As Brancas começam com peão para e4, as Pretas respondem peão para e5, Nf3 ataca o peão e as Pretas defendem-no com Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 e a Ruy Lopez está no tabuleiro. As Pretas jogam peão para a6, anunciando a Defesa Morphy",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "e fazem ao nosso bispo uma pergunta muito direta. Recuamos o bispo para a4. As Pretas desenvolvem Nf6,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "fazemos o roque do lado do rei e as Pretas desenvolvem o bispo para e7. A torre para e1 reforça o nosso peão de e4",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "e coloca a torre em frente ao rei preto. As Pretas expandem com peão para b5, por isso o nosso bispo assenta",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "em b3. O peão para d6 dá ao centro preto uma base firme. Jogamos peão para c3,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "preparando o grande avanço central, peão para d4. As Pretas fazem o roque do lado do rei. Agora peão para h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "um lance pequeno e útil que mantém um bispo ou um cavalo longe de g4 e dá ao nosso rei algum ar.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Depois vem o lance que torna a Breyer inconfundível. As Pretas recuam o cavalo para b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "Parece que o cavalo esqueceu por que saiu, mas nada disso. Isto é estratégico",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "reciclagem da mais alta ordem. Atacamos com peão para d4, estabelecendo um centro magnífico. As Pretas",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "reencaminham esse cavalo para d7, onde apoia e5 e liberta o peão de c para o futuro contra-jogo.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "O nosso cavalo da ala da dama desenvolve-se para d2. O bispo preto vai para b7 e aponta a e4. O bispo",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "para c2 preserva o nosso valioso bispo espanhol e aponta para o lado do rei. As Pretas colocam a",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "torre em e8, dando mais apoio ao peão de e5. Por fim, o nosso cavalo desliza para f1. Esse cavalo",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "tem um itinerário esplêndido. De f1 pode viajar para g3, aumentando a pressão sobre f5 e ajudando",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "o ataque do lado do rei a ganhar impulso. Essa é a Breyer fechada. Paciente, sofisticada e",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "absolutamente cheia de vida e energia. As Brancas possuem o espaço central. As Pretas construíram uma posição compacta",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "e preparam o contragolpe. Joga-a com convicção. Aproveita cada manobra",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "e lembra-te: os lances quietos não estão à espera. Estão a carregar a mola.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "A tua vez: treina até que essa viagem do cavalo de b1 para d2 e depois para f1 pareça tão natural como encontrar",
    "your way around London.":
      "o caminho por Londres.",
    "Right then, the Sicilian Defence for Black.":
      "Muito bem, a defesa siciliana para as Pretas.",
    "White starts with 1. e4, claiming the centre.":
      "As Brancas começam com um ponto e4, reclamando o centro.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "As Pretas respondem um ponto c5, golpeando de lado em vez de copiar as Brancas diretamente.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "A ideia é desafiar as ambições centrais das Brancas, desenvolver-se com atividade e criar contrajogo desde o início.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Uma rota comum é 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "Aí está: uma defesa aguda e flexível, com bastante mordida.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Muito bem, bem-vindo à linha 1 da Sicilian, a Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "Esta é uma das respostas mais ambiciosas das pretas ao peão para e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "As brancas abrem com peão para e4, e as pretas golpeiam logo com peão para c5.",
    "White develops knight to f3.":
      "As brancas desenvolvem o cavalo para f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "As pretas jogam peão para d6, e as brancas abrem o centro com peão para d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "As pretas tomam em d4 com o peão de c, as brancas recapturam com cavalo toma d4.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "As pretas desenvolvem o cavalo para f6, e as brancas trazem o outro cavalo para c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Agora vem o famoso lance Najdorf, peão para a6, um lance pequeno e flexível com muito veneno.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "As pretas mantêm a posição adaptável e preparam a expansão na ala da dama.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "A primeira parte da linha é peão para e4, peão para c5, cavalo para f3, peão para d6, peão para d4, peão toma d4, cavalo toma d4, cavalo para f6, cavalo para c3, peão para a6, bispo para e3, peão para e5, cavalo para b3, bispo para e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "Agora a linha continua, peão para f3, bispo para e7, dama para d2, roque pequeno, roque grande, cavalo para bd7, peão para g4, peão para b5.",
    "White prepares a kingside assault with pawn to f3.":
      "As brancas preparam um assalto na ala do rei com peão para f3.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "As pretas desenvolvem com calma o bispo para e7, e então as brancas trazem a dama para d2.",
    "Black castles kingside and White castles queenside.":
      "As pretas rocam no lado do rei e as brancas rocam no lado da dama.",
    "Now the battle lines are drawn.":
      "Agora as linhas de batalha estão traçadas.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "As pretas desenvolvem o cavalo para bd7 e as brancas começam a famosa tempestade de peões com peão para g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "As pretas respondem com peão para b5 e aí está, a Najdorf ganhou vida.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "As brancas reúnem forças na ala do rei, as pretas avançam na ala da dama, e ambos preparam algo bastante perigoso.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Muito bem, acompanhe os lances de perto, mantenha a atenção e aproveite esta excelente linha Sicilian.",
  },
  ru: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Итак — Scotch Gambit. Начинается как настоящая открытая партия: e4, e5, кони выходят, затем белые бьют по центру ходом d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Когда чёрные берут на d4, белые могут оставить пешку и поставить слона на c4. Это и есть гамбит — быстро развиваться, целиться на f7 и давить на чёрных, пока они не наведут порядок.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "Семейство Scotch получило имя от тех партий по переписке Edinburgh–London в 1820-х годах. Любители до сих пор любят эту линию: доска открывается, планы конкретны — не долгое тихое удушение.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Бери чай. Тренируй со мной книжные ходы — я удержу тебя на настоящей тропе Scotch Gambit.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Итак — добро пожаловать на линию 1. Professor Potato Pie к твоим услугам.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "В этом учебном паке мы свели гамбит к десяти тщательно выбранным линиям.",
    "10 lines from Opening Lab.":
      "10 линий от Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Выучи их, и ты не просто переживёшь теорию. Ты будешь уверенно возвращать верные ходы, держать равновесие и твёрдо оставаться в партии.",
    "You get 10 lines from Opening Lab.":
      "Ты получаешь 10 линий от Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Когда чёрные ошибаются, ты научишься видеть, почему ход плох, выбирать точное продолжение, обращать ошибку в ясный перевес и порой в довольно изысканный мат.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Конечно, у чёрных больше десяти способов играть. Считай это компактным кратким курсом, а не исчерпывающей энциклопедией — логика ходов, а не просто последовательность для заучивания.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Пройди пак, и Scotch Gambit будет выглядеть знакомым, когда бы он ни появился. Ты узнаешь ориентиры, поймёшь планы и получишь твёрдую опору, чтобы учиться дальше.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Наслаждайся. Не спеши, пройди каждую линию, и увидимся у доски.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Итак, теперь дебютные ловушки. Эти линии очень забавны и порой застают ничего не подозревающего соперника совсем врасплох. Уже поэтому их стоит знать.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Но есть и более серьёзный смысл. Изучение ловушек учит узнавать предупреждающие знаки, и ты гораздо реже сам в них забредёшь.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Пройди каждую линию, ухвати идею и насладись изящными маленькими тактическими механизмами.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Применяй их с суждением, пойми их по-настоящему, и когда появится случай, пусть точность сделает работу.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Попробуй, повеселись, и теперь, кажется, время картофельного пирога. Приятного.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Итак, добро пожаловать на линию 1. Это Legal's Mate, названный в честь Monsieur de Légal, французского игрока XVIII века.",
    "White opens with the king's pawn, e4.": "Белые открывают королевской пешкой, e4.",
    "Black answers symmetrically with e5.": "Чёрные отвечают симметрично ходом e5.",
    "Knight to f3 attacks that pawn.": "Конь на f3 атакует эту пешку.",
    "Black defends it with d6, which is the Philidor Defence.":
      "Чёрные защищают её ходом d6 — это защита Philidor.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "Слон белых приходит на c4 и смотрит на слабое поле f7.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "Слон чёрных идёт на g4 и связывает коня против ферзя.",
    "White calmly develops, knight to c3.": "Белые спокойно развиваются, конь на c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "Чёрные играют g6. Медленный ход, и теперь ловушка готова.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "Конь берёт на e5! Этот конь был связан только против ферзя, не против короля, поэтому он совершенно свободен.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "Чёрные не могут удержаться и берут ферзя на d1. Это жадный захват, и он смертелен.",
    "Bishop takes f7, check!": "Слон берёт на f7, шах!",
    "The king has only one square to go to, e7.": "Королю остаётся только одно поле, e7.",
    "Knight to d5, and that's checkmate.": "Конь на d5, и это мат.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "Два коня и один слон победили всю чёрную армию. Ферзь, ладьи и слон на d1 у чёрных всё ещё на доске, и никто из них не может помочь.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Запомни: если так рано предлагают ферзя даром, хорошо осмотрись, прежде чем брать.",
    "Now over to you. Practise it until your knights know the way.":
      "Теперь ты. Тренируй, пока твои кони не запомнят дорогу.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "А, здравствуй снова. Professor Potato Pie, чай в руке. Сегодня мы обращаемся к защите Caro-Kann — замечательно стойкому дебюту с отличными манерами и неожиданно острыми локтями.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "Она начинается с e4 c6 и носит имя Horatio Caro и Marcus Kann, двух игроков XIX века, чей анализ дал этой почтенной защите её лицо.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "Стратегическая идея восхитительно экономна. Чёрные готовят d5, сразу оспаривая центр белых, и оставляют белопольного слона свободным, а не запирают его за пешечной цепью.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Caro-Kann солидна, терпелива и структурно здорова, но не принимай спокойствие за пассивность. Под благопристойной оболочкой — отличный набор контратак, особенно если белые становятся слишком амбициозными.",
    "You'll study 10 lines from Opening Lab.":
      "Ты изучишь 10 линий от Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "Это 10 линий от Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "В Practice я дам подсказки там, где они нужны. В Test помощь исчезает: остаёшься ты, позиция и твоё суждение.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Каждая линия кончается там, где кончается подготовленная книжная линия. Дальше нет продолжения против компьютера.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "Цель не в том, чтобы играть дальше без смысла, а в том, чтобы впитать ходы, понять идеи и узнавать узоры, когда ты снова сядешь за доску.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Итак. Чай налит, фигуры готовы. Начнём.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Итак, добро пожаловать на линию 1, вариант продвижения. Белые захватывают центр ходом e4.",
    "We answer c6, preparing the thematic d5 advance.":
      "Мы отвечаем c6, готовя тематическое продвижение d5.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "Белые ставят широкий центр ходом d4, и мы сразу оспариваем его ходом d5.",
    "White pushes on to e5, gaining space.": "Белые идут дальше на e5 и получают пространство.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Прежде чем закрыть пешечную цепь ходом e6, наш слон уходит на f5. В этом, по сути, первая хорошая хозяйственность Caro-Kann. Слон выходит, пока дверь не закрылась.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "Следует конь f3, затем e6. Когда слон уже спокойно развит, e6 вполне удобен.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "Белые выбирают тихий и разумный план слон e2, систему, которую сделал популярной английский гроссмейстер Nigel Short.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "Мы бьём ходом c5, атакуя основание пешечной цепи белых на d4.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "Белые рокируются, и конь c6 добавляет ещё одну фигуру к давлению.",
    "White reinforces d4 with c3.": "Белые укрепляют d4 ходом c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "Мы меняем пешки на d4, открывая линию c и давая нашей контригре полезный путь.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "Второй конь развивается на e7 и идёт на f5, где снова может поставить под вопрос d4.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "Белые играют конь c3, и наш слон ставит связку с g4.",
    "White answers with knight e1, breaking the pin.": "Белые отвечают конём e1 и снимают связку.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Поэтому мы меняем полезного слона белых на e2. Взятие конём оставляет d4 надёжно защищённым.",
    "Our knight settles on f5, still eyeing d4.":
      "Наш конь устраивается на f5 и по-прежнему смотрит на d4.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "Белые защищают его слоном e3, а мы спокойно развиваем слона на e7, готовые к рокировке.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "Получается равная позиция с ясным планом. Держи давление на d4 и осмысленно пользуйся линией c.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "Фейерверк не нужен: только здоровая структура, терпеливое давление и каждая фигура при деле.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "Теперь ты. Повторяй линию, пока ходы не станут меньше похожи на память и больше — на здравый смысл.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Итак, Professor Potato Pie на связи, чай в руке, и сегодня мы коротко смотрим на лондонскую систему.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "Этот дебют тесно связали с большим Лондонским турниром 1922 года, где эта надёжная расстановка привлекла более широкое внимание.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Итак, обычно начинают пешкой на d4, конём на f3 и слоном на f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Затем пешка на e3, пешка на c3, конь на d2, слон на d3 и короткая рокировка.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "Точный порядок может меняться, но эта знакомая расстановка — сердце лондонской системы.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "Это крепкий, разумный дебют, который играли и клубные игроки, и гроссмейстеры.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Итак, приятного знакомства с лондонской системой, и посмотрим, как фигуры складываются вместе.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Итак, посмотрим первую линию в нашем учебном паке по лондонской системе.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Это лондонские тиски, поначалу тихие, но в каждом ходе есть метод.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Мы играем пешку на d4, и чёрные отвечают пешкой на d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Слон на f4, конь на f6, пешка на e3, и чёрные бьют пешкой на c5.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Мы строим знакомую пирамиду пешкой на c3, чёрные развивают коня на c6.",
    "Knight to d2 and black plays pawn to e6.": "Конь на d2, и чёрные играют пешку на e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "Другой наш конь приходит на f3, а слон чёрных приходит на d6.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Мы отводим слона назад на g3, оставляя его полезным и в безопасности.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "Чёрные рокируются в короткую сторону, мы ставим другого слона на d3, чёрные играют пешку на b6, и теперь мы ставим коня на e5, великолепный центральный форпост.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Слон на b7, мы рокируемся в короткую сторону, чёрные ставят ферзя на c7, и мы завершаем тиски пешкой на f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "Вот она, компактная лондонская позиция: центр под твёрдым надзором, а наши фигуры начинают поглядывать в сторону королевского фланга.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Тренируй её, пока рука не узнает маршрут, а соперник не задумается, когда тихий дебют стал атакой.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Итак, здесь Professor Potato Pie, чай в руке, и сегодня мы встречаем один из самых старых и изящных дебютов шахмат, итальянскую партию.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "Её идеи изучали итальянские мастера более четырёх веков назад, и этот дебют по-прежнему встречается на любом уровне шахмат.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "Белые начинают пешкой на e4, и чёрные отвечают пешкой на e5, конём на f3, конём на c6, а затем слоном на c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "Этот слон смотрит на f7, хрупкую маленькую клетку рядом с чёрным королём.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "Отсюда чёрные обычно отвечают слоном на c5, входя в Giuoco Piano, или конём на f6, достигая защиты двух коней.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "Итальянская партия классическая, живая и построена на естественном развитии, контроле центра и атакующих возможностях.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Итак, приятного знакомства с итальянской партией, и посмотрим, куда нас ведёт этот слон на c4.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Итак, добро пожаловать в линию 1 нашего учебного набора по итальянской партии.",
    "This is the quieter Italian.": "Это более спокойная итальянская партия.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "Незачем поджигать шторы, когда тщательная подготовка вполне справится.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Мы начинаем пешкой на e4, и чёрные отвечают пешкой на e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "Конь на f3, конь на c6, слон на c4, и чёрные развивают слона на c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "Оба слона занимают классические посты и зорко следят за центром.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Мы играем пешку на c3, готовя будущую пешку на d4.",
    "Black develops knight to f6 and places pressure on e4.":
      "Чёрные развивают коня на f6 и оказывают давление на e4.",
    "Pawn to d3, pawn to d6.": "Пешка на d3, пешка на d6.",
    "Both sides secure the centre before making any grand declarations.":
      "Обе стороны укрепляют центр, прежде чем делать громкие заявления.",
    "We castle king side.": "Мы рокируемся в короткую сторону.",
    "Black plays pawn to a6.": "Чёрные играют пешку на a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Мы отвечаем пешкой на a4, немного расширяя пространство на ферзевом фланге, и слон располагается на a7.",
    "Knight to d2 and black castles king side.":
      "Конь на d2, и чёрные рокируются в короткую сторону.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Мы играем пешку на h3, не давая слону стать неприятным на g4, и даём королю полезное поле для воздуха.",
    "Black's knight moves to e7.": "Конь чёрных идёт на e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "Ладья на e1 укрепляет e4, и конь продолжает на g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "Вот и она, здоровая итальянская позиция, где каждая фигура готовится к полезной работе.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Продолжай развиваться, следи за центром и будь готов к прорыву d4, когда настанет момент.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Повторяй линию, пока ходы не станут такими же естественными, как поставить чайник.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Итак, это Professor Potato Pie, чай как следует заварен, и сегодня мы представляем один из великих классических дебютов, ферзевый гамбит.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "Этот дебют встречается в шахматных текстах с конца пятнадцатого века, и поколения выдающихся игроков использовали его, чтобы бороться за центр.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "Белые начинают пешкой на d4, и чёрные отвечают пешкой на d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Затем белые играют пешкой на c4, оспаривая центральную пешку чёрных и предлагая пешку c.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "Это называют гамбитом, хотя белые обычно могут вернуть пешку, если чёрные её принимают,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Так что это меньше безрассудный дар и больше стратегическое приглашение, поданное вежливо, но с дальним умыслом.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "Отсюда чёрные могут принять пешку или отказаться и сохранить прочный центр.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Хорошо, получай удовольствие, знакомясь ближе с ферзевым гамбитом, и посмотрим, на что этот предприимчивый маленький пешечный c может уговорить чёрных.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Итак, добро пожаловать на линию 1 нашего учебного пакета ферзевого гамбита.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "Это настоящие классические шахматы: прочный фундамент, терпеливое развитие и никакой мебели, летящей через комнату.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Мы начинаем пешкой на d4, и чёрные отвечают пешкой на d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Пешка на c4 оспаривает центр, и чёрные отвечают пешкой на e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "Это отказанный ферзевый гамбит. Чёрные поддерживают пешку d5, вместо того чтобы принять наше предложение.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "Конь на c3, конь на f6, слон на g5 создаёт связку, и чёрные спокойно развивают слона на e7.",
    "We play pawn to e3 and black castles kingside.":
      "Мы играем пешкой на e3, и чёрные рокируют в короткую сторону.",
    "Knight to f3, knight to d7.": "Конь на f3, конь на d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Ладья на c1 ставит ладью на линию c, пока чёрные играют пешкой на c6 и укрепляют центральную структуру.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Слон на d3, и чёрные снимают напряжение пешкой с d5 бьёт c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "Наш слон бьёт c4, возвращая пешку развитием.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "Конь чёрных идёт на d5 и занимает сильное центральное поле.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Мы размениваемся слоном, бьющим e7, и ферзь чёрных бьёт в ответ на e7.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "Вот она, уравновешенная позиция ферзевого гамбита, с разумным развитием и ещё большой игрой в центре.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Изучи структуру, пойми размены и дай позиции подсказать, когда пора наступать.",
    "Very civilised and quietly ambitious.": "Очень цивилизованно и тихо амбициозно.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Итак, здесь Professor Potato Pie, привожу вас в готовность, и сегодня мы знакомимся с французской защитой: каковы самые стойкие ответы чёрных на королевскую пешку?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "Белые начинают пешкой на e4, мы отвечаем пешкой на e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "Белые захватывают больше пространства пешкой на d4, и мы сразу бьём пешкой на d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "Дебют получил имя по переписочному матчу между Лондоном и Парижем в 1834 году, когда парижская команда успешно применила эту защиту.",
    "Its character is patient, but hardly passive.": "Его характер терпелив, но едва ли пассивен.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "Чёрные строят прочную пешечную цепь, приглашают белых объявить намерения, затем оспаривают центр ходами вроде пешки на c5 и, когда момент созреет, пешки на f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "Нашему белопольному слону может понадобиться немного дипломатии, но это часть тонкой архитектуры дебюта.",
    "Solid, combative and rich in counterplay.": "Надёжно, боевито и богато контригрой.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "Французская не торопит спор: она выигрывает его по одному точному вопросу за раз.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "Так что устраивайтесь, следите за пешечными прорывами и наслаждайтесь тем, как французская защита становится вам ближе.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "Итак, добро пожаловать в линию 1 нашего учебного пакета французской защиты.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "Точное название — французская защита, вариант Winawer, позиционная главная линия продвижения, и мы разбираем её со стороны чёрных.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "Белые начинают пешкой на e4, мы отвечаем пешкой на e6, белые занимают центр пешкой на d4, и мы оспариваем его пешкой на d5.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "Конь на c3, затем слон на b4: это объявляет Winawer.",
    "We pin the knight and ask white how ambitious they're feeling.": "Мы связываем коня и спрашиваем белых, насколько амбициозно они себя чувствуют.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "Белые продвигают пешку на e5, мы немедленно контратакуем пешкой на c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "Белые играют пешкой на a3, вызывая нашего слона, поэтому слон берёт c3, шах.",
    "White recaptures with the b-pawn to c3.": "Белые бьют в ответ пешкой b на c3.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.": "Белые получили пару слонов и широкий центр, но взамен приняли сдвоенные пешки c.",
    "That trade-and-balance is the very grammar of the Winawer.": "Этот размен и равновесие — сама грамматика Winawer.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.": "Мы развиваем коня на e7, белые развивают коня на f3, и наш слон идёт на d7.",
    "White plays pawn to a4, restraining queen side expansion.": "Белые играют пешкой на a4, сдерживая расширение на ферзевом фланге.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Мы отвечаем ферзём на a5, давим на c3 и помогаем освободить путь для рокировки на ферзевый фланг.",
    "Bishop to d2 and our knight develops to c6.": "Слон на d2, и наш конь развивается на c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "Белые ставят слона на d3, довольно невежливо поглядывая на h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "Мы продвигаем пешку на c4, захватывая пространство и отправляя этого слона назад на e2.",
    "Now comes pawn to f6, the characteristic French lever.": "Теперь пешка на f6, характерный рычаг французской защиты.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.": "Мы не просто любуемся центром белых: мы просим его предъявить свои полномочия.",
    "White castles king side, black castles queen side.": "Белые рокируются в короткую сторону, чёрные рокируются в длинную.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "Короли теперь стоят на противоположных флангах, позиция великолепно неравновесна, и план чёрных ясен.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "Оспаривай пешку e5, открывай полезные линии и создавай игру на ферзевом фланге с ясным замыслом.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Это позиционная Winawer: прочная по построению, боевитая по намерению и несущая немалый запас скрытого электричества.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.":
      "Твой ход: повторяй её, пока порядок ходов не станет меньше похож на память и больше — на здравый смысл.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Вот здесь, мои дорогие. Big Red на связи. И сегодня мы как следует смотрим на Ruy Lopez,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "известную также как испанская партия. В ней есть история. Она берёт имя",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "от Ruy Lopez de Segura, испанского священника и шахматного автора, который изучал этот дебют в",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "XVI веке. Белые начинают пешкой на e4. Чёрные отвечают пешкой на e5. Конь на f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "атакует эту пешку, и чёрные защищают её конём на c6. Затем слон на b5. И вот",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "она. Ruy Lopez. Слон не выигрывает сразу пешку e5. Он оказывает",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "давление на коня, который её стережёт, и оставляет чёрным тихую, но настойчивую задачу.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "Из этого изящного начала вырастает одно из самых великих дебютных семейств в шахматах.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Одни варианты спокойны и маневренны, другие могут ожить раньше, чем вы успеете поставить",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "чай. Она классическая, тонкая и полна настоящих стратегических идей. Старая, достойная и всё ещё",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "полная возможностей. Немного как сам Лондон. Так что следите за центром,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "берегите фигуры и радуйтесь, узнавая Ruy Lopez ближе. Big Red ещё увидится с вами.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "Ну что ж, мои дорогие, Big Red снова у доски, и это линия 1 нашего учебного пакета Ruy Lopez, защита Морфи, закрытый вариант Брейера.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Мы играем белыми фигурами, и это настоящий стратегический шедевр.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "Белые начинают пешкой на e4, чёрные отвечают пешкой на e5, Nf3 атакует пешку, и чёрные защищают её ходом Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5, и Ruy Lopez уже на доске. Чёрные играют пешкой на a6, объявляя защиту Морфи",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "и задают нашему слону очень прямой вопрос. Мы отступаем слоном на a4. Чёрные развивают Nf6,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "мы рокируемся в короткую сторону, и чёрные развивают слона на e7. Ладья на e1 укрепляет нашу пешку e4",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "и ставит ладью напротив чёрного короля. Чёрные расширяются пешкой на b5, и наш слон располагается",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "на b3. Пешка на d6 даёт центру чёрных прочное основание. Мы играем пешкой на c3,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "готовя грандиозное центральное продвижение, пешку на d4. Чёрные рокируются в короткую сторону. Теперь пешка на h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "полезный маленький ход, который не пускает слона или коня на g4 и даёт нашему королю немного воздуха.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Затем приходит ход, который делает Брейера безошибочным. Чёрные отступают конём на b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "Кажется, будто конь забыл, зачем вышел, но ничуть. Это стратегическая",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "переработка высшего порядка. Мы бьём пешкой на d4, создавая великолепный центр. Чёрные",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "переводят этого коня на d7, где он поддерживает e5 и освобождает пешку c для будущего контригры.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "Наш ферзевый конь развивается на d2. Слон чёрных идёт на b7 и целится на e4. Слон",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "на c2 сохраняет нашего ценного испанского слона и смотрит в сторону королевского фланга. Чёрные ставят",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "ладью на e8, ещё больше поддерживая пешку e5. Наконец наш конь скользит на f1. У этого коня",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "прекрасный маршрут. С f1 он может отправиться на g3, усиливая давление на f5 и помогая",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "атаке на королевском фланге набрать ход. Это закрытый Брейер. Терпеливый, изысканный и",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "абсолютно полный жизни и энергии. Белые владеют центральным пространством. Чёрные построили компактную",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "позицию и готовят контрудар. Играйте с убеждённостью. Наслаждайтесь каждым манёвром",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "и помните: тихие ходы не простаивают. Они взводят пружину.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "Теперь вы: повторяйте, пока путь этого коня с b1 на d2 и далее на f1 не станет таким же естественным, как найти",
    "your way around London.":
      "дорогу по Лондону.",
    "Right then, the Sicilian Defence for Black.":
      "Итак, сицилианская защита за чёрных.",
    "White starts with 1. e4, claiming the centre.":
      "Белые начинают с одного пункта e4 и претендуют на центр.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "Чёрные отвечают одним пунктом c5, ударяя с фланга, а не копируя белых напрямую.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "Идея в том, чтобы оспорить центральные амбиции белых, активно развиваться и создавать контригру с самого начала.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Обычный маршрут: 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "Вот так: острая, гибкая защита с изрядным запасом зуба.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Итак, добро пожаловать в линию 1 Sicilian, Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "Это один из самых амбициозных ответов чёрных на пешку на e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "Белые открывают пешкой на e4, и чёрные сразу бьют пешкой на c5.",
    "White develops knight to f3.":
      "Белые развивают коня на f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "Чёрные играют пешку на d6, и белые открывают центр пешкой на d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "Чёрные берут на d4 пешкой c, белые отыгрывают конём берёт d4.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "Чёрные развивают коня на f6, и белые приводят другого коня на c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Теперь знаменитый ход Najdorf, пешка на a6, гибкий маленький ход с большим ядом.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "Чёрные сохраняют позицию гибкой и готовят расширение на ферзевом фланге.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "Первая часть линии: пешка на e4, пешка на c5, конь на f3, пешка на d6, пешка на d4, пешка берёт d4, конь берёт d4, конь на f6, конь на c3, пешка на a6, слон на e3, пешка на e5, конь на b3, слон на e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "Теперь линия продолжается, пешка на f3, слон на e7, ферзь на d2, короткая рокировка, длинная рокировка, конь на bd7, пешка на g4, пешка на b5.",
    "White prepares a kingside assault with pawn to f3.":
      "Белые готовят штурм королевского фланга пешкой на f3.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "Чёрные спокойно развивают слона на e7, затем белые приводят ферзя на d2.",
    "Black castles kingside and White castles queenside.":
      "Чёрные рокируют в короткую сторону, белые рокируют в длинную.",
    "Now the battle lines are drawn.":
      "Теперь линии боя обозначены.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "Чёрные развивают коня на bd7, и белые начинают знаменитую пешечную бурю пешкой на g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "Чёрные отвечают пешкой на b5, и вот она, Najdorf ожила.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "Белые собирают силы на королевском фланге, чёрные идут на ферзевом, и оба готовят нечто довольно опасное.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Итак, следите за ходами внимательно, не теряйте бдительности и наслаждайтесь этой отличной линией Sicilian.",
  },
  it: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Bene — Scotch Gambit. Inizia come una vera partita aperta: e4, e5, cavalli fuori, poi il Bianco colpisce il centro con d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Quando il Nero prende in d4, il Bianco può lasciare il pedone e piantare l'alfiere in c4. Quello è il gambetto — sviluppare in fretta, puntare a f7 e mettere il Nero sotto pressione prima che sistemi la posizione.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "La famiglia Scotch prende il nome da quelle partite per corrispondenza Edinburgh–London degli anni 1820. I dilettanti amano ancora questa linea perché la scacchiera si apre e i piani sono concreti — non una lunga stretta silenziosa.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Prendi il tè. Pratica con me le mosse di libro — ti terrò sulla vera strada dello Scotch Gambit.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Bene — benvenuto alla Linea 1. Professor Potato Pie, al tuo servizio.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "In questo pack abbiamo distillato il gambetto in dieci linee scelte con cura.",
    "10 lines from Opening Lab.":
      "10 linee da Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Imparale e non ti limiterai a sopravvivere alla teoria. Restituirai le mosse giuste con sicurezza, manterrai l'equilibrio e resterai saldo nella partita.",
    "You get 10 lines from Opening Lab.":
      "Hai 10 linee da Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Quando il Nero sbaglia, imparerai a vedere perché la mossa è difettosa, a scegliere la continuazione precisa, a trasformare l'errore in un chiaro vantaggio e, a volte, in uno scacco matto piuttosto squisito.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Naturalmente il Nero ha più di dieci modi di giocare. Pensalo come un piccolo manuale, non come un'enciclopedia — la logica delle mosse, non solo una sequenza da memorizzare.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Completa il pack e lo Scotch Gambit ti sembrerà familiare ogni volta che appare. Riconoscerai i punti di riferimento, capirai i piani e avrai una base solida per studiare oltre.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Goditelo. Prenditi il tempo, percorri ogni linea, e ci vediamo alla scacchiera.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Bene, ora le trappole di apertura. Queste linee sono molto divertenti e, a volte, colgono un avversario impreparato del tutto alla sprovvista. Solo per questo vale la pena conoscerle.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Ma c'è un punto più serio. Studiare le trappole insegna a riconoscere i segnali d'allarme, così è molto meno probabile che ci caschi tu.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Percorri ogni linea, cogli l'idea e goditi gli eleganti piccoli meccanismi tattici.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Usale con giudizio, capiscile davvero e, quando si presenta l'occasione, lascia che la precisione faccia il lavoro.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Prova, divertiti, e ora credo sia l'ora di una torta di patate. Buon divertimento.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Bene, benvenuto alla Linea 1. Questo è Legal's Mate, chiamato così da Monsieur de Légal, un giocatore francese del Settecento.",
    "White opens with the king's pawn, e4.": "Il Bianco apre con il pedone di re, e4.",
    "Black answers symmetrically with e5.": "Il Nero risponde in modo simmetrico con e5.",
    "Knight to f3 attacks that pawn.": "Cavallo in f3 attacca quel pedone.",
    "Black defends it with d6, which is the Philidor Defence.":
      "Il Nero lo difende con d6, che è la Difesa Philidor.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "L'alfiere del Bianco arriva in c4 e guarda la casella debole f7.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "L'alfiere del Nero va in g4 e inchioda il cavallo contro la donna.",
    "White calmly develops, knight to c3.": "Il Bianco sviluppa con calma, cavallo in c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "Il Nero gioca g6. È una mossa lenta, e ora la trappola è pronta.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "Il cavallo prende in e5! Quel cavallo era inchiodato solo contro la donna, non contro il re, quindi è perfettamente libero di muoversi.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "Il Nero non resiste e prende la donna in d1. È la cattura avida, ed è fatale.",
    "Bishop takes f7, check!": "L'alfiere prende in f7, scacco!",
    "The king has only one square to go to, e7.": "Al re resta una sola casa, e7.",
    "Knight to d5, and that's checkmate.": "Cavallo in d5, e quello è scacco matto.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "Due cavalli e un alfiere hanno battuto l'intero esercito nero. La donna, le torri e l'alfiere in d1 del Nero sono ancora sulla scacchiera, e nessuno può aiutare.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Ricorda: quando ti offrono una donna gratis così presto, guarda bene intorno prima di prenderla.",
    "Now over to you. Practise it until your knights know the way.":
      "Ora tocca a te. Praticala finché i tuoi cavalli non conoscono la strada.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "Ah, ciao di nuovo. Professor Potato Pie, tè in mano. Oggi ci occupiamo della Difesa Caro-Kann, un'apertura splendidamente tenace, di ottime maniere e con gomiti sorprendentemente aguzzi.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "Inizia con e4 c6, e prende il nome da Horatio Caro e Marcus Kann, due giocatori dell'Ottocento il cui lavoro analitico ha dato identità a questa venerabile difesa.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "La premessa strategica è mirabilmente economica. Il Nero prepara d5, sfidando subito il centro del Bianco, e tiene libero l'alfiere dei campi chiari invece di rinchiuderlo dietro la catena di pedoni.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "La Caro-Kann è solida, paziente e sana di struttura, ma non scambiare la compostezza per passività. Sotto quell'esterno rispettabile c'è una bella raccolta di contrattacchi, specie quando il Bianco diventa troppo ambizioso.",
    "You'll study 10 lines from Opening Lab.":
      "Studierai 10 linee da Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "Queste sono 10 linee da Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "In Practice darò suggerimenti dove ti servono. In Test l'aiuto sparisce: resti tu, la posizione e il tuo giudizio.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Ogni linea finisce dove finisce la linea di libro preparata. Dopo non c'è continuazione contro il computer.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "Lo scopo non è continuare senza meta, ma assorbire le mosse, capire le idee e riconoscere gli schemi quando torni alla scacchiera.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Bene. Tè sistemato, pezzi pronti. Cominciamo.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Bene, benvenuto alla Linea 1, la Variante dell'Avanzata. Il Bianco rivendica il centro con e4.",
    "We answer c6, preparing the thematic d5 advance.":
      "Rispondiamo c6, preparando l'avanzata tematica d5.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "Il Bianco stabilisce un centro ampio con d4, e lo sfidiamo subito con d5.",
    "White pushes on to e5, gaining space.": "Il Bianco spinge fino a e5 e guadagna spazio.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Prima di chiudere la catena di pedoni con e6, il nostro alfiere scappa in f5. Questo, in sostanza, è il primo buon ordine della Caro-Kann. L'alfiere esce prima che la porta si chiuda.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "Segue cavallo f3, poi e6. Con l'alfiere sviluppato al sicuro, e6 è ora del tutto comodo.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "Il Bianco sceglie l'impianto quieto e sensato di alfiere e2, un sistema reso popolare dal grande maestro inglese Nigel Short.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "Colpiamo con c5, attaccando la base della catena di pedoni bianca in d4.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "Il Bianco arrocca, e cavallo c6 aggiunge un altro pezzo alla pressione.",
    "White reinforces d4 with c3.": "Il Bianco rinforza d4 con c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "Cambiamo i pedoni in d4, apriamo la colonna c e diamo al nostro controgioco una via utile.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "L'altro cavallo si sviluppa in e7, diretto a f5, dove può mettere di nuovo in discussione d4.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "Il Bianco gioca cavallo c3, e il nostro alfiere applica l'inchiodatura da g4.",
    "White answers with knight e1, breaking the pin.":
      "Il Bianco risponde con cavallo e1 e spezza l'inchiodatura.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Perciò cambiamo l'utile alfiere bianco in e2. Ricatturare con il cavallo tiene d4 ben difeso.",
    "Our knight settles on f5, still eyeing d4.":
      "Il nostro cavallo si sistema in f5, con l'occhio ancora su d4.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "Il Bianco lo protegge con alfiere e3, e noi sviluppiamo con calma l'alfiere in e7, pronti ad arroccare.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "Il risultato è una posizione pari con un piano coerente. Mantieni la pressione su d4 e usa la colonna c con intenzione.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "Niente fuochi d'artificio: solo struttura sana, pressione paziente e ogni pezzo utilmente occupato.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "Ora tocca a te. Ripeti la linea finché le mosse non sembrano meno memoria e più buon senso.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Bene, qui è Professor Potato Pie, tè in mano, e oggi diamo un breve sguardo al sistema di Londra.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "L'apertura è diventata strettamente associata al grande Torneo di Londra del 1922, dove questo impianto affidabile attirò più attenzione.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Bene, di solito inizia con pedone in d4, cavallo in f3 e alfiere in f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Poi vengono pedone in e3, pedone in c3, cavallo in d2, alfiere in d3 e l'arrocco corto.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "L'ordine preciso può cambiare, ma quella formazione familiare è il cuore del sistema di Londra.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "È un'apertura solida e sensata, giocata sia dai giocatori di club sia dai grandi maestri.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Bene, goditi il prendere confidenza con il sistema di Londra e vediamo come i pezzi si combinano.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Bene, diamo un'occhiata alla prima linea del nostro pacchetto di studio del Londra.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Questa è la morsa di Londra, quieta all'inizio, ma c'è metodo in ogni mossa.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Giochiamo pedone in d4 e il Nero risponde con pedone in d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Alfiere in f4, cavallo in f6, pedone in e3, e il Nero colpisce con pedone in c5.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Costruiamo la piramide familiare con pedone in c3, il Nero sviluppa il cavallo in c6.",
    "Knight to d2 and black plays pawn to e6.": "Cavallo in d2 e il Nero gioca pedone in e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "L'altro nostro cavallo arriva in f3, mentre l'alfiere del Nero arriva in d6.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Ritiriamo il nostro alfiere in g3, tenendolo utile e al sicuro.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "Il Nero arrocca sul lato di re, piazziamo l'altro alfiere in d3, il Nero gioca pedone in b6 e ora piantiamo il cavallo in e5, uno splendido avamposto centrale.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Alfiere in b7, arrochiamo sul lato di re, il Nero piazza la donna in c7 e completiamo la morsa con pedone in f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "Eccola, una posizione di Londra compatta, con il centro saldamente sotto controllo e i nostri pezzi che cominciano a guardare verso il lato di re.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Ripetila finché la tua mano non conosce la strada e il tuo avversario non si chiede quando l'apertura quieta è diventata un attacco.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Bene, qui Professor Potato Pie, tè in mano, e oggi incontriamo una delle aperture più antiche ed eleganti degli scacchi, la partita italiana.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "Le sue idee furono studiate dai maestri italiani più di quattro secoli fa, e l'apertura compare ancora oggi a ogni livello degli scacchi.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "Il Bianco inizia con pedone in e4, e il Nero risponde con pedone in e5, cavallo in f3, cavallo in c6, e poi alfiere in c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "Quell'alfiere punta verso f7, la delicata casella accanto al re nero.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "Da qui il Nero risponde di solito con alfiere in c5, entrando nel Giuoco Piano, oppure con cavallo in f6, raggiungendo la difesa dei due cavalli.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "La partita italiana è classica, vivace, e si fonda sullo sviluppo naturale, sul controllo del centro e sulle possibilità d'attacco.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Bene, goditi il prendere confidenza con la partita italiana e vediamo dove ci porta quell'alfiere in c4.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Bene, benvenuto alla linea 1 del nostro pacchetto di apprendimento della partita italiana.",
    "This is the quieter Italian.": "Questa è l'italiana più tranquilla.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "Non serve dare fuoco alle tende quando una preparazione attenta basta e avanza.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Iniziamo con pedone in e4, e il Nero risponde con pedone in e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "Cavallo in f3, cavallo in c6, alfiere in c4, e il Nero sviluppa l'alfiere in c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "Entrambi gli alfieri occupano i loro posti classici e tengono d'occhio il centro.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Giochiamo pedone in c3, preparando un futuro pedone in d4.",
    "Black develops knight to f6 and places pressure on e4.":
      "Il Nero sviluppa il cavallo in f6 e mette pressione su e4.",
    "Pawn to d3, pawn to d6.": "Pedone in d3, pedone in d6.",
    "Both sides secure the centre before making any grand declarations.":
      "Entrambi i lati assicurano il centro prima di qualsiasi grande dichiarazione.",
    "We castle king side.": "Arrocchiamo sul lato di re.",
    "Black plays pawn to a6.": "Il Nero gioca pedone in a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Rispondiamo con pedone in a4, guadagnando un po' di spazio sul lato di donna, e l'alfiere si sistema in a7.",
    "Knight to d2 and black castles king side.": "Cavallo in d2 e il Nero arrocca sul lato di re.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Giochiamo pedone in h3, impedendo che un alfiere diventi fastidioso in g4, e dando al nostro re una casa utile per respirare.",
    "Black's knight moves to e7.": "Il cavallo del Nero si sposta in e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "Torre in e1 rinforza il e4, e il cavallo prosegue verso g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "Eccoci, una posizione italiana solida, con ogni pezzo che si prepara a un lavoro utile.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Continua a sviluppare, sorveglia il centro e sii pronto per la rottura d4 quando arriva il momento.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Ripeti la linea finché le mosse non sembrano naturali come mettere il bollitore.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Bene, qui è Professor Potato Pie, tè preparato come si deve, e oggi presentiamo una delle grandi aperture classiche, il gambetto di donna.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "L'apertura compare negli scritti scacchistici dalla fine del quindicesimo secolo, e generazioni di giocatori illustri l'hanno usata per contendere il centro.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "Il Bianco inizia con pedone in d4, e il Nero risponde con pedone in d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Poi il Bianco gioca pedone in c4, sfidando il pedone centrale nero e offrendo il pedone c.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "Si chiama gambetto, anche se il Bianco di solito può recuperare il pedone se il Nero accetta,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Quindi questo è meno una donazione avventata e più un invito strategico, servito con cortesia ma con secondi fini.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "Da qui il Nero può accettare il pedone o rifiutarlo e mantenere un centro solido.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Bene, goditi il prendere confidenza con il gambetto di donna e vediamo cosa quel piccolo pedone c avventuroso può persuadere il Nero a fare.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Bene, benvenuto alla Linea 1 del nostro pacchetto di studio del gambetto di donna.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "Questi sono veri scacchi classici: fondamenta solide, sviluppo paziente e nessun mobile lanciato attraverso la stanza.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Cominciamo con pedone in d4 e il Nero risponde con pedone in d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Pedone in c4 sfida il centro e il Nero risponde con pedone in e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "Questo è il gambetto di donna rifiutato. Il Nero sostiene il pedone d5 invece di accettare la nostra offerta.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "Cavallo in c3, cavallo in f6, alfiere in g5 crea l'inchiodatura e il Nero sviluppa con calma l'alfiere in e7.",
    "We play pawn to e3 and black castles kingside.":
      "Giochiamo pedone in e3 e il Nero arrocca sul lato di re.",
    "Knight to f3, knight to d7.": "Cavallo in f3, cavallo in d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Torre in c1 mette la torre sulla colonna c mentre il Nero gioca pedone in c6 e rafforza la struttura centrale.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Alfiere in d3 e il Nero risolve ora la tensione con pedone da d5 prende c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "Il nostro alfiere prende c4, recuperando il pedone con lo sviluppo.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "Il cavallo nero va in d5 e occupa una forte casa centrale.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Cambiamo con alfiere prende e7 e la donna nera ricattura in e7.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "Eccola, una posizione equilibrata del gambetto di donna, con uno sviluppo sensato e ancora molto gioco al centro.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Impara la struttura, comprendi i cambi e lascia che la posizione ti dica quando è ora di spingere.",
    "Very civilised and quietly ambitious.": "Molto civile e quietamente ambizioso.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Bene, qui Professor Potato Pie, ti metto pronto, e oggi incontriamo la difesa francese: quali sono le risposte più resistenti del Nero al pedone di re?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "Il Bianco inizia con pedone in e4, noi rispondiamo con pedone in e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "Il Bianco reclama più spazio con pedone in d4 e noi colpiamo subito con pedone in d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "L'apertura prese il nome da una partita per corrispondenza tra Londra e Parigi nel 1834, quando la squadra di Parigi impiegò la difesa con successo.",
    "Its character is patient, but hardly passive.": "Il suo carattere è paziente, ma tutt'altro che passivo.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "Il Nero costruisce una solida catena di pedoni, invita il Bianco a dichiarare le intenzioni, poi sfida il centro con mosse come pedone in c5 e, quando il momento è maturo, pedone in f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "Il nostro alfiere in caselle chiare può richiedere un po' di diplomazia, ma ciò fa parte della sottile architettura dell'apertura.",
    "Solid, combative and rich in counterplay.": "Solida, combattiva e ricca di controgioco.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "La francese non affretta la discussione: la vince, una domanda precisa alla volta.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "Quindi mettiti comodo, tieni d'occhio le rotture di pedone e goditi il prendere confidenza con la difesa francese.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "Bene, benvenuto alla Linea 1 del nostro pacchetto di studio della difesa francese.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "Il titolo esatto è la difesa francese, variante Winawer, linea principale posizionale dell'avanzata, e la stiamo esercitando dal lato del Nero.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "Il Bianco inizia con pedone in e4, noi rispondiamo con pedone in e6, il Bianco prende il centro con pedone in d4 e noi lo sfidiamo con pedone in d5.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "Cavallo in c3, poi alfiere in b4: questo annuncia la Winawer.",
    "We pin the knight and ask white how ambitious they're feeling.": "Inchiodiamo il cavallo e chiediamo al Bianco quanto si senta ambizioso.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "Il Bianco avanza il pedone in e5, noi contrattacchiamo subito con pedone in c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.":
      "Il Bianco gioca pedone in a3, sfidando il nostro alfiere, quindi l'alfiere prende c3, scacco.",
    "White recaptures with the b-pawn to c3.": "Il Bianco ricattura con il pedone b verso c3.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "Il Bianco ha guadagnato la coppia degli alfieri e un centro ampio, ma ha accettato in cambio pedoni c doppiati.",
    "That trade-and-balance is the very grammar of the Winawer.": "Quello scambio e quell'equilibrio sono la grammatica stessa della Winawer.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.":
      "Sviluppiamo il cavallo in e7, il Bianco sviluppa il cavallo in f3 e il nostro alfiere va in d7.",
    "White plays pawn to a4, restraining queen side expansion.": "Il Bianco gioca pedone in a4, frenando l'espansione sull'ala di donna.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Rispondiamo con donna in a5, facendo pressione su c3 e aiutando a liberare la via per l'arrocco sull'ala di donna.",
    "Bishop to d2 and our knight develops to c6.": "Alfiere in d2 e il nostro cavallo si sviluppa in c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "Il Bianco piazza l'alfiere in d3, gettando uno sguardo piuttosto sgarbato verso h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "Avanziamo il pedone in c4, guadagnando spazio e rimandando quell'alfiere in e2.",
    "Now comes pawn to f6, the characteristic French lever.": "Ora arriva pedone in f6, la leva caratteristica della francese.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.":
      "Non stiamo soltanto ammirando il centro del Bianco: gli chiediamo di presentare le sue credenziali.",
    "White castles king side, black castles queen side.": "Il Bianco arrocca sull'ala di re, il Nero arrocca sull'ala di donna.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "I re sono ora sistemati su ali opposte, la posizione è splendidamente squilibrata e il piano del Nero è chiaro.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "Sfida il pedone e5, apri linee utili e genera attività sull'ala di donna con uno scopo preciso.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Questa è la Winawer posizionale: solida nella costruzione, combattiva nell'intenzione e carica di una notevole elettricità nascosta.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.":
      "Tocca a te: ripetila finché l'ordine delle mosse non sembri meno memoria e più buon senso.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Proprio lì, miei cari. Big Red qui. E oggi guardiamo come si deve la Ruy Lopez,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "nota anche come apertura spagnola. C'è della storia in questa. Prende il nome",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "da Ruy Lopez de Segura, un prete spagnolo e scrittore di scacchi che studiò l'apertura nel",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "XVI secolo. Il Bianco inizia con pedone in e4. Il Nero risponde pedone in e5. Cavallo in f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "attacca quel pedone e il Nero lo difende con cavallo in c6. Poi viene l'alfiere in b5. Ed ecco",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "che c'è. La Ruy Lopez. L'alfiere non sta vincendo subito il pedone e5. Sta applicando",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "pressione al cavallo che lo difende, lasciando al Nero un problema quieto ma insistente.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "Da questo piccolo inizio elegante cresce una delle più grandi famiglie di aperture degli scacchi.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Alcune linee sono calme e di manovra, altre possono animarsi prima che tu abbia avuto il tempo di posare",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "il tè. È classica, sottile e piena di idee strategiche vere. Vecchia, dignitosa e ancora",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "piena di possibilità. Un po' come Londra stessa. Tieni dunque d'occhio il centro,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "cura i pezzi e goditi il diventare più familiare con la Ruy Lopez. Big Red ti rivedrà.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "Bene allora, miei cari, Big Red è di nuovo alla scacchiera e questa è la linea 1 del nostro pacchetto sulla Ruy Lopez, la Difesa Morphy, variante chiusa Breyer.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Giochiamo con i pezzi bianchi e questa è un'autentica opera strategica.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "Il Bianco inizia con il pedone in e4, il Nero risponde con il pedone in e5, Nf3 attacca il pedone e il Nero lo difende con Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 e la Ruy Lopez è sulla scacchiera. Il Nero gioca il pedone in a6, annunciando la Difesa Morphy",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "e pone al nostro alfiere una domanda molto diretta. Ritiriamo l'alfiere in a4. Il Nero sviluppa Nf6,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "arrochiamo sul lato di re e il Nero sviluppa l'alfiere in e7. La torre in e1 rinforza il nostro pedone e4",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "e pone la torre di fronte al re nero. Il Nero si espande con il pedone in b5, così il nostro alfiere si sistema",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "in b3. Il pedone in d6 dà al centro nero una base solida. Giochiamo il pedone in c3,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "preparando il grande avanzamento centrale, il pedone in d4. Il Nero arrocca sul lato di re. Ora il pedone in h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "una piccola mossa utile che tiene un alfiere o un cavallo lontano da g4 e dà al nostro re un po' d'aria.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Poi arriva la mossa che rende la Breyer inconfondibile. Il Nero ritira il cavallo in b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "Sembra che il cavallo abbia dimenticato perché è uscito, ma nient'affatto. Questo è strategico",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "riciclo del più alto livello. Colpiamo con il pedone in d4, stabilendo un centro magnifico. Il Nero",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "reindirizza quel cavallo in d7, dove sostiene e5 e libera il pedone c per il futuro controgioco.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "Il nostro cavallo di donna si sviluppa in d2. L'alfiere nero va in b7 e mira a e4. L'alfiere",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "in c2 preserva il nostro prezioso alfiere spagnolo e punta verso il lato di re. Il Nero piazza la",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "torre in e8, aggiungendo ulteriore sostegno al pedone e5. Infine il nostro cavallo scivola in f1. Quel cavallo",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "ha un itinerario splendido. Da f1 può andare in g3, aumentando la pressione su f5 e aiutando",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "l'attacco sul lato di re a prendere slancio. Questa è la Breyer chiusa. Paziente, sofisticata e",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "assolutamente traboccante di vita e di energia. Il Bianco possiede lo spazio centrale. Il Nero ha costruito una posizione compatta",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "e sta preparando il contrattacco. Giocala con convinzione. Goditi ogni manovra",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "e ricorda: le mosse quiete non stanno ad aspettare. Stanno caricando la molla.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "Tocca a te: ripetila finché quel viaggio del cavallo da b1 a d2 e poi a f1 non sembri naturale come trovare",
    "your way around London.":
      "la strada per Londra.",
    "Right then, the Sicilian Defence for Black.":
      "Bene allora, la difesa siciliana per il Nero.",
    "White starts with 1. e4, claiming the centre.":
      "Il Bianco inizia con un punto e4, reclamando il centro.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "Il Nero risponde un punto c5, colpendo di fianco invece di copiare direttamente il Bianco.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "L'idea è sfidare le ambizioni centrali del Bianco, svilupparsi con attività e creare controgioco fin dall'inizio.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Una strada comune è 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "Eccoci: una difesa acuta e flessibile, con un bel morso.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Bene, benvenuto alla linea 1 della Sicilian, la Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "Questa è una delle risposte più ambiziose del Nero alla pedone in e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "Il Bianco apre con pedone in e4, e il Nero colpisce subito con pedone in c5.",
    "White develops knight to f3.":
      "Il Bianco sviluppa il cavallo in f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "Il Nero gioca pedone in d6, e il Bianco apre il centro con pedone in d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "Il Nero prende in d4 con il pedone c, il Bianco ricattura con cavallo prende d4.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "Il Nero sviluppa il cavallo in f6, e il Bianco porta l'altro cavallo in c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Ora arriva la famosa mossa Najdorf, pedone in a6, una piccola mossa flessibile con molto veleno.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "Il Nero tiene la posizione adattabile e si prepara a espandersi sul lato di donna.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "La prima parte della linea è pedone in e4, pedone in c5, cavallo in f3, pedone in d6, pedone in d4, pedone prende d4, cavallo prende d4, cavallo in f6, cavallo in c3, pedone in a6, alfiere in e3, pedone in e5, cavallo in b3, alfiere in e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "Ora la linea continua, pedone in f3, alfiere in e7, donna in d2, arroco corto, arroco lungo, cavallo in bd7, pedone in g4, pedone in b5.",
    "White prepares a kingside assault with pawn to f3.":
      "Il Bianco prepara un assalto sul lato di re con pedone in f3.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "Il Nero sviluppa con calma l'alfiere in e7, poi il Bianco porta la donna in d2.",
    "Black castles kingside and White castles queenside.":
      "Il Nero arrocca sul lato di re e il Bianco arrocca sul lato di donna.",
    "Now the battle lines are drawn.":
      "Ora le linee di battaglia sono tracciate.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "Il Nero sviluppa il cavallo in bd7 e il Bianco inizia la famosa tempesta di pedoni con pedone in g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "Il Nero risponde con pedone in b5 ed eccola, la Najdorf ha preso vita.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "Il Bianco raduna le forze sul lato di re, il Nero carica sul lato di donna, ed entrambi preparano qualcosa di piuttosto pericoloso.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Bene, segui le mosse da vicino, resta attento e goditi questa splendida linea Sicilian.",
  },
  hi: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "ठीक — Scotch Gambit। यह एक सही खुले खेल की तरह शुरू होता है: e4, e5, घोड़े बाहर, फिर सफ़ेद d4 से केंद्र पर वार करते हैं।",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "जब काले d4 पर लेते हैं, सफ़ेद मोहरा छोड़कर ऊँट को c4 पर रख सकते हैं। यही गैंबिट है — जल्दी विकास, f7 पर निशाना, और काले संभलें उससे पहले उन पर दबाव।",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "Scotch परिवार का नाम उन Edinburgh–London पत्राचार मैचों से पड़ा, जो 1820 के दशक में हुए। शौकीनों को यह लाइन अब भी पसंद है, क्योंकि बोर्ड खुलता है और योजनाएँ ठोस होती हैं — कोई लंबी चुपचाप घुटन नहीं।",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "अपनी चाय लो। मेरे साथ बुक चालें अभ्यास करो — मैं तुम्हें असली Scotch Gambit के रास्ते पर रखूँगा।",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "अच्छा — लाइन 1 में स्वागत है। Professor Potato Pie, तुम्हारी सेवा में।",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "इस सीखने के पैक में हमने गैंबिट को दस सावधानी से चुनी लाइनों में समेटा है।",
    "10 lines from Opening Lab.":
      "Opening Lab की 10 लाइनें।",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "उन्हें सीखो और तुम केवल थ्योरी में बचोगे नहीं। तुम सही चालें भरोसे के साथ लौटाओगे, संतुलन रखोगे, और खेल में मजबूती से बने रहोगे।",
    "You get 10 lines from Opening Lab.":
      "तुम्हें Opening Lab की 10 लाइनें मिलती हैं।",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "जब काले फिसलें, तुम सीखोगे कि चाल क्यों खराब है, सटीक सिलसिला चुनना, गलती को साफ बढ़त में बदलना और कभी-कभी एक बहुत सुंदर मात।",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "स्वाभाविक है, काले के पास दस से अधिक तरीके हैं। इसे एक छोटी पुस्तिका समझो, पूरी ज्ञानकोश नहीं — चालों के पीछे का तर्क, केवल याद करने का क्रम नहीं।",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "पैक पूरा करो और Scotch Gambit जब भी आए परिचित लगेगा। तुम निशान पहचानोगे, योजनाएँ समझोगे, और आगे पढ़ाई के लिए पक्की ज़मीन पाओगे।",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "आनंद लो। समय लो, हर लाइन चलो, और बोर्ड पर मिलते हैं।",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "अच्छा, अब ओपनिंग के जाल। ये लाइनें बहुत मज़ेदार हैं, और कभी-कभी एक असावधान प्रतिद्वंद्वी को पूरी तरह चौंका देती हैं। इसीलिए उन्हें जानना सार्थक है।",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "लेकिन एक गंभीर बात भी है। जाल पढ़ने से चेतावनी के संकेत पहचानना आता है, इसलिए तुम्हारे खुद फँसने की संभावना बहुत कम हो जाती है।",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "हर लाइन चलो, उसके पीछे का विचार पकड़ो, और इन छोटे सुंदर सामरिक तंत्रों का आनंद लो।",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "उन्हें समझदारी से इस्तेमाल करो, ठीक से समझो, और जब अवसर आए, सटीकता को काम करने दो।",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "कोशिश करो, मज़ा लो, और अब मुझे लगता है आलू की पाई का समय है। आनंद लो।",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "अच्छा, लाइन 1 में स्वागत है। यह Legal's Mate है, Monsieur de Légal के नाम पर, जो अठारहवीं सदी के एक फ़्रांसीसी खिलाड़ी थे।",
    "White opens with the king's pawn, e4.": "सफ़ेद राजा के प्यादे से खोलते हैं, e4।",
    "Black answers symmetrically with e5.": "काले सममित जवाब देते हैं, e5।",
    "Knight to f3 attacks that pawn.": "घोड़ा f3 पर उस प्यादे पर हमला करता है।",
    "Black defends it with d6, which is the Philidor Defence.":
      "काले उसे d6 से बचाते हैं, यही Philidor रक्षा है।",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "सफ़ेद का ऊँट c4 पर आता है और कमज़ोर f7 घर को देखता है।",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "काले का ऊँट g4 पर जाता है और घोड़े को रानी पर पिन करता है।",
    "White calmly develops, knight to c3.": "सफ़ेद शांत भाव से विकास करते हैं, घोड़ा c3 पर।",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "काले g6 खेलते हैं। यह धीमी चाल है, और अब जाल तैयार है।",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "घोड़ा e5 लेता है! वह घोड़ा केवल रानी पर पिन था, राजा पर नहीं, इसलिए वह चलने के लिए पूरी तरह आज़ाद है।",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "काले रोक नहीं पाते और d1 पर रानी ले लेते हैं। यही लालची कब्ज़ा है, और यह घातक है।",
    "Bishop takes f7, check!": "ऊँट f7 लेता है, शह!",
    "The king has only one square to go to, e7.": "राजा के पास केवल एक घर बचा है, e7।",
    "Knight to d5, and that's checkmate.": "घोड़ा d5 पर, और यह मात है।",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "दो घोड़ों और एक ऊँट ने पूरी काली सेना को हरा दिया। काले की रानी, हाथी और d1 का ऊँट अभी भी बोर्ड पर हैं, और कोई मदद नहीं कर सकता।",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "याद रखो: जब खेल में इतनी जल्दी रानी मुफ़्त में मिले, लेने से पहले चारों ओर अच्छी तरह देखो।",
    "Now over to you. Practise it until your knights know the way.":
      "अब तुम्हारी बारी। अभ्यास करो, जब तक तुम्हारे घोड़े रास्ता न जान जाएँ।",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "आह, फिर नमस्ते। Professor Potato Pie, हाथ में चाय। आज हम Caro-Kann रक्षा की ओर देखते हैं, एक बहुत मज़बूत ओपनिंग, उत्तम शिष्टाचार के साथ और कोहनियाँ आश्चर्यजनक रूप से तेज़।",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "यह e4 c6 से शुरू होती है, और नाम Horatio Caro तथा Marcus Kann से है, उन्नीसवीं सदी के दो खिलाड़ी, जिनके विश्लेषण ने इस सम्मानित रक्षा को पहचान दी।",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "रणनीतिक आधार सराहनीय रूप से किफायती है। काले d5 तैयार करते हैं, तुरंत सफ़ेद के केंद्र को चुनौती देते हैं, और हल्के घरों के ऊँट को आज़ाद रखते हैं, प्यादों की कतार के पीछे बंद करने के बजाय।",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Caro-Kann ठोस, धैर्यवान और संरचना में स्वस्थ है, पर शांति को निष्क्रियता मत समझो। सम्मानजनक बाहरी रूप के नीचे अच्छे पलटवार हैं, खासकर जब सफ़ेद ज़्यादा महत्वाकांक्षी हो जाएँ।",
    "You'll study 10 lines from Opening Lab.":
      "तुम Opening Lab की 10 लाइनें पढ़ोगे।",
    "These are 10 lines from Opening Lab.":
      "ये Opening Lab की 10 लाइनें हैं।",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "Practice में मैं संकेत दूँगा जहाँ ज़रूरत हो। Test में सहायता गायब हो जाती है, और रह जाते हो तुम, स्थिति और तुम्हारा निर्णय।",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "हर लाइन वहीं समाप्त होती है जहाँ तैयार बुक लाइन समाप्त होती है। उसके बाद कंप्यूटर के विरुद्ध कोई जारी खेल नहीं।",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "उद्देश्य बेमतलब आगे खेलना नहीं, बल्कि चालें आत्मसात करना, विचार समझना और बोर्ड पर लौटने पर पैटर्न पहचानना है।",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "अच्छा। चाय जम गई, मोहरे तैयार। चलें शुरू करें।",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "अच्छा, लाइन 1 में स्वागत है, एडवांस वैरिएशन। सफ़ेद e4 से केंद्र लेते हैं।",
    "We answer c6, preparing the thematic d5 advance.":
      "हम c6 का जवाब देते हैं, विषयगत d5 अग्रसर तैयार करते हुए।",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "सफ़ेद d4 से चौड़ा केंद्र बनाते हैं, और हम तुरंत d5 से उसे चुनौती देते हैं।",
    "White pushes on to e5, gaining space.": "सफ़ेद e5 तक बढ़ते हैं और जगह पाते हैं।",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "e6 से प्यादों की कतार बंद करने से पहले हमारा ऊँट f5 पर निकल जाता है। यही, संक्षेप में, Caro-Kann की पहली अच्छी गृहस्थी है। दरवाज़ा बंद होने से पहले ऊँट बाहर आ जाता है।",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "फिर घोड़ा f3, उसके बाद e6। ऊँट सुरक्षित विकसित हो चुका है, इसलिए e6 अब पूरी तरह आरामदायक है।",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "सफ़ेद शांत और समझदार ऊँट e2 व्यवस्था चुनते हैं, एक प्रणाली जिसे अंग्रेज़ ग्रैंडमास्टर Nigel Short ने लोकप्रिय किया।",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "हम c5 से वार करते हैं, सफ़ेद की प्यादों की कतार के आधार d4 पर हमला करते हुए।",
    "White castles, and knight c6 adds another piece to the pressure.":
      "सफ़ेद रोकाड करते हैं, और घोड़ा c6 दबाव में एक और टुकड़ा जोड़ता है।",
    "White reinforces d4 with c3.": "सफ़ेद c3 से d4 को मज़बूत करते हैं।",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "हम d4 पर प्यादे बदलते हैं, c-फ़ाइल खोलते हैं और अपने पलटवार को एक उपयोगी रास्ता देते हैं।",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "बचा घोड़ा e7 पर विकसित होता है, f5 की ओर, जहाँ वह फिर d4 पर सवाल उठा सकता है।",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "सफ़ेद घोड़ा c3 खेलते हैं, और हमारा ऊँट g4 से पिन लगाता है।",
    "White answers with knight e1, breaking the pin.":
      "सफ़ेद घोड़ा e1 से जवाब देते हैं और पिन तोड़ते हैं।",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "इसलिए हम सफ़ेद के उपयोगी ऊँट को e2 पर बदलते हैं। घोड़े से वापस लेना d4 को सुरक्षित बचाए रखता है।",
    "Our knight settles on f5, still eyeing d4.":
      "हमारा घोड़ा f5 पर जम जाता है, अभी भी d4 को देखता हुआ।",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "सफ़ेद उसे ऊँट e3 से बचाते हैं, और हम शांत भाव से ऊँट को e7 पर विकसित करते हैं, रोकाड के लिए तैयार।",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "नतीजा बराबर स्थिति है, स्पष्ट योजना के साथ। d4 पर दबाव रखो और c-फ़ाइल का उद्देश्य के साथ उपयोग करो।",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "आतिशबाज़ी की ज़रूरत नहीं, केवल स्वस्थ संरचना, धैर्यवान दबाव, और हर टुकड़ा सार्थक काम में।",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "अब तुम्हारी बारी। लाइन को तब तक दोहराओ जब तक चालें याद से कम और समझ से ज़्यादा न लगें।",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "अच्छा, यहाँ Professor Potato Pie है, हाथ में चाय, और आज हम लंदन प्रणाली पर एक संक्षिप्त नज़र डालते हैं।",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "यह ओपनिंग 1922 के महान लंदन टूर्नामेंट से घनिष्ठ रूप से जुड़ी, जहाँ इस भरोसेमंद व्यवस्था ने व्यापक ध्यान खींचा।",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "ठीक, आमतौर पर यह d4 पर प्यादा, f3 पर घोड़ा और f4 पर हाथी से शुरू होती है।",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "फिर आता है e3 पर प्यादा, c3 पर प्यादा, d2 पर घोड़ा, d3 पर हाथी और किंग-साइड कैसलिंग।",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "सटीक क्रम बदल सकता है, लेकिन वह परिचित रचना लंदन प्रणाली का हृदय है।",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "यह एक ठोस, समझदार ओपनिंग है, जिसे क्लब खिलाड़ी और ग्रैंडमास्टर दोनों ने खेला है।",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "ठीक, लंदन प्रणाली से और परिचित होने का आनंद लो, और देखें कि मोहरे कैसे साथ बैठते हैं।",
    "Right then, let's have a look at the first line in our London learning pack.":
      "अच्छा, हमारे लंदन सीखने के पैक की पहली लाइन पर नज़र डालते हैं।",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "यह लंदन क्लैंप है, शुरुआत में शांत, लेकिन हर चाल में विधि है।",
    "We play pawn to d4 and black answers pawn to d5.":
      "हम प्यादा d4 पर खेलते हैं और काला प्यादा d5 से जवाब देता है।",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "हाथी f4 पर, घोड़ा f6 पर, प्यादा e3 पर, और काला प्यादा c5 से वार करता है।",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "हम परिचित पिरामिड प्यादा c3 से बनाते हैं, काला घोड़े को c6 पर विकसित करता है।",
    "Knight to d2 and black plays pawn to e6.": "घोड़ा d2 पर और काला प्यादा e6 खेलता है।",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "हमारा दूसरा घोड़ा f3 पर आता है, जबकि काले का हाथी d6 पर आता है।",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "हम अपने हाथी को g3 पर वापस समेटते हैं, उसे उपयोगी और सुरक्षित रखते हुए।",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "काला किंग साइड कैसल करता है, हम अपना दूसरा हाथी d3 पर रखते हैं, काला प्यादा b6 खेलता है और अब हम घोड़े को e5 पर गाड़ते हैं, एक शानदार केंद्रीय चौकी।",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "हाथी b7 पर, हम किंग साइड कैसल करते हैं, काला रानी को c7 पर रखता है और हम प्यादा f4 से क्लैंप पूरा करते हैं।",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "यह रही, एक सघन लंदन स्थिति, केंद्र दृढ़ निगरानी में और हमारे मोहरे किंग साइड की ओर झाँकने लगते हैं।",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "इसे तब तक दोहराओ जब तक तुम्हारा हाथ रास्ता जान न ले और तुम्हारा प्रतिद्वंद्वी यह न सोचे कि शांत ओपनिंग हमला कब बन गई।",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "ठीक है, यहाँ Professor Potato Pie, हाथ में चाय, और आज हम शतरंज की सबसे पुरानी और सबसे सुंदर ओपनिंग में से एक से मिलते हैं, इतालवी ओपनिंग।",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "इसके विचार चार शताब्दियों से भी पहले इतालवी मास्टरों ने पढ़े थे, और यह ओपनिंग आज भी शतरंज के हर स्तर पर दिखती है।",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "सफेद e4 पर प्यादे से शुरू करता है, और काला e5 पर प्यादे से जवाब देता है, f3 पर घोड़ा, c6 पर घोड़ा, और फिर c4 पर ऊंट।",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "वह ऊंट f7 की ओर इशारा करता है, काले राजा के बगल का नाज़ुक छोटा घर।",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "यहाँ से काला आमतौर पर c5 पर ऊंट से जवाब देता है, Giuoco Piano में प्रवेश करता है, या f6 पर घोड़े से, दो घोड़ों की रक्षा तक पहुँचता है।",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "इतालवी ओपनिंग शास्त्रीय और जीवंत है, और स्वाभाविक विकास, केंद्र नियंत्रण और हमले की संभावनाओं पर बनी है।",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "ठीक, इतालवी ओपनिंग से और परिचित होने का आनंद लो, और देखें कि c4 पर वह ऊंट हमें कहाँ ले जाता है।",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "ठीक है, हमारे इतालवी ओपनिंग सीखने के पैक की लाइन 1 में स्वागत है।",
    "This is the quieter Italian.": "यह शांत इतालवी ओपनिंग है।",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "जब सावधानी भरी तैयारी काफी हो, पर्दों में आग लगाने की ज़रूरत नहीं।",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "हम प्यादे से e4 पर शुरू करते हैं, और काला प्यादे से e5 पर जवाब देता है।",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "घोड़ा f3 पर, घोड़ा c6 पर, ऊंट c4 पर, और काला ऊंट को c5 पर विकसित करता है।",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "दोनों ऊंट अपने शास्त्रीय पद संभालते हैं और केंद्र पर चौकन्नी नज़र रखते हैं।",
    "We play pawn to c3, preparing a future pawn to d4.":
      "हम प्यादा c3 पर खेलते हैं, भविष्य के प्यादे d4 की तैयारी करते हुए।",
    "Black develops knight to f6 and places pressure on e4.":
      "काला घोड़े को f6 पर विकसित करता है और e4 पर दबाव डालता है।",
    "Pawn to d3, pawn to d6.": "प्यादा d3 पर, प्यादा d6 पर।",
    "Both sides secure the centre before making any grand declarations.":
      "दोनों पक्ष कोई बड़ा ऐलान करने से पहले केंद्र को सुरक्षित करते हैं।",
    "We castle king side.": "हम किंग साइड कैसल करते हैं।",
    "Black plays pawn to a6.": "काला प्यादा a6 खेलता है।",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "हम प्यादे a4 से जवाब देते हैं, क्वीन साइड पर थोड़ी जगह पाते हैं, और ऊंट a7 पर जम जाता है।",
    "Knight to d2 and black castles king side.":
      "घोड़ा d2 पर और काला किंग साइड कैसल करता है।",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "हम प्यादा h3 खेलते हैं, ताकि कोई ऊंट g4 पर तकलीफ़देह न बने, और अपने राजा को साँस लेने की एक उपयोगी घर मिल जाए।",
    "Black's knight moves to e7.": "काले का घोड़ा e7 पर जाता है।",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "हाथी e1 पर e4 को मज़बूत करता है, और घोड़ा g6 तक जाता है।",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "यह रही, एक ठोस इतालवी स्थिति, हर मोहरा उपयोगी काम की तैयारी में।",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "विकास जारी रखो, केंद्र पर नज़र रखो, और सही पल पर d4 तोड़ के लिए तैयार रहो।",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "लाइन को तब तक दोहराओ जब तक चालें केतली चढ़ाने जितनी स्वाभाविक न लगें।",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "ठीक है, यहाँ Professor Potato Pie हैं, चाय ठीक से बनी हुई, और आज हम एक महान शास्त्रीय ओपनिंग पेश करते हैं, क्वीन गैम्बिट।",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "यह ओपनिंग पंद्रहवीं सदी के अंत से शतरंज लेखन में दिखती है, और प्रतिष्ठित खिलाड़ियों की पीढ़ियों ने इससे केंद्र के लिए संघर्ष किया है।",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "सफेद d4 पर प्यादा से शुरू करते हैं, और काले d5 पर प्यादे से जवाब देते हैं।",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "फिर सफेद c4 पर प्यादा खेलते हैं, काले के केंद्रीय प्यादे को चुनौती देते हुए और c प्यादा अर्पित करते हुए।",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "इसे गैम्बिट कहते हैं, हालाँकि अगर काले स्वीकार करें तो सफेद आमतौर पर प्यादा वापस पा सकते हैं,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "तो यह लापरवाह दान कम और रणनीतिक निमंत्रण अधिक है, शिष्टता से परोसा गया लेकिन दूसरे इरादे के साथ।",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "यहाँ से काले प्यादा स्वीकार कर सकते हैं या उसे ठुकराकर ठोस केंद्र बनाए रख सकते हैं।",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "अच्छा, क्वीन गैम्बिट से और परिचित होने का आनंद लो और देखें कि वह साहसिक छोटा c प्यादा काले को क्या करने के लिए मना सकता है।",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "ठीक है, हमारे क्वीन गैम्बिट सीखने के पैक की लाइन 1 में स्वागत है।",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "यह असली शास्त्रीय शतरंज है: मजबूत नींव, धैर्यपूर्ण विकास, और कमरे के आर-पार उड़ता कोई फ़र्नीचर नहीं।",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "हम प्यादे से d4 पर शुरू करते हैं और काले प्यादे से d5 पर जवाब देते हैं।",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "प्यादा c4 पर केंद्र को चुनौती देता है और काले प्यादे से e6 पर उत्तर देते हैं।",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "यह अस्वीकृत क्वीन गैम्बिट है। काले d5 प्यादे को सहारा देते हैं, हमारी भेंट स्वीकार करने के बजाय।",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "घोड़ा c3 पर, घोड़ा f6 पर, हाथी g5 पर पिन बनाता है और काले शांति से हाथी e7 पर निकालते हैं।",
    "We play pawn to e3 and black castles kingside.":
      "हम प्यादा e3 पर खेलते हैं और काले राजा-पक्ष में कैसल करते हैं।",
    "Knight to f3, knight to d7.": "घोड़ा f3 पर, घोड़ा d7 पर।",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "हाथी c1 पर हाथी को c-फ़ाइल पर रखता है, जबकि काले प्यादा c6 पर खेलते हैं और केंद्रीय ढाँचे को मज़बूत करते हैं।",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "हाथी d3 पर, और काले अब तनाव d5 से प्यादे के c4 लेने से हल करते हैं।",
    "Our bishop takes c4 recovering the pawn with development.":
      "हमारा हाथी c4 लेता है और विकास के साथ प्यादा वापस पाता है।",
    "Black's knight moves to d5 and occupies a strong central square.":
      "काले का घोड़ा d5 पर जाता है और एक मज़बूत केंद्रीय घर घेरता है।",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "हम हाथी से e7 लेकर विनिमय करते हैं और काले की रानी e7 पर वापस लेती है।",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "यह रहा, क्वीन गैम्बिट की संतुलित स्थिति, समझदार विकास के साथ और केंद्र में अभी बहुत खेल।",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "ढाँचा सीखो, विनिमय समझो, और स्थिति को बताने दो कि आगे बढ़ने का समय कब है।",
    "Very civilised and quietly ambitious.": "बहुत सभ्य और चुपचाप महत्त्वाकांक्षी।",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "ठीक है, यहाँ Professor Potato Pie, आपको तैयार करता हूँ, और आज हम फ्रेंच डिफेंस से मिलते हैं: राजा के प्यादे पर काले के सबसे मज़बूत जवाब कौन से हैं?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "सफ़ेद प्यादा e4 पर चलाते हैं, हम प्यादा e6 से जवाब देते हैं।",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "सफ़ेद प्यादा d4 से और जगह लेते हैं और हम तुरंत प्यादा d5 से प्रहार करते हैं।",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "इस ओपनिंग का नाम 1834 में लंदन और पेरिस के बीच एक पत्राचार मैच से पड़ा, जब पेरिस की टीम ने इस बचाव को सफलता से खेला।",
    "Its character is patient, but hardly passive.": "इसका स्वभाव धैर्यवान है, लेकिन निष्क्रिय कतई नहीं।",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "काले एक मज़बूत प्यादा शृंखला बनाते हैं, सफ़ेद को अपने इरादे बताने का न्योता देते हैं, फिर प्यादा c5 जैसी चालों से केंद्र को चुनौती देते हैं और जब समय आए, प्यादा f6।",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "हमारे हल्के रंग के ऊँट को थोड़ी कूटनीति चाहिए हो सकती है, लेकिन यही इस ओपनिंग की सूक्ष्म रचना का हिस्सा है।",
    "Solid, combative and rich in counterplay.": "ठोस, लड़ाकू और पलटवार से भरपूर।",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "फ्रेंच बहस में जल्दबाज़ी नहीं करता, वह उसे एक-एक सटीक सवाल से जीतता है।",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "तो बैठ जाइए, प्यादे की तोड़ पर नज़र रखें और फ्रेंच डिफेंस से और परिचित होने का आनंद लें।",
    "Right then, welcome to Line 1 of our French defence learning pack.": "ठीक है, हमारे फ्रेंच डिफेंस सीखने वाले पैक की लाइन 1 में स्वागत है।",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "सही नाम है फ्रेंच डिफेंस Winawer रूपांतर, एडवांस की स्थितिगत मुख्य रेखा, और हम इसे काले की ओर से अभ्यास कर रहे हैं।",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "सफ़ेद प्यादा e4 से शुरू करते हैं, हम प्यादा e6 से जवाब देते हैं, सफ़ेद केंद्र प्यादा d4 से लेते हैं और हम उसे प्यादा d5 से चुनौती देते हैं।",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "घोड़ा c3 पर, फिर ऊँट b4 पर: यही Winawer की घोषणा है।",
    "We pin the knight and ask white how ambitious they're feeling.":
      "हम घोड़े को पिन करते हैं और सफ़ेद से पूछते हैं कि वे कितने महत्त्वाकांक्षी महसूस कर रहे हैं।",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "सफ़ेद प्यादा e5 आगे बढ़ाते हैं, हम तुरंत प्यादा c5 से पलटवार करते हैं।",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "सफ़ेद प्यादा a3 खेलते हैं, हमारे ऊँट को चुनौती देते हुए, इसलिए ऊँट c3 लेता है, शह।",
    "White recaptures with the b-pawn to c3.": "सफ़ेद b-प्यादे से c3 पर वापस लेते हैं।",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "सफ़ेद को ऊँटों की जोड़ी और चौड़ा केंद्र मिला, पर बदले में दोहरे c-प्यादे स्वीकार करने पड़े।",
    "That trade-and-balance is the very grammar of the Winawer.": "यही विनिमय और संतुलन Winawer का व्याकरण है।",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.":
      "हम घोड़ा e7 पर विकसित करते हैं, सफ़ेद घोड़ा f3 पर विकसित करते हैं और हमारा ऊँट d7 पर जाता है।",
    "White plays pawn to a4, restraining queen side expansion.": "सफ़ेद प्यादा a4 खेलते हैं, रानी पक्ष के विस्तार को रोकते हुए।",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "हम रानी a5 से जवाब देते हैं, c3 पर दबाव डालते हुए और रानी पक्ष के रोके के लिए रास्ता साफ़ करने में मदद करते हुए।",
    "Bishop to d2 and our knight develops to c6.": "ऊँट d2 पर और हमारा घोड़ा c6 पर विकसित होता है।",
    "White places the bishop on d3, glancing rather impolitely at h7.": "सफ़ेद ऊँट को d3 पर रखते हैं, h7 की ओर कुछ असभ्य नज़र डालते हुए।",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "हम प्यादा c4 आगे बढ़ाते हैं, जगह पाते हैं और उस ऊँट को e2 पर वापस भेज देते हैं।",
    "Now comes pawn to f6, the characteristic French lever.": "अब आता है प्यादा f6, फ्रेंच का खास लीवर।",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.":
      "हम सफ़ेद के केंद्र की केवल प्रशंसा नहीं कर रहे, हम उससे अपनी साख पेश करने को कह रहे हैं।",
    "White castles king side, black castles queen side.": "सफ़ेद राजा पक्ष में रोका करते हैं, काले रानी पक्ष में रोका करते हैं।",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "राजा अब विपरीत पक्षों पर बस गए हैं, स्थिति शानदार ढंग से असंतुलित है और काले की योजना साफ़ है।",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.":
      "e5 प्यादे को चुनौती दो, उपयोगी लाइनें खोलो और सही उद्देश्य से रानी पक्ष में सक्रियता पैदा करो।",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "यही स्थितिगत Winawer है: बनावट में ठोस, इरादे में लड़ाकू, और छिपी बिजली की अच्छी मात्रा लिए हुए।",
    "Your turn, drill it until the move order feels less like memory and more like common sense.":
      "अब तुम्हारी बारी: इसे तब तक दोहराओ जब तक चालों का क्रम याददाश्त कम और सामान्य समझ ज़्यादा लगे।",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "ठीक वहीं, मेरे प्यारों। Big Red यहाँ है। और आज हम Ruy Lopez को अच्छे से देख रहे हैं,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "जिसे स्पेनिश ओपनिंग भी कहते हैं। इसमें कुछ इतिहास है। इसका नाम आता है",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "Ruy Lopez de Segura से, एक स्पेनिश पादरी और शतरंज लेखक जिन्होंने इस ओपनिंग को",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "16वीं सदी में पढ़ा। सफेद e4 पर पैदल से शुरू करता है। काला e5 पर पैदल से जवाब देता है। घोड़ा f3 पर",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "उस पैदल पर हमला करता है और काला c6 पर घोड़े से बचाव करता है। फिर हाथी b5 पर आता है। और वहीं",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "यह है। Ruy Lopez। हाथी e5 का पैदल तुरंत नहीं जीत रहा। वह दबाव डाल रहा है",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "उस घोड़े पर जो उसे रखवाली करता है, और काले को एक शांत लेकिन लगातार समस्या देता है।",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "इस सुंदर छोटी शुरुआत से शतरंज के सबसे भव्य ओपनिंग परिवारों में से एक उगता है।",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "कुछ लाइनें शांत और चालों वाली हैं, दूसरी तब तक जीवंत हो सकती हैं जब तक आपको बैठने का समय न मिले",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "आपकी चाय। यह शास्त्रीय, सूक्ष्म और असली रणनीतिक विचारों से भरी है। पुरानी, गरिमामय और अब भी",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "संभावनाओं से भरी। थोड़ी लंदन जैसी। इसलिए केंद्र पर नज़र रखो,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "अपने मोहरों का ध्यान रखो और Ruy Lopez से और परिचित होने का आनंद लो। Big Red फिर मिलेगा।",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "ठीक है मेरे प्यारों, Big Red बोर्ड पर वापस है और यह हमारे Ruy Lopez सीखने के पैक की लाइन 1 है, मॉर्फी डिफेंस की बंद ब्रेयर वैरिएशन।",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "हम सफ़ेद मोहरों से खेल रहे हैं और यह एक असली रणनीतिक उत्कृष्ट रचना है।",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "सफ़ेद पैदल e4 से शुरू करते हैं, काले पैदल e5 से जवाब देते हैं, Nf3 उस पैदल पर हमला करता है और काले Nc6 से उसकी रक्षा करते हैं।",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 और Ruy Lopez बोर्ड पर है। काले पैदल a6 खेलते हैं, मॉर्फी डिफेंस की घोषणा करते हुए",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "और हमारे हाथी से एक बहुत सीधा सवाल पूछते हैं। हम हाथी को a4 पर वापस लेते हैं। काले Nf6 विकसित करते हैं,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "हम राजा पक्ष में रोकाड करते हैं और काले हाथी को e7 पर विकसित करते हैं। रुक e1 पर हमारे e4 पैदल को मज़बूत करता है",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "और रुक को काले राजा के सामने रखता है। काले पैदल b5 से फैलते हैं, इसलिए हमारा हाथी बैठता है",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "b3 पर। पैदल d6 काले केंद्र को एक मज़बूत नींव देता है। हम पैदल c3 खेलते हैं,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "भव्य केंद्रीय बढ़त की तैयारी करते हुए, पैदल d4। काले राजा पक्ष में रोकाड करते हैं। अब पैदल h3,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "एक उपयोगी छोटी चाल जो हाथी या घोड़े को g4 से दूर रखती है और हमारे राजा को साँस लेने की जगह देती है।",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "फिर वह चाल आती है जो ब्रेयर को एकदम पहचानने लायक बनाती है। काले घोड़े को b8 पर वापस लेते हैं।",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "लगता है जैसे घोड़ा भूल गया कि वह क्यों निकला, पर ऐसा बिलकुल नहीं। यह रणनीतिक",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "सबसे ऊँचे दर्जे की रीसाइक्लिंग है। हम पैदल d4 से वार करते हैं और एक शानदार केंद्र बनाते हैं। काले",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "उस घोड़े को d7 पर मोड़ते हैं, जहाँ वह e5 का साथ देता है और भविष्य के पलटवार के लिए c पैदल को आज़ाद करता है।",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "हमारा रानी-पक्ष का घोड़ा d2 पर विकसित होता है। काले का हाथी b7 पर जाता है और e4 पर निशाना साधता है। हाथी",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "c2 पर हमारे कीमती स्पेनिश हाथी को बचाता है और राजा पक्ष की ओर इशारा करता है। काले रखते हैं",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "रुक को e8 पर, e5 पैदल को और सहारा देते हुए। अंत में हमारा घोड़ा f1 पर सरकता है। उस घोड़े का",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "एक शानदार रास्ता है। f1 से वह g3 जा सकता है, f5 पर दबाव बढ़ाते हुए और मदद करते हुए",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "राजा-पक्ष के हमले को रफ्तार पकड़ने में। यही बंद ब्रेयर है। धैर्यवान, परिष्कृत और",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "जीवन और ऊर्जा से बिल्कुल भरी हुई। सफ़ेद के पास केंद्रीय जगह है। काले ने एक सघन",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "स्थिति बनाई है और पलटवार की तैयारी कर रहे हैं। विश्वास के साथ खेलो। हर चाल का आनंद लो",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "और याद रखो, शांत चालें इंतज़ार नहीं कर रही। वे स्प्रिंग लाद रही हैं।",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "अब तुम्हारी बारी: इसे तब तक दोहराओ जब तक उस घोड़े की यात्रा b1 से d2 और फिर f1 तक उतनी स्वाभाविक लगे जितना ढूँढना",
    "your way around London.":
      "लंदन में अपना रास्ता।",
    "Right then, the Sicilian Defence for Black.":
      "अच्छा, काले के लिए सिसिलियन रक्षा।",
    "White starts with 1. e4, claiming the centre.":
      "सफ़ेद एक बिंदु e4 से शुरू करता है और केंद्र पर दावा करता है।",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "काला एक बिंदु c5 से जवाब देता है, सीधे सफ़ेद की नकल करने के बजाय बगल से प्रहार करता है।",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "विचार है सफ़ेद की केंद्रीय महत्वाकांक्षाओं को चुनौती देना, सक्रिय रूप से विकसित होना, और शुरुआत से ही काउंटरप्ले बनाना।",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "एक आम रास्ता है 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6।",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "यह रहा: एक तीखी, लचीली रक्षा, जिसमें खूब काट है।",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "ठीक है, Sicilian की लाइन 1 में स्वागत है, Najdorf।",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "यह e4 पर मोहरे का काले का सबसे महत्वाकांक्षी जवाबों में से एक है।",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "सफेद e4 पर मोहरे से खोलता है, और काला तुरंत c5 पर मोहरे से वार करता है।",
    "White develops knight to f3.":
      "सफेद घोड़े को f3 पर विकसित करता है।",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "काला d6 पर मोहरा चलता है, और सफेद d4 पर मोहरे से केंद्र खोलता है।",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "काला c के मोहरे से d4 पर लेता है, सफेद घोड़े से d4 लेकर वापस लेता है।",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "काला घोड़े को f6 पर विकसित करता है, और सफेद दूसरा घोड़ा c3 पर लाता है।",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "अब प्रसिद्ध Najdorf चाल आती है, मोहरा a6 पर, एक लचीली छोटी चाल जिसके पीछे बहुत ज़हर है।",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "काला स्थिति को लचीला रखता है और रानी पक्ष पर फैलने की तैयारी करता है।",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "लाइन का पहला भाग है मोहरा e4, मोहरा c5, घोड़ा f3, मोहरा d6, मोहरा d4, मोहरा d4 लेता है, घोड़ा d4 लेता है, घोड़ा f6, घोड़ा c3, मोहरा a6, ऊंट e3, मोहरा e5, घोड़ा b3, ऊंट e6।",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "अब लाइन आगे बढ़ती है, मोहरा f3, ऊंट e7, रानी d2, छोटी रोकी, लंबी रोकी, घोड़ा bd7, मोहरा g4, मोहरा b5।",
    "White prepares a kingside assault with pawn to f3.":
      "सफेद f3 पर मोहरे से राजा पक्ष पर हमले की तैयारी करता है।",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "काला शांति से ऊंट को e7 पर विकसित करता है, फिर सफेद रानी को d2 पर लाता है।",
    "Black castles kingside and White castles queenside.":
      "काला राजा पक्ष में रोकी करता है और सफेद रानी पक्ष में रोकी करता है।",
    "Now the battle lines are drawn.":
      "अब युद्ध की रेखाएँ खिंच गई हैं।",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "काला घोड़े को bd7 पर विकसित करता है और सफेद g4 पर मोहरे से प्रसिद्ध मोहरा तूफान शुरू करता है।",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "काला b5 पर मोहरे से जवाब देता है और बस, Najdorf जीवंत हो उठी है।",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "सफेद राजा पक्ष पर सेना जुटा रहा है, काला रानी पक्ष पर बढ़ रहा है, और दोनों कुछ काफी खतरनाक तैयार कर रहे हैं।",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "ठीक है, चालों को ध्यान से देखें, होश रखें और इस शानदार Sicilian लाइन का आनंद लें।",
  },
  ja: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "よし——Scotch Gambit。きちんとしたオープンゲームのように始まる。e4、e5、ナイトを出し、それから白が d4 でセンターを突く。",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "黒が d4 で取ったとき、白はポーンを残してビショップを c4 に置ける。それがギャンビットだ。早く展開し、f7 を狙い、黒が整える前に圧力をかける。",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "Scotch の一族は、1820年代の Edinburgh–London 通信対戦から名がついた。愛好家が今もこのラインを好むのは、盤が開き、計画が具体的だからだ。長い静かな締めつけではない。",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "お茶をどうぞ。定跡の手をいっしょに練習しよう。本当の Scotch Gambit の道から外れないようにする。",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "では——ライン 1 へようこそ。Professor Potato Pie、お役に立ちます。",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "この学習パックでは、ギャンビットを注意深く選んだ十のラインにまとめた。",
    "10 lines from Opening Lab.":
      "Opening Lab の 10 ライン。",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "それらを学べば、理論を生き延びるだけではない。正しい手を自信をもって返し、均衡を保ち、対局にしっかり残れる。",
    "You get 10 lines from Opening Lab.":
      "Opening Lab の 10 ラインだ。",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "黒が踏み外したとき、なぜその手が悪いのかを見分け、正確な続きを選び、誤りを明確な優位に、ときにはかなり見事なチェックメイトに変えることを学ぶ。",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "もちろん、黒の指し方は十通りより多い。これは短い入門であって、網羅した百科ではない。手の並びを覚えるだけでなく、その論理だ。",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "パックを終えると、Scotch Gambit は現れるたびに見慣れたものになる。目印が分かり、計画が分かり、さらに学ぶ足場ができる。",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "楽しんで。急がず、すべてのラインを歩き、盤の前で会おう。",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "では、オープニングの罠だ。これらのラインはとても楽しく、ときに油断した相手を完全に不意打ちする。それだけでも知っておく価値がある。",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "だが、もっと真面目な点がある。罠を学ぶと警告のサインが見えるようになり、自分で踏み込みにくくなる。",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "各ラインを進み、その考えをつかみ、働いている小さな優雅な戦術の仕掛けを楽しもう。",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "判断して使い、きちんと理解し、機会が来たら精度に仕事をさせよう。",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "やってみて、楽しんで。さて、ポテトパイの時間だと思う。どうぞ。",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "では、ライン 1 へようこそ。これが Legal's Mate で、十八世紀のフランスのプレイヤー Monsieur de Légal にちなむ。",
    "White opens with the king's pawn, e4.": "白はキングのポーンで開く。e4。",
    "Black answers symmetrically with e5.": "黒は e5 で左右対称に答える。",
    "Knight to f3 attacks that pawn.": "ナイトが f3 へ行き、そのポーンを攻める。",
    "Black defends it with d6, which is the Philidor Defence.":
      "黒は d6 で守り、これが Philidor ディフェンスだ。",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "白のビショップが c4 に来て、弱い f7 のマスを見る。",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "黒のビショップが g4 に行き、ナイトをクイーンにピンする。",
    "White calmly develops, knight to c3.": "白は落ち着いて展開する。ナイトは c3 へ。",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "黒は g6 と指す。遅い手で、これで罠の用意ができた。",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "ナイトが e5 を取る！そのナイトはクイーンにピンされていただけで、キングにはピンされていない。だから自由に動ける。",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "黒は我慢できず、d1 のクイーンを取る。それが欲ばった取りで、致命的だ。",
    "Bishop takes f7, check!": "ビショップが f7 を取る、チェック！",
    "The king has only one square to go to, e7.": "キングが行けるマスは e7 だけだ。",
    "Knight to d5, and that's checkmate.": "ナイトが d5 へ、そしてチェックメイト。",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "ナイト二つとビショップ一つが、黒の全軍を破った。黒のクイーン、ルーク、d1 のビショップはまだ盤上にいるのに、誰も助けられない。",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "覚えておこう。こんなに早い段階でクイーンをただで出されたら、取る前にまわりをよく見ること。",
    "Now over to you. Practise it until your knights know the way.":
      "あとは君だ。ナイトが道を覚えるまで練習しよう。",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "ああ、また会ったね。Professor Potato Pie、お茶を手に。今日は Caro-Kann ディフェンスだ。たいへん粘り強く、作法は立派で、肘は意外なほど鋭いオープニング。",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "e4 c6 で始まり、名は Horatio Caro と Marcus Kann から来ている。十九世紀の二人のプレイヤーの分析が、この由緒あるディフェンスに顔を与えた。",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "戦略の前提は見事に節約的だ。黒は d5 を用意し、すぐに白のセンターに挑み、ポーンチェーンの後ろに閉じ込めるのではなく、白マスのビショップを自由にしておく。",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Caro-Kann は堅く、辛抱強く、構造も健全だ。だが落ち着きを受動と取り違えてはいけない。立派な外見の下には見事なカウンターがあり、白が欲を出しすぎたときに特にそうだ。",
    "You'll study 10 lines from Opening Lab.":
      "Opening Lab の 10 ラインを学ぶ。",
    "These are 10 lines from Opening Lab.":
      "これらは Opening Lab の 10 ラインだ。",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "Practice では、必要なところにヒントを出す。Test では助けが消え、残るのは君と局面と君の判断だけだ。",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "各ラインは、用意された定跡のラインが終わるところで終わる。そのあとコンピュータとの続きはない。",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "目的は、あてどなく指し続けることではない。手を身につけ、考えを理解し、盤に戻ったときに形を見分けることだ。",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "よし。お茶は落ち着き、駒は準備ができた。始めよう。",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "では、ライン 1、アドバンス・バリエーションへようこそ。白は e4 でセンターを主張する。",
    "We answer c6, preparing the thematic d5 advance.":
      "こちらは c6 と応え、主題の d5 前進を用意する。",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "白は d4 で広いセンターを作り、こちらはすぐ d5 で挑む。",
    "White pushes on to e5, gaining space.": "白は e5 まで押し、スペースを得る。",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "e6 でポーンチェーンを閉じる前に、ビショップは f5 へ逃げる。それが本質的に Caro-Kann の最初の良い家事だ。扉が閉まる前にビショップを出す。",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "続いてナイト f3、それから e6。ビショップが安全に出たので、e6 はもうまったく楽だ。",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "白は静かで堅実なビショップ e2 の配置を選ぶ。イギリスのグランドマスター Nigel Short が広めたシステムだ。",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "こちらは c5 で打ち、白のポーンチェーンの土台 d4 を攻める。",
    "White castles, and knight c6 adds another piece to the pressure.":
      "白はキャスリングし、ナイト c6 が圧力にもう一つ駒を加える。",
    "White reinforces d4 with c3.": "白は c3 で d4 を補強する。",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "こちらは d4 でポーンを交換し、cファイルを開け、カウンターに有用な道を与える。",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "残りのナイトは e7 へ展開し、f5 を目指す。そこで再び d4 を問える。",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "白はナイト c3 と指し、こちらのビショップが g4 からピンをかける。",
    "White answers with knight e1, breaking the pin.": "白はナイト e1 で応え、ピンを外す。",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "そこで白の有用な e2 のビショップを交換する。ナイトで取り返し、d4 はしっかり守られたままになる。",
    "Our knight settles on f5, still eyeing d4.":
      "こちらのナイトは f5 に落ち着き、なお d4 を見ている。",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "白はビショップ e3 でそれを守り、こちらは落ち着いてビショップを e7 へ出し、キャスリングの準備をする。",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "結果は、筋の通った計画のある互角の局面だ。d4 への圧力を保ち、cファイルを意図して使おう。",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "花火は要らない。健全な構造、辛抱強い圧力、そしてすべての駒が役に立っていればよい。",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "あとは君だ。手が記憶というより良識に感じるまで、ラインを繰り返そう。",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "よし、Professor Potato Pie だ。茶を持って、今日はロンドン・システムを少し見ていこう。",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "このオープニングは1922年のロンドン大会と密接に結びつき、この頼れる布陣が広く注目された。",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "そう、ふつうはポーンを d4、ナイトを f3、ビショップを f4 から始まる。",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "続いてポーンを e3、ポーンを c3、ナイトを d2、ビショップを d3、そしてキングサイドのキャスリングだ。",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "正確な手順は変わり得るが、その見慣れた陣形がロンドン・システムの核心だ。",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "堅実で分別のあるオープニングで、クラブプレイヤーもグランドマスターも指してきた。",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "よし、ロンドン・システムにもっと親しむのを楽しんで、駒がどう噛み合うか見ていこう。",
    "Right then, let's have a look at the first line in our London learning pack.":
      "よし、ロンドン学習パックの最初のラインを見ていこう。",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "これがロンドンのクランプだ。最初は静かだが、どの手にも狙いがある。",
    "We play pawn to d4 and black answers pawn to d5.":
      "私たちはポーンを d4 に進め、黒はポーンを d5 で応じる。",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "ビショップを f4、ナイトを f6、ポーンを e3、そして黒はポーンを c5 で突いてくる。",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "ポーンを c3 にして見慣れたピラミッドを組み、黒はナイトを c6 に展開する。",
    "Knight to d2 and black plays pawn to e6.": "ナイトを d2 へ、黒はポーンを e6 と指す。",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "もう一方のナイトが f3 に来て、そのあいだに黒のビショップは d6 に来る。",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "ビショップを g3 に戻し、有用で安全なまま保つ。",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "黒はキングサイドにキャスリングし、私たちはもう一方のビショップを d3 に置き、黒はポーンを b6 と指し、ここでナイトを e5 に植え付ける。見事な中央の前哨だ。",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "ビショップを b7、私たちはキングサイドにキャスリングし、黒はクイーンを c7 に置き、ポーンを f4 にしてクランプを完成させる。",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "これがその姿だ。引き締まったロンドンの局面で、中央はしっかり監視され、駒はキングサイドへ目を向け始める。",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "手が道順を覚えるまで繰り返し、静かなオープニングがいつの間に攻撃になったのか相手が不思議がるまで鍛えよう。",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "よし、こちらは Professor Potato Pie、紅茶を手に、今日はチェスで最も古く最も優雅なオープニングの一つ、イタリア・ゲームに会いに来た。",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "その考えは四世紀以上前にイタリアの棋士たちが研究し、このオープニングは今もあらゆるレベルのチェスに現れる。",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "白はポーンを e4 へ進め、黒はポーンを e5 へ、ナイトを f3 へ、ナイトを c6 へ、そしてビショップを c4 へ。",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "そのビショップは f7 を指す。黒のキングのそばにある繊細な小さなマスだ。",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "ここから黒はたいていビショップを c5 へ応じて Giuoco Piano に入り、あるいはナイトを f6 へ進めてツーナイツ・ディフェンスに至る。",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "イタリア・ゲームは古典的で生き生きとしており、自然な展開、中心の支配、そして攻撃の可能性の上に築かれている。",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "よし、イタリア・ゲームにもっと親しむのを楽しんで、c4 のビショップが私たちをどこへ連れていくか見ていこう。",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "よし、イタリア・ゲーム学習パックのライン 1 へようこそ。",
    "This is the quieter Italian.": "こちらが、より静かなイタリアだ。",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "入念な準備で十分なら、カーテンに火を付ける必要はない。",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "私たちはポーンを e4 へ進め、黒はポーンを e5 で応じる。",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "ナイトを f3、ナイトを c6、ビショップを c4、そして黒はビショップを c5 に展開する。",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "両方のビショップが古典的なポストに就き、センターを油断なく見守る。",
    "We play pawn to c3, preparing a future pawn to d4.":
      "私たちはポーンを c3 と指し、将来のポーンの d4 に備える。",
    "Black develops knight to f6 and places pressure on e4.":
      "黒はナイトを f6 に展開し、e4 に圧力をかける。",
    "Pawn to d3, pawn to d6.": "ポーンを d3、ポーンを d6。",
    "Both sides secure the centre before making any grand declarations.":
      "双方は大きな宣言をする前にセンターを固める。",
    "We castle king side.": "私たちはキングサイドにキャスリングする。",
    "Black plays pawn to a6.": "黒はポーンを a6 と指す。",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "私たちはポーンを a4 で応じ、クイーンサイドに少し空間を得て、ビショップは a7 に落ち着く。",
    "Knight to d2 and black castles king side.":
      "ナイトを d2 へ、そして黒はキングサイドにキャスリングする。",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "私たちはポーンを h3 と指し、ビショップが g4 で厄介になるのを防ぎ、キングに役立つ息継ぎのマスを与える。",
    "Black's knight moves to e7.": "黒のナイトは e7 へ動く。",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "ルークを e1 へ進めて e4 を補強し、ナイトは g6 へ続く。",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "ここまで来た。健全なイタリアの局面で、どの駒も役立つ仕事の準備をしている。",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "展開を続け、センターを見て、時機が来たら d4 の突破に備えよう。",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "手がやかんを火にかけるように自然になるまで、このラインを繰り返そう。",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "では、Professor Potato Pie です。お茶はきちんと淹れてあります。今日は偉大な古典的オープニングの一つ、クイーンズ・ギャンビットを紹介します。",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "このオープニングは十五世紀後半からチェスの文献に現れ、優れた棋士たちが何世代にもわたってセンターを争うために用いてきました。",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "白はポーンを d4 へ進め、黒はポーンを d5 で応じます。",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "それから白はポーンを c4 へ進め、黒の中央ポーンに挑み、c ポーンを差し出します。",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "ギャンビットと呼ばれますが、黒が受け取っても白はたいていポーンを取り戻せます、",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "ですからこれは無謀な寄贈というより戦略的な招待で、丁寧に出されながら裏の狙いがあります。",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "ここから黒はポーンを受け取るか、拒んで堅いセンターを保つかを選べます。",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "では、クイーンズ・ギャンビットにもっと親しむのを楽しみ、その冒険好きな小さな c ポーンが黒に何をさせるか見てみましょう。",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "では、クイーンズ・ギャンビット学習パックのライン 1 へようこそ。",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "これは本物の古典的チェスです。しっかりした土台、忍耐強い展開、そして部屋の向こうへ家具を投げ飛ばすことはありません。",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "ポーンを d4 から始め、黒はポーンを d5 で応じます。",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "ポーンを c4 へ進めてセンターに挑み、黒はポーンを e6 で応じます。",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "これがクイーンズ・ギャンビット・ディクラインドです。黒はこちらの申し出を受けるのではなく d5 のポーンを支えます。",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "ナイトを c3、ナイトを f6、ビショップを g5 へ進めてピンを作り、黒は落ち着いてビショップを e7 に展開します。",
    "We play pawn to e3 and black castles kingside.":
      "ポーンを e3 と指し、黒はキングサイドにキャスリングします。",
    "Knight to f3, knight to d7.": "ナイトを f3、ナイトを d7。",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "ルークを c1 に置き、c ファイルへ据え、そのあいだに黒はポーンを c6 と指して中央構造を強めます。",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "ビショップを d3 へ、そして黒はここで d5 からのポーンが c4 を取ることで緊張を解消します。",
    "Our bishop takes c4 recovering the pawn with development.":
      "こちらのビショップが c4 を取り、展開しながらポーンを取り戻します。",
    "Black's knight moves to d5 and occupies a strong central square.":
      "黒のナイトが d5 へ動き、強い中央のマスを占めます。",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "ビショップが e7 を取って交換し、黒のクイーンが e7 で取り返しします。",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "これがその姿です。バランスの取れたクイーンズ・ギャンビットの局面で、理にかなった展開と、センターにまだ多くの遊びがあります。",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "構造を学び、交換を理解し、前進する時は局面に教えてもらいましょう。",
    "Very civilised and quietly ambitious.": "とても上品で、静かに野心的です。",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "さて、Professor Potato Pie です。準備を整えて、今日はフレンチ・ディフェンスに会いましょう。キングポーンに対する黒の最も粘り強い受けは何でしょう。",
    "White begins with pawn to e4, we answer pawn to e6.":
      "白はポーンを e4 へ進め、私たちはポーンを e6 で応じます。",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "白はポーンを d4 へ進めてより多くの空間を取り、私たちは直ちにポーンを d5 で打ちます。",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "このオープニングの名は、1834年のロンドンとパリの通信試合に由来します。パリのチームがこのディフェンスを成功させたのです。",
    "Its character is patient, but hardly passive.": "その性格は辛抱強いものの、決して受動的ではありません。",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "黒は頑丈なポーンチェーンを築き、白に意図を明らかにさせ、それからポーンを c5 のような手で中央に挑み、機が熟せばポーンを f6 へ進めます。",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "私たちの白マスのビショップには少し外交が要るかもしれませんが、それもこのオープニングの繊細な構造の一部です。",
    "Solid, combative and rich in counterplay.": "堅実で、闘争的で、カウンタープレイに富んでいます。",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "フレンチは議論を急がず、一度に一つの精密な問いかけでそれを勝ち取ります。",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "では腰を据えて、ポーンブレイクに目を配り、フレンチ・ディフェンスに親しむ時間を楽しんでください。",
    "Right then, welcome to Line 1 of our French defence learning pack.": "さて、フレンチ・ディフェンス学習パックのライン 1 へようこそ。",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.": "正式な題はフレンチ・ディフェンス Winawer 変化、アドバンスの局面的本線で、私たちは黒側からこれを練習します。",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.": "白はポーンを e4 へ進め、私たちはポーンを e6 で応じ、白はポーンを d4 でセンターを取り、私たちはポーンを d5 で挑みます。",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "ナイトを c3 へ、それからビショップを b4 へ。これで Winawer の宣言です。",
    "We pin the knight and ask white how ambitious they're feeling.": "そのナイトをピンし、白がどれほど野心的に感じているかを問います。",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "白はポーンを e5 へ進め、私たちは直ちにポーンを c5 で反撃します。",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "白はポーンを a3 と指し、私たちのビショップに挑むので、ビショップは c3 を取ってチェックです。",
    "White recaptures with the b-pawn to c3.": "白は b ポーンで c3 に取り返しします。",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.": "白はビショップ・ペアと広いセンターを得ましたが、引き換えにダブル c ポーンを受け入れました。",
    "That trade-and-balance is the very grammar of the Winawer.": "この交換と均衡こそ、Winawer の文法そのものです。",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.": "私たちはナイトを e7 へ展開し、白はナイトを f3 へ展開し、私たちのビショップは d7 へ行きます。",
    "White plays pawn to a4, restraining queen side expansion.": "白はポーンを a4 と指し、クイーンサイドの拡大を抑えます。",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.": "私たちはクイーンを a5 で応じ、c3 に圧力をかけ、クイーンサイド・キャスリングへの道を開く助けをします。",
    "Bishop to d2 and our knight develops to c6.": "ビショップを d2 へ、そして私たちのナイトは c6 へ展開します。",
    "White places the bishop on d3, glancing rather impolitely at h7.": "白はビショップを d3 に置き、かなり無礼に h7 を見やります。",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "私たちはポーンを c4 へ進め、空間を得て、そのビショップを e2 へ戻します。",
    "Now comes pawn to f6, the characteristic French lever.": "ここでポーンを f6 へ。フレンチ特有のてこです。",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.": "私たちは白のセンターを眺めているだけではありません。その資格を示すよう求めています。",
    "White castles king side, black castles queen side.": "白はキングサイドにキャスリングし、黒はクイーンサイドにキャスリングします。",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.": "キングは今や反対側の翼に落ち着き、局面は見事に不均衡で、黒の計画は明確です。",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.": "e5 のポーンに挑み、役に立つラインを開き、明確な目的をもってクイーンサイドの活動を生み出します。",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.": "これが局面的な Winawer です。構造は堅実、意図は闘争的、そしてかなりの隠れた電気を帯びています。",
    "Your turn, drill it until the move order feels less like memory and more like common sense.": "あなたの番です。指し順が記憶ではなく常識のように感じるまで、繰り返し練習してください。",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "ちょうどそこだ、愛する者たちよ。Big Red だ。今日は Ruy Lopez をきちんと見ていく、",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "スペイン定跡とも呼ばれる。これには歴史がある。名前の由来は",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "Ruy Lopez de Segura、この定跡を研究したスペインの司祭にしてチェスの著者で、時代は",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "16世紀。白はポーンを e4 へ。黒はポーンを e5 で応える。ナイトを f3 へ",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "そのポーンを攻め、黒はナイトを c6 で守る。それからビショップが b5 へ。そして",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "これだ。Ruy Lopez。ビショップは e5 のポーンをすぐに取っているのではない。圧力をかけている",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "それを守るナイトに対して、黒に静かだが根強い問題を残す。",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "この優雅な小さな始まりから、チェスで最も壮大な定跡の家系の一つが育つ。",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "ある変化は穏やかで手を組むもの、別の変化はお茶を置く間もなく活発になり得る",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "君のお茶。古典的で繊細、きちんとした戦略思想に満ちている。古く、品位があり、それでもなお",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "可能性で賑わっている。ロンドンそのものに少し似ている。だから中央から目を離すな、",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "駒を大切にし、Ruy Lopez にもっと親しむのを楽しんでくれ。Big Red はまた会う。",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "さあ、愛する者たちよ。Big Red が盤に戻った。これは私たちの Ruy Lopez 学習パックの第1線、モーフィー・ディフェンスのクローズド Breyer 変化だ。",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "私たちは白の駒を持っていて、これは立派な戦略の傑作だ。",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "白はポーンを e4 へ進め、黒はポーンを e5 で応じ、Nf3 がそのポーンを攻め、黒は Nc6 で守る。",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5、そして Ruy Lopez が盤上にある。黒はポーンを a6 と指し、モーフィー・ディフェンスを告げる",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "そして私たちのビショップにごく直接的な問いを投げる。ビショップを a4 へ退く。黒は Nf6 を展開し、",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "私たちはキングサイドにキャスリングし、黒はビショップを e7 へ展開する。ルークを e1 へ、私たちの e4 ポーンを補強する",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "そしてルークを黒のキングの正面に置く。黒はポーンを b5 で広がり、そこで私たちのビショップは落ち着く",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "b3 に。ポーンを d6 へ。黒のセンターに頑丈な土台を与える。私たちはポーンを c3 と指し、",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "壮大な中央の前進、ポーンの d4 を準備する。黒はキングサイドにキャスリングする。さてポーンを h3 へ、",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "ビショップやナイトを g4 から遠ざけ、キングに少し息をつく余地を与える、役に立つ小さな一手だ。",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "それから Breyer を見分けさせる一手が来る。黒はナイトを b8 へ退く。",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "ナイトは出てきた理由を忘れたように見えるが、とんでもない。これは戦略的な",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "最高の再利用だ。私たちはポーンを d4 で突き、見事なセンターを築く。黒は",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "そのナイトを d7 へ回し、そこで e5 を支え、将来のカウンターのために c ポーンを自由にする。",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "私たちのクイーンサイドのナイトは d2 へ展開する。黒のビショップは b7 へ行き、e4 を狙う。ビショップ",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "を c2 へ。大切なスペインのビショップを保ち、キングサイドを指す。黒は",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "ルークを e8 に置き、e5 ポーンをさらに支える。最後に私たちのナイトは f1 へ滑る。そのナイトには",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "見事な旅程がある。f1 から g3 へ旅でき、f5 への圧力を高め、助けとなる",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "キングサイドの攻撃が勢いを集める。これがクローズド Breyer だ。忍耐強く、洗練されて、そして",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "生命とエネルギーに満ちている。白が中央の空間を持つ。黒は引き締まった",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "陣形を築き、反撃の準備をしている。確信を持って指せ。一手一手の機動を楽しめ",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "そして覚えておけ。静かな手は待っているのではない。ばねを仕込んでいるのだ。",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "あとは君だ。そのナイトの旅が b1 から d2、そして f1 まで、道を見つけるのと同じくらい自然に感じるまで繰り返せ",
    "your way around London.":
      "ロンドンの中を。",
    "Right then, the Sicilian Defence for Black.":
      "さあ、黒のシシリアン・ディフェンスです。",
    "White starts with 1. e4, claiming the centre.":
      "白はワンポイント e4 で始め、センターを主張します。",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "黒はワンポイント c5 で応え、白をそのまま真似るのではなく横から突きます。",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "狙いは白の中央の野心に挑み、積極的に駒を出し、最初からカウンタープレイを作ることです。",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "よくある道筋は 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6 です。",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "そこです。鋭く柔軟で、切れ味のある防御です。",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "さあ、Sicilian のライン 1、Najdorf へようこそ。",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "これは黒の、ポーンを e4 へ進める手への最も野心的な応手の一つです。",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "白はポーンを e4 へ進めて開始し、黒はすぐにポーンを c5 へ進めて側面から打ちます。",
    "White develops knight to f3.":
      "白はナイトを f3 へ展開します。",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "黒はポーンを d6 へ進め、白はポーンを d4 へ進めてセンターを開きます。",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "黒は c ポーンで d4 を取り、白はナイトが d4 を取って取り返しします。",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "黒はナイトを f6 へ展開し、白はもう一つのナイトを c3 へ連れてきます。",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "ここで有名な Najdorf の手、ポーンを a6 へ。柔軟な小さな手で、背後に強い毒があります。",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "黒は局面を柔軟に保ち、クイーンサイドでの拡張を準備します。",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "ラインの前半は、ポーンを e4、ポーンを c5、ナイトを f3、ポーンを d6、ポーンを d4、ポーンが d4 を取る、ナイトが d4 を取る、ナイトを f6、ナイトを c3、ポーンを a6、ビショップを e3、ポーンを e5、ナイトを b3、ビショップを e6。",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "ここからラインは続きます。ポーンを f3、ビショップを e7、クイーンを d2、キングサイドキャッスル、クイーンサイドキャッスル、ナイトを bd7、ポーンを g4、ポーンを b5。",
    "White prepares a kingside assault with pawn to f3.":
      "白はポーンを f3 へ進めてキングサイドの攻撃を準備します。",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "黒は落ち着いてビショップを e7 へ展開し、それから白はクイーンを d2 へ連れてきます。",
    "Black castles kingside and White castles queenside.":
      "黒はキングサイドにキャッスルし、白はクイーンサイドにキャッスルします。",
    "Now the battle lines are drawn.":
      "これで戦線が引かれました。",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "黒はナイトを bd7 へ展開し、白はポーンを g4 へ進めて有名なポーンストームを始めます。",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "黒はポーンを b5 へ進めて応え、Najdorf が生き生きと動き出します。",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "白はキングサイドに兵力を集め、黒はクイーンサイドを突き進み、両者ともかなり危険な何かを準備しています。",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "さあ、手をよく追い、油断せず、この見事な Sicilian のラインを楽しんでください。",
  },
  ar: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "حسنًا — Scotch Gambit. تبدأ كلعبة مفتوحة كما ينبغي: e4، ثم e5، الخيول تخرج، ثم يضرب الأبيض المركز بـ d4.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "عندما يأخذ الأسود على d4، يمكن للأبيض أن يترك البيدق ويغرس الفيل على c4. هذا هو الغامبت — طوّر بسرعة، صوّب نحو f7، وضع الأسود تحت الضغط قبل أن يرتّب وضعه.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "أخذت عائلة Scotch اسمها من مباريات المراسلة تلك بين Edinburgh–London في عشرينيات القرن التاسع عشر. ما زال الهواة يحبون هذا الخط لأن الرقعة تنفتح والخطط ملموسة — لا عصرًا طويلًا هادئًا.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "خذ شايك. تدرّب معي على حركات الكتاب — سأبقيك على طريق Scotch Gambit الحقيقي.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "حسنًا — أهلًا بك في الخط 1. Professor Potato Pie في خدمتك.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "في حزمة التعلّم هذه قطرنا الغامبت إلى عشرة خطوط مختارة بعناية.",
    "10 lines from Opening Lab.":
      "10 خطوط من Opening Lab.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "تعلّمها ولن تكتفي بالنجاة من النظرية. ستعيد الحركات الصحيحة بثقة، وتحفظ التوازن، وتبقى راسخًا في اللعبة.",
    "You get 10 lines from Opening Lab.":
      "تحصل على 10 خطوط من Opening Lab.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "عندما يزلّ الأسود، ستتعلم أن تتعرّف لماذا الحركة معيبة، وتختار المتابعة الدقيقة، وتحوّل الخطأ إلى أفضلية واضحة، وأحيانًا إلى كش مات رائع.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "بطبيعة الحال، للأسود أكثر من عشر طرق للعب. اعتبر هذا مدخلًا صغيرًا موجزًا لا موسوعة شاملة — منطق الحركات، لا مجرد تسلسل للحفظ.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "أكمل الحزمة وسيبدو Scotch Gambit مألوفًا كلما ظهر. ستتعرّف المعالم، وتفهم الخطط، ويكون لك أساس متين تتابع منه الدراسة.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "استمتع. خذ وقتك، وامشِ في كل خط، وأراك عند الرقعة.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "حسنًا، والآن فخاخ الافتتاح. هذه الخطوط ممتعة جدًا، وقد تفاجئ خصمًا غافلًا تمامًا. ذلك وحده يجعل معرفتها جديرة.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "لكن هناك نقطة أجدّ. دراسة الفخاخ تعلّمك أن تتعرّف علامات التحذير، فتقل كثيرًا فرصة أن تقع أنت في أحدها.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "اعمل في كل خط، وأمسك الفكرة وراءه، واستمتع بالآليات التكتيكية الصغيرة الأنيقة.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "استخدمها بحكم، وافهمها كما ينبغي، وعندما تسنح الفرصة دع الدقة تقوم بالعمل.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "جرّب، واستمتع، وأظن أن الوقت حان لفطيرة بطاطا. تفضّل.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "حسنًا، أهلًا بك في الخط 1. هذه Legal's Mate، وسمّيت باسم Monsieur de Légal، لاعب فرنسي من القرن الثامن عشر.",
    "White opens with the king's pawn, e4.": "يفتتح الأبيض ببيدق الملك، e4.",
    "Black answers symmetrically with e5.": "يجيب الأسود تناظريًا بـ e5.",
    "Knight to f3 attacks that pawn.": "حصان إلى f3 يهاجم ذلك البيدق.",
    "Black defends it with d6, which is the Philidor Defence.":
      "يدافع الأسود عنه بـ d6، وهذه دفاع Philidor.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "يأتي فيل الأبيض إلى c4 ويرنو إلى مربع f7 الضعيف الصغير.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "يذهب فيل الأسود إلى g4 ويثبّت الحصان على الملكة.",
    "White calmly develops, knight to c3.": "يطوّر الأبيض بهدوء، حصان إلى c3.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "يلعب الأسود g6. حركة بطيئة، والآن الفخ جاهز.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "الحصان يأخذ على e5! كان ذلك الحصان مثبّتًا على الملكة فقط، لا على الملك، فهو حر تمامًا في الحركة.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "لا يقاوم الأسود ويأخذ الملكة على d1. هذا هو الأخذ الطمّاع، وهو قاتل.",
    "Bishop takes f7, check!": "الفيل يأخذ على f7، كش!",
    "The king has only one square to go to, e7.": "لم يبق للملك إلا مربع واحد، e7.",
    "Knight to d5, and that's checkmate.": "حصان إلى d5، وهذا كش مات.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "حصانان وفيل واحد هزموا جيش الأسود كله. ملكة الأسود والقلاع والفيل على d1 ما زالوا على الرقعة، ولا يستطيع أحدهم المساعدة.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "فتذكّر: إذا عُرضت ملكة مجانًا في هذا الوقت المبكر، انظر حولك جيدًا قبل أن تأخذها.",
    "Now over to you. Practise it until your knights know the way.":
      "الآن دورك. تدرّب حتى تعرف خيولك الطريق.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "آه، مرحبًا من جديد. Professor Potato Pie، الشاي في يده. واليوم نلتفت إلى دفاع Caro-Kann، افتتاح شديد الصلابة، حسن الأدب، ومرفقاه حادّان على نحو مفاجئ.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "يبدأ بـ e4 c6، ويأخذ اسمه من Horatio Caro و Marcus Kann، لاعبين من القرن التاسع عشر منح عملهما التحليلي هذه الدفاع العريق هويته.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "المقدمة الاستراتيجية مقتصدة على نحو يثير الإعجاب. يجهّز الأسود d5، متحديًا مركز الأبيض فورًا، ويبقي فيل المربعات الفاتحة حرًا بدل حبسه خلف سلسلة البيادق.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Caro-Kann صلبة وصبورة وسليمة البنية، لكن لا تخلط بين الاتزان والسلبية. تحت المظهر المحترم مجموعة جميلة من الضربات المضادة، خصوصًا إذا طمع الأبيض.",
    "You'll study 10 lines from Opening Lab.":
      "ستدرس 10 خطوط من Opening Lab.",
    "These are 10 lines from Opening Lab.":
      "هذه 10 خطوط من Opening Lab.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "في Practice سأقدّم تلميحات حيث تحتاجها. في Test تختفي المساعدة، ويبقى أنت والوضع وحكمك.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "ينتهي كل خط حيث تنتهي خط الكتاب المجهّزة. لا متابعة بعد ذلك ضد الحاسوب.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "الغرض ليس أن تواصل اللعب بلا هدف، بل أن تمتص الحركات، وتفهم الأفكار، وتتعرّف الأنماط حين تعود إلى الرقعة.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "حسنًا. الشاي مستقر، والقطع جاهزة. لنبدأ.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "حسنًا، أهلًا بك في الخط 1، تنويعة التقدم. يطالب الأبيض بالمركز بـ e4.",
    "We answer c6, preparing the thematic d5 advance.": "نجيب c6، مجهّزين تقدم d5 الموضوعي.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "يقيم الأبيض مركزًا عريضًا بـ d4، ونتحداه فورًا بـ d5.",
    "White pushes on to e5, gaining space.": "يدفع الأبيض إلى e5 ويكسب مساحة.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "قبل إغلاق سلسلة البيادق بـ e6، يفلت فيلنا إلى f5. ذلك، في جوهره، أول تدبير حسن في Caro-Kann. يخرج الفيل قبل أن يُغلق الباب.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "يتبع حصان f3، ثم e6. وبعد أن تطوّر الفيل بأمان، صار e6 مريحًا تمامًا.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "يختار الأبيض ترتيب الفيل e2 الهادئ العاقل، وهو نظام أشاعه الأستاذ الكبير الإنجليزي Nigel Short.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "نضرب بـ c5، مهاجمين قاعدة سلسلة بيادق الأبيض على d4.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "يبيّت الأبيض، وحصان c6 يضيف قطعة أخرى إلى الضغط.",
    "White reinforces d4 with c3.": "يعزّز الأبيض d4 بـ c3.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "نبادل البيادق على d4، فنفتح عمود c ونعطي لعبتنا المضادة طريقًا مفيدًا.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "يتطوّر الحصان الباقي إلى e7، قاصدًا f5، حيث يستطيع أن يسأل d4 من جديد.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "يلعب الأبيض حصان c3، وفيلنا يطبّق التثبيت من g4.",
    "White answers with knight e1, breaking the pin.": "يجيب الأبيض بحصان e1، ويكسر التثبيت.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "لذلك نبادل فيل الأبيض المفيد على e2. الاستعادة بالحصان تُبقي d4 محميًا بأمان.",
    "Our knight settles on f5, still eyeing d4.": "يستقر حصاننا على f5، وما زال يرمق d4.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "يحميه الأبيض بفيل e3، ونطوّر بهدوء الفيل إلى e7، جاهزين للتبييت.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "النتيجة وضع متعادل بخطة متماسكة. أبقِ الضغط على d4 واستخدم عمود c بقصد.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "لا حاجة إلى ألعاب نارية، فقط بنية سليمة وضغط صبور وكل قطعة موظّفة بما ينفع.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "الآن دورك. كرّر الخط حتى تشعر الحركات بأنها حسن تقدير أكثر منها ذاكرة.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "حسنًا، هنا Professor Potato Pie، والشاي في اليد، واليوم نلقي نظرة موجزة على نظام لندن.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "ارتبط هذا الافتتاح ارتباطًا وثيقًا ببطولة لندن الكبرى عام 1922، حيث جذب هذا الترتيب الموثوق انتباهًا أوسع.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "حسنًا، يبدأ عادة ببيدق إلى d4، وحصان إلى f3، وفيل إلى f4.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "ثم بيدق إلى e3، وبيدق إلى c3، وحصان إلى d2، وفيل إلى d3، والتبييت القصير.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "قد يتغير الترتيب الدقيق، لكن ذلك التشكيل المألوف هو قلب نظام لندن.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "إنه افتتاح متين وعاقل، لعبه لاعبو الأندية وأساتذة الكبار على السواء.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "حسنًا، استمتع بالتعرّف أكثر على نظام لندن، ولنرَ كيف تتآلف القطع.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "حسنًا، لنلقِ نظرة على الخط الأول في حزمة تعلّم لندن.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "هذه كماشة لندن، هادئة في البداية، لكن في كل نقلة منهج.",
    "We play pawn to d4 and black answers pawn to d5.":
      "نلعب بيدقًا إلى d4 ويجيب الأسود ببيدق إلى d5.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "فيل إلى f4، حصان إلى f6، بيدق إلى e3، ويضرب الأسود ببيدق إلى c5.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "نبني الهرم المألوف ببيدق إلى c3، ويطوّر الأسود الحصان إلى c6.",
    "Knight to d2 and black plays pawn to e6.": "حصان إلى d2 ويلعب الأسود بيدقًا إلى e6.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "يأتي حصاننا الآخر إلى f3، بينما يأتي فيل الأسود إلى d6.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "نُرجع فيلنا إلى g3، نبقيه مفيدًا وآمنًا.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "يبيت الأسود على جانب الملك، ونضع فيلنا الآخر على d3، ويلعب الأسود بيدقًا إلى b6، والآن نغرس الحصان في e5، موقعًا مركزيًا رائعًا.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "فيل إلى b7، نبيت على جانب الملك، يضع الأسود الملكة على c7 ونُكمل الكماشة ببيدق إلى f4.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "ها هي، وضعية لندن متماسكة، والمركز تحت رقابة ثابتة، وقطعنا تبدأ في النظر نحو جانب الملك.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "كرّرها حتى تعرف يدك الطريق ويتساءل خصمك متى صار الافتتاح الهادئ هجومًا.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "حسنًا، هنا Professor Potato Pie، الشاي في اليد، واليوم نلتقي بإحدى أقدم افتتاحيات الشطرنج وأكثرها أناقة، الافتتاح الإيطالي.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "درس أفكارها الأساتذة الإيطاليون قبل أكثر من أربعة قرون، وما زالت هذه الافتتاحية تظهر في كل مستويات الشطرنج اليوم.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "يبدأ الأبيض ببيدق إلى e4، ويرد الأسود ببيدق إلى e5، وحصان إلى f3، وحصان إلى c6، ثم فيل إلى c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "ذلك الفيل يشير نحو f7، المربع الصغير الحساس بجانب ملك الأسود.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "من هنا يرد الأسود عادة بفيل إلى c5، داخلًا Giuoco Piano، أو بحصان إلى f6، وصولًا إلى دفاع الحصانين.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "الافتتاح الإيطالي كلاسيكي وحيوي، ومبني على التطوير الطبيعي والسيطرة على المركز وإمكانات الهجوم.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "حسنًا، استمتع بالتعرّف أكثر على الافتتاح الإيطالي، ولنرَ إلى أين يأخذنا ذلك الفيل على c4.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "حسنًا، أهلًا بك في الخط 1 من حزمة تعلّم الافتتاح الإيطالي.",
    "This is the quieter Italian.": "هذه هي الإيطالية الأكثر هدوءًا.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "لا داعي لإضرام النار في الستائر حين تكفي العناية في التحضير.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "نبدأ ببيدق إلى e4، ويرد الأسود ببيدق إلى e5.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "حصان إلى f3، حصان إلى c6، فيل إلى c4، ويطوّر الأسود الفيل إلى c5.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "يتخذ الفيلان موقعيهما الكلاسيكيين ويبقيان عينًا يقظة على المركز.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "نلعب بيدقًا إلى c3، مهيئين لبيدق مستقبلي إلى d4.",
    "Black develops knight to f6 and places pressure on e4.":
      "يطوّر الأسود الحصان إلى f6 ويضع ضغطًا على e4.",
    "Pawn to d3, pawn to d6.": "بيدق إلى d3، بيدق إلى d6.",
    "Both sides secure the centre before making any grand declarations.":
      "يؤمّن الطرفان المركز قبل أي تصريحات كبيرة.",
    "We castle king side.": "نبيت على جانب الملك.",
    "Black plays pawn to a6.": "يلعب الأسود بيدقًا إلى a6.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "نجيب ببيدق إلى a4، نكسب قليلًا من الفضاء على جانب الملكة، ويستقر الفيل على a7.",
    "Knight to d2 and black castles king side.": "حصان إلى d2 ويبيت الأسود على جانب الملك.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "نلعب بيدقًا إلى h3، نمنع فيلًا من أن يصبح مزعجًا على g4، ونمنح ملكنا مربعًا مفيدًا للتنفس.",
    "Black's knight moves to e7.": "ينتقل حصان الأسود إلى e7.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "القلعة إلى e1 تعزز e4، ويتابع الحصان إلى g6.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "ها نحن، وضعية إيطالية سليمة، وكل قطعة تستعد لعمل مفيد.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "واصل التطوير، راقب المركز، وكن مستعدًا لاختراق d4 حين يحين الوقت.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "كرّر الخط حتى تشعر بالنقلات طبيعية كوضع الغلاية.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "حسنًا، هنا Professor Potato Pie، والشاي مُعد كما ينبغي، واليوم نقدم إحدى الافتتاحيات الكلاسيكية العظيمة، غامبيت الملكة.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "ظهرت هذه الافتتاحية في كتابات الشطرنج منذ أواخر القرن الخامس عشر، واستخدمتها أجيال من اللاعبين المميزين لمنازعة المركز.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "يبدأ الأبيض ببيدق إلى d4، ويرد الأسود ببيدق إلى d5.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "ثم يلعب الأبيض بيدقًا إلى c4، متحديًا بيدق الأسود المركزي وعارضًا بيدق c.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "يُسمى غامبيتًا، مع أن الأبيض يستطيع عادة استعادة البيدق إذا قبله الأسود،",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "فهذا أقل ما يكون هبة طائشة وأكثر ما يكون دعوة استراتيجية، تُقدَّم بأدب لكن بدوافع خفية.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "من هنا قد يقبل الأسود البيدق أو يرفضه ويحافظ على مركز متين.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "حسنًا، استمتع بالتعرّف أكثر على غامبيت الملكة ولنرَ ماذا يستطيع ذلك البيدق c الصغير المغامر أن يقنع الأسود بفعله.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "حسنًا، أهلًا بك في الخط 1 من حزمة تعلّم غامبيت الملكة.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "هذا شطرنج كلاسيكي كما ينبغي: أسس راسخة، وتطوير صبور، ولا أثاث يُقذف عبر الغرفة.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "نبدأ ببيدق إلى d4 ويجيب الأسود ببيدق إلى d5.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "بيدق إلى c4 يتحدى المركز ويرد الأسود ببيدق إلى e6.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "هذا غامبيت الملكة المرفوض. يدعم الأسود بيدق d5 بدلًا من قبول عرضنا.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "حصان إلى c3، حصان إلى f6، فيل إلى g5 يصنع التثبيت، ويطوّر الأسود بهدوء الفيل إلى e7.",
    "We play pawn to e3 and black castles kingside.":
      "نلعب بيدقًا إلى e3 ويبيت الأسود على جانب الملك.",
    "Knight to f3, knight to d7.": "حصان إلى f3، حصان إلى d7.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "قلعة إلى c1 تضع القلعة على عمود c بينما يلعب الأسود بيدقًا إلى c6 ويقوّي البنية المركزية.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "فيل إلى d3 والآن يحل الأسود التوتر ببيدق من d5 يأخذ c4.",
    "Our bishop takes c4 recovering the pawn with development.":
      "فيلنا يأخذ c4 مستعيدًا البيدق مع التطوير.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "ينتقل حصان الأسود إلى d5 ويحتل مربعًا مركزيًا قويًا.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "نبادل بفيل يأخذ e7 وتستعيد ملكة الأسود على e7.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "ها هي، وضعية متوازنة لغامبيت الملكة بتطوير معقول وما زال كثير من اللعب في المركز.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "تعلّم البنية، وافهم التبادلات، ودع الوضعية تخبرك متى يحين وقت التقدم.",
    "Very civilised and quietly ambitious.": "متحضّر جدًا وطموح بهدوء.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "حسنًا، هنا Professor Potato Pie، أجهّزك، واليوم نلتقي بالدفاع الفرنسي: ما أشد ردود الأسود صمودًا على بيدق الملك؟",
    "White begins with pawn to e4, we answer pawn to e6.": "يبدأ الأبيض ببيدق إلى e4، ونرد ببيدق إلى e6.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "يأخذ الأبيض مساحة أكبر ببيدق إلى d4، ونضرب فورًا ببيدق إلى d5.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "أخذت الافتتاحية اسمها من مباراة بالمراسلة بين لندن وباريس عام 1834، حين استخدم فريق باريس الدفاع بنجاح.",
    "Its character is patient, but hardly passive.": "طابعها صبور، لكنه أبعد ما يكون عن السلبية.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "يبني الأسود سلسلة بيادق متينة، ويدعو الأبيض إلى إعلان نواياه، ثم يتحدى المركز بنقلات مثل بيدق إلى c5 وحين يحين الوقت بيدق إلى f6.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "قد يحتاج فيلنا ذو المربعات الفاتحة إلى قليل من الدبلوماسية، لكن ذلك جزء من عمارة الافتتاحية الدقيقة.",
    "Solid, combative and rich in counterplay.": "صلب، قتالي، وغني باللعب المضاد.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "الفرنسية لا تستعجل الجدال، بل تربحه سؤالًا دقيقًا في كل مرة.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "فاستقر، وأبقِ عينك على كسور البيادق، واستمتع بأن تصبح أكثر ألفة مع الدفاع الفرنسي.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "حسنًا، أهلًا بك في الخط 1 من حزمة تعلّم الدفاع الفرنسي.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "العنوان الصحيح هو الدفاع الفرنسي، تنويع Winawer، الخط الرئيسي الموضعي للتقدم، وندرّبه من جانب الأسود.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "يبدأ الأبيض ببيدق إلى e4، ونرد ببيدق إلى e6، ويأخذ الأبيض المركز ببيدق إلى d4 ونتحداه ببيدق إلى d5.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "حصان إلى c3، ثم فيل إلى b4: هذا يعلن Winawer.",
    "We pin the knight and ask white how ambitious they're feeling.": "نثبّت الحصان ونسأل الأبيض عن مدى طموحهم.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "يتقدم الأبيض ببيدق إلى e5، ونرد فورًا ببيدق إلى c5.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "يلعب الأبيض بيدق إلى a3 متحديًا فيلنا، فيأخذ الفيل c3، كش.",
    "White recaptures with the b-pawn to c3.": "يستعيد الأبيض ببيدق b إلى c3.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.": "كسب الأبيض زوج الفيلة ومركزًا واسعًا، لكنه قبل في المقابل بيادق c مضاعفة.",
    "That trade-and-balance is the very grammar of the Winawer.": "هذا التبادل والتوازن هو نحو Winawer نفسه.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.": "نطوّر الحصان إلى e7، ويطوّر الأبيض الحصان إلى f3، ويذهب فيلنا إلى d7.",
    "White plays pawn to a4, restraining queen side expansion.": "يلعب الأبيض بيدق إلى a4، مقيّدًا التوسع في جناح الملكة.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.": "نرد بالملكة إلى a5، ضاغطين على c3 ومساعدين على إخلاء الطريق للتبييت في جناح الملكة.",
    "Bishop to d2 and our knight develops to c6.": "فيل إلى d2 ويتطور حصاننا إلى c6.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "يضع الأبيض الفيل على d3، ناظرًا بوقاحة إلى حد ما نحو h7.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "نتقدم ببيدق إلى c4، نكسب مساحة ونعيد ذلك الفيل إلى e2.",
    "Now comes pawn to f6, the characteristic French lever.": "والآن بيدق إلى f6، رافعة الفرنسي المميزة.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.": "لسنا نكتفي بالإعجاب بمركز الأبيض، بل نطلب منه أن يقدّم أوراق اعتماده.",
    "White castles king side, black castles queen side.": "يبيّت الأبيض في جناح الملك، ويبيّت الأسود في جناح الملكة.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "استقر الملكان الآن على جناحين متقابلين، والوضعية غير متوازنة على نحو رائع، وخطة الأسود واضحة.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.": "تحدَّ بيدق e5، وافتح خطوطًا مفيدة، وولّد نشاطًا في جناح الملكة بغرض واضح.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "هذه هي Winawer الموضعية: متينة في بنائها، قتالية في قصدها، وتحمل قدرًا كبيرًا من الكهرباء المخبوءة.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.": "دورك: كرّرها حتى يبدو ترتيب النقلات أقل شبهًا بالذاكرة وأكثر شبهًا بالبديهة.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "هنا تمامًا يا أحبائي. Big Red هنا. واليوم نلقي نظرة كما ينبغي على Ruy Lopez،",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "المعروفة أيضًا بالافتتاح الإسباني. في هذه تاريخ. وهي تأخذ اسمها",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "من Ruy Lopez de Segura، كاهن إسباني وكاتب شطرنج درس الافتتاح في",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "القرن السادس عشر. يبدأ الأبيض ببيدق إلى e4. يرد الأسود ببيدق إلى e5. حصان إلى f3",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "يهاجم ذلك البيدق ويدافع الأسود بحصان إلى c6. ثم يأتي الفيل إلى b5. وها",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "قد صارت. Ruy Lopez. الفيل لا يربح بيدق e5 فورًا. إنه يضغط",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "على الحصان الذي يحرسه، ويمنح الأسود مشكلة هادئة لكنها مستمرة.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "من هذه البداية الأنيقة الصغيرة تنمو إحدى أعظم عائلات الافتتاح في الشطرنج.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "بعض الخطوط هادئة ومناورة، وأخرى قد تنشط قبل أن يتسع وقتك لتضع",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "الشاي. إنها كلاسيكية ودقيقة ومليئة بأفكار استراتيجية حقيقية. قديمة ووقورة وما زالت",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "زاخرة بالاحتمالات. تشبه لندن نفسها قليلًا. فابقِ عينك على المركز،",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "اعتنِ بقطعك واستمتع بأن تصبح أكثر ألفة مع Ruy Lopez. Big Red سيراك لاحقًا.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "حسنًا يا أحبائي، Big Red عاد إلى الرقعة وهذه هي الخط 1 من حزمة تعلّم Ruy Lopez، دفاع مورفي، تنويعة Breyer المغلقة.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "نلعب بالقطع البيضاء وهذه تحفة استراتيجية بحق.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "يبدأ الأبيض ببيدق إلى e4، ويرد الأسود ببيدق إلى e5، و Nf3 يهاجم البيدق ويدافع الأسود عنه بـ Nc6.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 و Ruy Lopez على الرقعة. يلعب الأسود بيدقًا إلى a6، معلنًا دفاع مورفي",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "ويطرح على فيلنا سؤالًا مباشرًا جدًا. نتراجع بالفيل إلى a4. يطوّر الأسود Nf6،",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "نبيّت في جناح الملك ويطوّر الأسود الفيل إلى e7. القلعة إلى e1 تعزّز بيدق e4",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "وتضع القلعة مقابل ملك الأسود. يتوسع الأسود ببيدق إلى b5، فيستقر فيلنا",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "على b3. بيدق إلى d6 يمنح مركز الأسود أساسًا متينًا. نلعب بيدقًا إلى c3،",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "مهيّئين التقدم المركزي الكبير، بيدق إلى d4. يبيّت الأسود في جناح الملك. والآن بيدق إلى h3،",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "نقلة صغيرة مفيدة تُبعد فيلًا أو حصانًا عن g4 وتمنح ملكنا متسعًا للتنفس.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "ثم تأتي النقلة التي تجعل Breyer لا تُخطئ. يتراجع الأسود بالحصان إلى b8.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "يبدو كأن الحصان نسي لماذا خرج، لكن أبدًا. هذا تدوير",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "استراتيجي من أعلى طراز. نضرب ببيدق إلى d4 ونقيم مركزًا رائعًا. الأسود",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "يعيد توجيه ذلك الحصان إلى d7، حيث يدعم e5 ويحرر بيدق c للهجوم المضاد لاحقًا.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "يتطور حصان جناح الملكة لدينا إلى d2. يذهب فيل الأسود إلى b7 ويصوب نحو e4. الفيل",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "إلى c2 يحفظ فيلنا الإسباني الثمين ويشير نحو جناح الملك. يضع الأسود",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "القلعة على e8، مضيفًا مزيدًا من الدعم لبيدق e5. وأخيرًا ينزلق حصاننا إلى f1. لذلك الحصان",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "مسار رائع. من f1 يمكنه السفر إلى g3، فيزيد الضغط على f5 ويساعد",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "هجوم جناح الملك على جمع الزخم. هذه هي Breyer المغلقة. صبورة، راقية و",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "طافحة بالحياة والطاقة. الأبيض يملك الفضاء المركزي. بنى الأسود وضعية متماسكة",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "ويُعد الضربة المضادة. العبها باقتناع. استمتع بكل مناورة",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "وتذكّر: النقلات الهادئة لا تنتظر. إنها تشحن النابض.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "دورك: كرّرها حتى تبدو رحلة ذلك الحصان من b1 إلى d2 ثم إلى f1 طبيعية كالعثور على",
    "your way around London.":
      "طريقك في لندن.",
    "Right then, the Sicilian Defence for Black.":
      "حسنًا، الدفاع الصقلي للأسود.",
    "White starts with 1. e4, claiming the centre.":
      "يبدأ الأبيض بنقطة e4 ويطالب بالمركز.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "يرد الأسود بنقطة c5، ضاربًا من الجانب بدل نسخ الأبيض مباشرة.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "الفكرة هي تحدي طموح الأبيض في المركز، والتطوير بنشاط، وخلق لعب مضاد منذ البداية.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "طريق شائع هو 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "ها أنت: دفاع حاد ومرن، وفيه الكثير من العض.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "حسنًا، أهلًا بك في الخط 1 من Sicilian، Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "هذا أحد أكثر ردود الأسود طموحًا على البيدق إلى e4.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "يبدأ الأبيض بالبيدق إلى e4، ويضرب الأسود فورًا بالبيدق إلى c5.",
    "White develops knight to f3.":
      "يطوّر الأبيض الحصان إلى f3.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "يلعب الأسود البيدق إلى d6، ويفتح الأبيض المركز بالبيدق إلى d4.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "يأخذ الأسود على d4 ببيدق c، ويستعيد الأبيض بالحصان يأخذ d4.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "يطوّر الأسود الحصان إلى f6، ويجلب الأبيض الحصان الآخر إلى c3.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "الآن تأتي نقلة Najdorf الشهيرة، البيدق إلى a6، نقلة صغيرة مرنة وراءها قدر كبير من السم.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "يبقي الأسود الوضع قابلًا للتكيف ويستعد للتوسع في جناح الملكة.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "الجزء الأول من الخط هو البيدق إلى e4، البيدق إلى c5، الحصان إلى f3، البيدق إلى d6، البيدق إلى d4، البيدق يأخذ d4، الحصان يأخذ d4، الحصان إلى f6، الحصان إلى c3، البيدق إلى a6، الفيل إلى e3، البيدق إلى e5، الحصان إلى b3، الفيل إلى e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "الآن يستمر الخط، البيدق إلى f3، الفيل إلى e7، الملكة إلى d2، التبييت الصغير، التبييت الكبير، الحصان إلى bd7، البيدق إلى g4، البيدق إلى b5.",
    "White prepares a kingside assault with pawn to f3.":
      "يجهّز الأبيض هجومًا على جناح الملك بالبيدق إلى f3.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "يطوّر الأسود بهدوء الفيل إلى e7، ثم يجلب الأبيض الملكة إلى d2.",
    "Black castles kingside and White castles queenside.":
      "يبيّت الأسود على جناح الملك ويبيّت الأبيض على جناح الملكة.",
    "Now the battle lines are drawn.":
      "الآن رُسمت خطوط المعركة.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "يطوّر الأسود الحصان إلى bd7 ويبدأ الأبيض عاصفة البيادق الشهيرة بالبيدق إلى g4.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "يرد الأسود بالبيدق إلى b5 وها هي Najdorf قد انبعثت حيّة.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "يجمع الأبيض قواته على جناح الملك، ويندفع الأسود على جناح الملكة، وكلاهما يجهّز شيئًا خطيرًا إلى حد ما.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "حسنًا، تابع النقلات عن كثب، وابقَ يقظًا واستمتع بهذا الخط Sicilian الرائع.",
  },
  tr: {
    "Right — Scotch Gambit. It starts like a proper open game: e4, e5, knights out, then White hits the centre with d4.":
      "Peki — Scotch Gambit. Düzgün bir açık oyun gibi başlar: e4, e5, atlar çıkar, sonra Beyaz merkeze d4 ile vurur.",
    "When Black takes on d4, White can leave the pawn and plant the bishop on c4. That is the gambit — develop fast, aim at f7, and put Black under pressure before they tidy up.":
      "Siyah d4'te alınca, Beyaz piyonu bırakıp fili c4'e dikebilir. Gambit budur — çabuk geliş, f7'yi hedefle ve Siyah toparlanmadan baskı kur.",
    "The Scotch family got its name from those Edinburgh–London correspondence matches in the eighteen-twenties. Hobbyists still love this line because the board opens up and the plans are concrete — not a long quiet squeeze.":
      "Scotch ailesi adını 1820'lerin Edinburgh–London yazışma maçlarından alır. Meraklılar bu hattı hâlâ sever, çünkü tahta açılır ve planlar somuttur — uzun sessiz bir sıkıştırma değil.",
    "Grab your tea. Practice the book moves with me — I'll keep you on the real Scotch Gambit path.":
      "Çayını al. Kitap hamlelerini benimle çalış — seni gerçek Scotch Gambit yolunda tutarım.",
    "Right then — welcome to Line 1. Professor Potato Pie, at your service.":
      "Peki — Hat 1'e hoş geldin. Professor Potato Pie, hizmetinde.",
    "In this learning pack, we've distilled the gambit into ten carefully selected lines.":
      "Bu öğrenme paketinde gambiti özenle seçilmiş on hatta damıttık.",
    "10 lines from Opening Lab.":
      "Opening Lab'den 10 hat.",
    "Learn those and you won't merely survive the theory. You'll return the correct moves with confidence, keep the balance, and stay firmly in the game.":
      "Onları öğren, teoriye yalnızca dayanmakla kalmazsın. Doğru hamleleri güvenle geri verir, dengeyi korur ve oyunda sağlam durursun.",
    "You get 10 lines from Opening Lab.":
      "Opening Lab'den 10 hat alırsın.",
    "When Black slips, you'll learn to recognise why the move is faulty, choose the precise continuation, convert the error into a clear advantage and, on occasion, a rather exquisite checkmate.":
      "Siyah kayınca, hamlenin neden kusurlu olduğunu görmeyi, kesin devamı seçmeyi, hatayı açık üstünlüğe ve ara sıra oldukça zarif bir mata çevirmeyi öğrenirsin.",
    "Naturally, Black has more than ten ways to play. Think of this as a compact, bite-sized primer rather than an exhaustive encyclopedia — the logic behind the moves, not simply a sequence to memorise.":
      "Doğal olarak Siyah'ın ondan fazla oynama yolu vardır. Bunu eksiksiz bir ansiklopedi değil, kısa bir başlangıç say — hamlelerin ardındaki mantık, yalnızca ezberlenecek bir dizi değil.",
    "Complete the pack and the Scotch Gambit will look familiar whenever it appears. You'll recognise the landmarks, understand the plans, and have a proper footing from which to take your study further.":
      "Paketi bitir, Scotch Gambit her göründüğünde tanıdık gelir. İşaretleri tanırsın, planları anlarsın ve çalışmayı ileri götürecek sağlam bir zeminin olur.",
    "Enjoy it. Take your time, walk through every line, and I'll see you at the board.":
      "Tadını çıkar. Acele etme, her hattı yürü, tahtada görüşürüz.",
    "Right then, now for the opening traps. These lines are great fun, and on occasion they can catch an unsuspecting opponent completely off guard. That alone makes them worth knowing.":
      "Peki, şimdi açılış tuzakları. Bu hatlar çok eğlencelidir ve bazen habersiz bir rakibi tamamen hazırlıksız yakalar. Yalnızca bu yüzden bilinmeye değerler.",
    "But there is a more serious point. Studying traps teaches you to recognise the warning signs, so you're far less likely to wander into one yourself.":
      "Ama daha ciddi bir nokta var. Tuzak çalışmak uyarı işaretlerini tanımayı öğretir, böylece kendin birine düşmen çok daha az olasıdır.",
    "Work through each line, grasp the idea behind it, and enjoy the elegant little tactical mechanisms at play.":
      "Her hattı işle, ardındaki fikri kavra ve işleyen zarif küçük taktik düzeneklerin tadını çıkar.",
    "Use them with judgement, understand them properly, and when the opportunity presents itself, let precision do the work.":
      "Onları muhakemeyle kullan, iyice anla ve fırsat gelince kesinliğin işi yapmasına izin ver.",
    "Have a go, have some fun, and now I think it's time for a potato pie. Enjoy.":
      "Bir dene, eğlen, ve sanırım şimdi bir patates turtası zamanı. Afiyet olsun.",
    "Right then, welcome to Line 1. This is Legal's Mate, named after Monsieur de Légal, a French player of the eighteenth century.":
      "Peki, Hat 1'e hoş geldin. Bu Legal's Mate, adını on sekizinci yüzyıl Fransız oyuncusu Monsieur de Légal'den alır.",
    "White opens with the king's pawn, e4.": "Beyaz şah piyonuyla açar, e4.",
    "Black answers symmetrically with e5.": "Siyah simetrik olarak e5 ile cevaplar.",
    "Knight to f3 attacks that pawn.": "At f3'e gider ve o piyona saldırır.",
    "Black defends it with d6, which is the Philidor Defence.":
      "Siyah onu d6 ile savunur; bu Philidor Savunmasıdır.",
    "White's bishop comes to c4 and eyes the weak little f7 square.":
      "Beyazın fili c4'e gelir ve zayıf küçük f7 karesine bakar.",
    "Black's bishop goes to g4 and pins the knight against the queen.":
      "Siyahın fili g4'e gider ve atı vezire bağlar.",
    "White calmly develops, knight to c3.": "Beyaz sakin sakin gelişir, at c3'e.",
    "Black plays g6. It's a slow move, and now the trap is ready.":
      "Siyah g6 oynar. Yavaş bir hamledir ve tuzak artık hazırdır.",
    "Knight takes e5! That knight was only pinned to the queen, not to the king, so it's perfectly free to move.":
      "At e5'i alır! O at yalnızca vezire bağlıydı, şaha değil, bu yüzden oynamakta tamamen özgürdür.",
    "Black can't resist and takes the queen on d1. That's the greedy capture, and it's fatal.":
      "Siyah dayanamaz ve d1'deki veziri alır. Açgözlü kapmadır ve ölümcüldür.",
    "Bishop takes f7, check!": "Fil f7'yi alır, şah!",
    "The king has only one square to go to, e7.": "Şahın gidecek tek karesi kaldı, e7.",
    "Knight to d5, and that's checkmate.": "At d5'e, ve bu mat.",
    "Two knights and one bishop have beaten the entire black army. Black's queen, rooks and the bishop on d1 are all still on the board, and none of them can help.":
      "İki at ve bir fil bütün siyah orduyu yendi. Siyahın veziri, kaleleri ve d1'deki fili hâlâ tahtadadır ve hiçbiri yardım edemez.",
    "So remember: when a queen is offered for free this early in the game, have a good look around before you take it.":
      "Unutma: oyunun bu kadar başında bir vezir bedavaya sunulursa, almadan önce etrafına iyi bak.",
    "Now over to you. Practise it until your knights know the way.":
      "Şimdi sıra sende. Atların yolu öğrenene kadar çalış.",
    "Ah, hello again. Professor Potato Pie, tea in hand. And today, we turn our attention to the Caro-Kann Defence, a splendidly resilient opening with excellent manners and a surprisingly sharp pair of elbows.":
      "Ah, yine merhaba. Professor Potato Pie, elinde çay. Bugün Caro-Kann Savunmasına bakıyoruz: olağanüstü dirençli, görgüsü yerinde ve dirsekleri şaşırtıcı derecede keskin bir açılış.",
    "It begins with e4 c6, and takes its name from Horatio Caro and Marcus Kann, two nineteenth-century players whose analytical work gave this venerable defence its identity.":
      "e4 c6 ile başlar ve adını Horatio Caro ile Marcus Kann'dan alır; on dokuzuncu yüzyılın iki oyuncusu, analitik çalışmalarıyla bu saygın savunmaya kimliğini vermiştir.",
    "The strategic premise is admirably economical. Black prepares d5, challenging White's centre at once, while keeping the light-squared bishop free rather than incarcerating it behind the pawn chain.":
      "Stratejik öncül hayranlık verecek kadar tutumludur. Siyah d5'i hazırlar, Beyazın merkezine hemen meydan okur ve açık renk fili piyon zincirinin arkasına kapatmak yerine özgür bırakır.",
    "The Caro-Kann is solid, patient and structurally sound, but do not mistake composure for passivity. Beneath its respectable exterior lies a fine collection of counterpunches, particularly when White becomes overambitious.":
      "Caro-Kann sağlam, sabırlı ve yapıca sağlıklıdır, ama sükûneti edilgenlik sanma. Saygın dışının altında güzel bir karşı darbe koleksiyonu vardır, özellikle Beyaz aşırı hırslanırsa.",
    "You'll study 10 lines from Opening Lab.":
      "Opening Lab'den 10 hat çalışacaksın.",
    "These are 10 lines from Opening Lab.":
      "Bunlar Opening Lab'den 10 hat.",
    "In Practice, I'll provide hints wherever you need them. In Test, the assistance disappears, and it is simply you, the position and your judgement.":
      "Practice içinde ihtiyaç duyduğun yerde ipucu veririm. Test içinde yardım kaybolur; kalan sensin, konum ve muhakemen.",
    "Each line concludes where the prepared book line ends. There is no continuation against the computer afterwards.":
      "Her hat, hazırlanmış kitap hattının bittiği yerde biter. Sonrasında bilgisayara karşı devam yoktur.",
    "The object is not to play aimlessly on, but to absorb the moves, comprehend the ideas and recognise the patterns when you return over the board.":
      "Amaç amaçsızca oynamaya devam etmek değil, hamleleri sindirmek, fikirleri kavramak ve tahtaya döndüğünde kalıpları tanımaktır.",
    "Right then. Tea settled, pieces ready. Let's begin.":
      "Peki. Çay yerine oturdu, taşlar hazır. Başlayalım.",
    "Right then, welcome to Line 1, the Advance Variation. White claims the centre with e4.":
      "Peki, Hat 1'e hoş geldin, İlerletme Varyantı. Beyaz merkezi e4 ile sahiplenir.",
    "We answer c6, preparing the thematic d5 advance.":
      "c6 ile cevaplarız, temalı d5 ilerleyişini hazırlarız.",
    "White establishes a broad centre with d4, and we challenge it immediately with d5.":
      "Beyaz d4 ile geniş bir merkez kurar, biz de hemen d5 ile ona meydan okuruz.",
    "White pushes on to e5, gaining space.": "Beyaz e5'e kadar iter ve alan kazanır.",
    "Before closing the pawn chain with e6, our bishop escapes to f5. That, in essence, is the Caro-Kann's first piece of good housekeeping. The bishop gets out before the door closes.":
      "Piyon zincirini e6 ile kapatmadan önce filimiz f5'e kaçar. Özünde Caro-Kann'ın ilk iyi ev düzeni budur. Kapı kapanmadan fil çıkar.",
    "Knight f3 follows, then e6. With the bishop safely developed, e6 is now entirely comfortable.":
      "At f3 gelir, sonra e6. Fil güvenle geliştiğine göre e6 artık bütünüyle rahattır.",
    "White chooses the quiet and sensible bishop e2 set-up, a system popularised by the English grandmaster Nigel Short.":
      "Beyaz, sakin ve akıllıca fil e2 düzenini seçer; İngiliz büyükustası Nigel Short'un yaygınlaştırdığı bir sistem.",
    "We strike with c5, attacking the base of White's pawn chain on d4.":
      "c5 ile vururuz, Beyazın piyon zincirinin d4'teki tabanına saldırırız.",
    "White castles, and knight c6 adds another piece to the pressure.":
      "Beyaz rok yapar ve at c6 baskıya bir taş daha ekler.",
    "White reinforces d4 with c3.": "Beyaz d4'ü c3 ile pekiştirir.",
    "We exchange pawns on d4, opening the c-file and giving our counterplay a useful avenue.":
      "d4'te piyon değiştiririz, c sütununu açarız ve karşı oyunumuza yararlı bir yol veririz.",
    "The remaining knight develops to e7, bound for f5, where it can question d4 once again.":
      "Kalan at e7'ye gelişir, f5'e gider; orada d4'ü yeniden sorgulayabilir.",
    "White plays knight c3, and our bishop applies the pin from g4.":
      "Beyaz at c3 oynar, filimiz g4'ten bağlamayı uygular.",
    "White answers with knight e1, breaking the pin.":
      "Beyaz at e1 ile cevaplar ve bağlamayı bozar.",
    "We therefore exchange White's useful bishop on e2. Recapturing with the knight keeps d4 securely defended.":
      "Bu yüzden Beyazın e2'deki yararlı filini değiştiririz. Atla geri almak d4'ü güvenle savunulmuş tutar.",
    "Our knight settles on f5, still eyeing d4.": "Atımız f5'e yerleşir, hâlâ d4'e bakar.",
    "White protects it with bishop e3, and we calmly develop the bishop to e7, ready to castle.":
      "Beyaz onu fil e3 ile korur, biz de sakin sakin fili e7'ye geliştirir, roka hazır oluruz.",
    "The result is an equal position with a coherent plan. Maintain the pressure on d4 and make purposeful use of the c-file.":
      "Sonuç, tutarlı bir planı olan eşit bir konumdur. d4 üzerindeki baskıyı sürdür ve c sütununu amaçlı kullan.",
    "No fireworks required, just sound structure, patient pressure and every piece gainfully employed.":
      "Havai fişek gerekmez; yalnızca sağlam yapı, sabırlı baskı ve her taşın işe yaraması.",
    "Over to you. Drill the line until the moves feel less like memory and more like good sense.":
      "Sıra sende. Hamleler bellekten çok sağduyu gibi hissedilene kadar hattı tekrarla.",
    "Right then, Professor Potato Pie here, tea in and, and today we're having a brief look at the London system.":
      "Peki, burada Professor Potato Pie, çay elde, ve bugün Londra sistemine kısa bir bakış atıyoruz.",
    "The opening became closely associated with the Great London Tournament in 1922, where this dependable set-up attracted wider attention.":
      "Bu açılış, 1922'deki Büyük Londra Turnuvası ile yakından ilişkilendi; bu güvenilir düzen daha geniş dikkat çekti.",
    "Right, normally begins with pawn to d4, knight to f3 and bishop to f4.":
      "Evet, normalde d4'e piyon, f3'e at ve f4'e fil ile başlar.",
    "Then comes pawn to e3, pawn to c3, knight to d2, bishop to d3 and king side castling.":
      "Sonra e3'e piyon, c3'e piyon, d2'ye at, d3'e fil ve kısa rok gelir.",
    "The precise order can change, but that familiar formation is the heart of the London system.":
      "Kesin sıra değişebilir, ama o tanıdık düzen Londra sisteminin kalbidir.",
    "It is a solid, sensible opening that has been played by club players and grandmasters alike.":
      "Kulüp oyuncularının da büyükustaların da oynadığı sağlam, akıllıca bir açılıştır.",
    "Right, enjoy getting more familiar with the London system and let's see how the pieces fit together.":
      "Peki, Londra sistemine daha yakından alışmanın keyfini çıkar, ve taşların nasıl oturduğuna bakalım.",
    "Right then, let's have a look at the first line in our London learning pack.":
      "Peki, Londra öğrenme paketimizdeki ilk hatta bir bakalım.",
    "This is the London clamp, quiet to begin with, but there is method in every move.":
      "Bu Londra kıskacıdır; başlangıçta sakindir, ama her hamlede bir yöntem vardır.",
    "We play pawn to d4 and black answers pawn to d5.":
      "Piyonu d4'e oynarız ve siyah piyonla d5 diye yanıt verir.",
    "Bishop to f4, knight to f6, pawn to e3 and black strikes with pawn to c5.":
      "Fil f4'e, at f6'ya, piyon e3'e, ve siyah piyonla c5'e vurur.",
    "We build the familiar pyramid with pawn to c3, black develops knight to c6.":
      "Tanıdık piramidi piyonla c3'te kurarız, siyah atı c6'ya geliştirir.",
    "Knight to d2 and black plays pawn to e6.": "At d2'ye, siyah da piyonu e6'ya oynar.",
    "Our other knight comes to f3, while black's bishop comes to d6.":
      "Öteki atımız f3'e gelirken siyahın fili d6'ya gelir.",
    "We tuck our bishop back to g3, keeping it useful and secure.":
      "Filimizi g3'e geri çekeriz; yararlı ve güvende kalsın.",
    "Black castles king side, we place our other bishop on d3, black plays pawn to b6 and now we plant the knight on e5, a splendid central outpost.":
      "Siyah kısa rok yapar, öteki filimizi d3'e koyarız, siyah piyonu b6'ya oynar ve şimdi atı e5'e dikeriz, görkemli bir merkez karakolu.",
    "Bishop to b7, we castle king side, black places the queen on c7 and we complete the clamp with pawn to f4.":
      "Fil b7'ye, biz kısa rok yaparız, siyah veziri c7'ye koyar ve kıskacı piyonla f4'te tamamlarız.",
    "There it is, a compact London position with the centre firmly under supervision and our pieces beginning to glance towards the king side.":
      "İşte orada: merkezin sıkı gözetim altında olduğu derli toplu bir Londra konumu, taşlarımız şah kanadına bakmaya başlıyor.",
    "Drill it until your hand knows the route and your opponent wonders when the quiet opening became an attack.":
      "Elin yolu öğrenene ve rakibin sessiz açılışın ne zaman saldırıya döndüğünü merak edene kadar tekrarla.",
    "Right then, Professor Potato Pie here, tea in hand, and today we're meeting one of chess's oldest and most elegant openings, the Italian Game.":
      "Peki, burada Professor Potato Pie, çay elde, ve bugün satrancın en eski ve en zarif açılışlarından biriyle, İtalyan Açılışı ile buluşuyoruz.",
    "Its ideas were studied by the Italian masters more than four centuries ago, and the opening still appears at every level of chess today.":
      "Fikirlerini dört yüzyıldan fazla önce İtalyan ustalar incelemişti, ve bu açılış bugün de satrancın her düzeyinde görülür.",
    "White begins with pawn to e4, and black answers pawn to e5, knight to f3, knight to c6, and then bishop to c4.":
      "Beyaz piyonla e4 ile başlar, siyah piyonla e5 diye yanıt verir, at f3, at c6, ve sonra fil c4.",
    "That bishop points towards f7, the delicate little square beside black's king.":
      "O fil f7'ye bakar, siyah şahın yanındaki nazik küçük kareye.",
    "From here, black commonly replies bishop to c5, entering the Giuoco Piano, or knight to f6, reaching the Two Knights Defence.":
      "Buradan siyah genellikle fil ile c5 diye yanıt verir, Giuoco Piano'ya girer, ya da at ile f6, İki At Savunmasına ulaşır.",
    "The Italian Game is classical, lively, and built upon natural development, central control and attacking possibilities.":
      "İtalyan Açılışı klasik ve canlıdır, doğal gelişim, merkez kontrolü ve saldırı olanakları üzerine kuruludur.",
    "Right, enjoy getting more familiar with the Italian Game, and let's see where that bishop on c4 takes us.":
      "Peki, İtalyan Açılışına daha yakından alışmanın keyfini çıkar, ve c4'teki filin bizi nereye götürdüğüne bakalım.",
    "Right then, welcome to Line 1 of our Italian Game Learning Pack.":
      "Peki, İtalyan Açılışı öğrenme paketimizin 1. hattına hoş geldin.",
    "This is the quieter Italian.": "Bu, daha sakin İtalyan.",
    "No need to set fire to the curtains when careful preparation will do nicely.":
      "Özenli bir hazırlık yetiyorsa perdeleri tutuşturmaya gerek yok.",
    "We begin with pawn to e4, and black answers pawn to e5.":
      "Piyonla e4 ile başlarız, siyah da piyonla e5 diye yanıt verir.",
    "Knight to f3, knight to c6, bishop to c4, and black develops bishop to c5.":
      "At f3'e, at c6'ya, fil c4'e, ve siyah fili c5'e geliştirir.",
    "Both bishops take up their classical posts and keep a watchful eye on the centre.":
      "İki fil de klasik mevzilerine yerleşir ve merkezi dikkatle izler.",
    "We play pawn to c3, preparing a future pawn to d4.":
      "Piyonu c3'e oynarız, ilerideki bir piyon d4 için hazırlık yaparak.",
    "Black develops knight to f6 and places pressure on e4.":
      "Siyah atı f6'ya geliştirir ve e4 üzerine baskı kurar.",
    "Pawn to d3, pawn to d6.": "Piyon d3'e, piyon d6'ya.",
    "Both sides secure the centre before making any grand declarations.":
      "İki taraf da büyük açıklamalardan önce merkezi sağlamlaştırır.",
    "We castle king side.": "Kısa rok yaparız.",
    "Black plays pawn to a6.": "Siyah piyonu a6'ya oynar.",
    "We answer pawn to a4, gaining a little queen side space and the bishop settles on a7.":
      "Piyonla a4 diye yanıt veririz, vezir kanadında biraz yer kazanırız ve fil a7'ye yerleşir.",
    "Knight to d2 and black castles king side.": "At d2'ye, siyah da kısa rok yapar.",
    "We play pawn to h3, preventing a bishop from becoming troublesome on g4, and giving our king a useful breathing square.":
      "Piyonu h3'e oynarız; bir filin g4'te sıkıntı çıkarmasını önler, şahımıza yararlı bir nefes karesi veririz.",
    "Black's knight moves to e7.": "Siyahın atı e7'ye gider.",
    "Rook to e1 reinforces the e4, and the knight continues to g6.":
      "Kale e1'e giderek e4'ü pekiştirir, at da g6'ya devam eder.",
    "There we are, a sound Italian position, with every piece preparing for useful work.":
      "İşte oradayız: sağlam bir İtalyan konumu, her taş yararlı bir işe hazırlanıyor.",
    "Keep developing, watch the centre and be ready for the d4 break when the moment is right.":
      "Geliştirmeye devam et, merkezi izle ve anı geldiğinde d4 kırılmasına hazır ol.",
    "Drill the line until the moves feel as natural as putting the kettle on.":
      "Hamleler çaydanlığı ocağa koymak kadar doğal hissedilene kadar hattı tekrarla.",
    "Right then, Professor Potato Pie here, tea properly brewed, and today we're introducing one of the great classical openings, the Queen's Gambit.":
      "Peki, burada Professor Potato Pie, çay usulünce demlenmiş, ve bugün büyük klasik açılışlardan birini tanıtıyoruz, vezir gambiti.",
    "The opening has appeared in chess writing since the late fifteenth century and generations of distinguished players have used it to contest the centre.":
      "Bu açılış on beşinci yüzyılın sonundan beri satranç yazılarında görünür ve seçkin oyuncu kuşakları merkezi çekişmek için onu kullanmıştır.",
    "White begins with pawn to d4, and black answers pawn to d5.":
      "Beyaz piyonla d4 ile başlar ve siyah piyonla d5 diye yanıtlar.",
    "Then white plays pawn to c4, challenging black's central pawn and offering the c-pawn.":
      "Sonra beyaz piyonla c4 oynar, siyahın merkez piyonuna meydan okur ve c piyonunu sunar.",
    "It is called a gambit, although white can usually recover the pawn if black accepts,":
      "Buna gambit denir, gerçi siyah kabul ederse beyaz piyonu genellikle geri alabilir,",
    "So this is less a reckless donation and more a strategic invitation, served politely but with ulterior motives.":
      "Yani bu pervasız bir bağıştan çok, nazikçe sunulmuş ama art niyetli stratejik bir davettir.",
    "From here, black may accept the pawn or decline it and maintain a solid centre.":
      "Buradan siyah piyonu kabul edebilir ya da reddedip sağlam bir merkez tutabilir.",
    "Right, enjoy getting more familiar with the Queen's Gambit and let's see what that adventurous little c-pawn can persuade black to do.":
      "Peki, vezir gambitiyle daha yakınlaşmanın tadını çıkar ve o maceracı küçük c piyonunun siyahı neye ikna edebileceğini görelim.",
    "Right then, welcome to Line 1 of our Queen's Gambit learning pack.":
      "Peki, vezir gambiti öğrenme paketimizin Hat 1'ine hoş geldin.",
    "This is proper classical chess, firm foundations, patient development and no furniture being thrown across the room.":
      "Bu gerçek klasik satrançtır: sağlam temeller, sabırlı gelişim ve odanın öbür ucuna fırlatılan mobilya yok.",
    "We begin with pawn to d4 and black answers pawn to d5.":
      "Piyonla d4 ile başlarız ve siyah piyonla d5 diye yanıt verir.",
    "Pawn to c4 challenges the centre and black replies pawn to e6.":
      "Piyon c4 merkeze meydan okur ve siyah piyonla e6 diye karşılık verir.",
    "That is the Queen's Gambit Declined. Black supports the d5 pawn rather than accepting our offer.":
      "Bu vezir gambiti reddedilmiştir. Siyah teklifimizi kabul etmek yerine d5 piyonunu destekler.",
    "Knight to c3, knight to f6, bishop to g5 creates the pin and black calmly develops bishop to e7.":
      "At c3'e, at f6'ya, fil g5'e pini kurar ve siyah fili sakin sakin e7'ye geliştirir.",
    "We play pawn to e3 and black castles kingside.":
      "Piyonu e3'e oynarız ve siyah kısa rok yapar.",
    "Knight to f3, knight to d7.": "At f3'e, at d7'ye.",
    "Rook to c1 places the rook on the c-file while black plays pawn to c6 and strengthens the central structure.":
      "Kale c1'e kaleyi c hattına koyar, siyah da piyonu c6'ya oynayıp merkez yapısını güçlendirir.",
    "Bishop to d3 and black now resolves the tension with pawn from d5 takes c4.":
      "Fil d3'e, ve siyah şimdi gerilimi d5 piyonunun c4 almasıyla çözer.",
    "Our bishop takes c4 recovering the pawn with development.":
      "Filimiz c4 alır ve piyonu gelişimle geri kazanır.",
    "Black's knight moves to d5 and occupies a strong central square.":
      "Siyahın atı d5'e gider ve güçlü bir merkez kareyi işgal eder.",
    "We exchange with bishop takes e7 and black's queen recaptures on e7.":
      "Fille e7 alarak değiştiririz ve siyahın veziri e7'de geri alır.",
    "There it is, a balanced Queen's Gambit position with sensible development and plenty of play still in the centre.":
      "İşte orada: dengeli bir vezir gambiti konumu, akıllıca gelişim ve merkezde hâlâ bol oyun.",
    "Learn the structure, understand the exchanges and let the position tell you when it is time to press forward.":
      "Yapıyı öğren, değişimleri anla ve ne zaman ileri basmanın zamanı olduğunu konuma bırak.",
    "Very civilised and quietly ambitious.": "Çok medeni ve sessizce hırslı.",
    "Right then, Professor Potato Pie here, set you at the ready and today we are meeting the French defence, what are Black's most resilient replies to the King's Pawn?":
      "Peki, burada Professor Potato Pie, seni hazırlıyorum, ve bugün Fransız Savunması ile tanışıyoruz: Şah piyonuna Siyah'ın en dirençli cevapları nelerdir?",
    "White begins with pawn to e4, we answer pawn to e6.":
      "Beyaz piyonu e4'e sürer, biz piyonla e6 diye yanıtlarız.",
    "White claims more space with pawn to d4 and we strike at once with pawn to d5.":
      "Beyaz piyonu d4 ile daha çok yer alır ve biz hemen piyonu d5 ile vururuz.",
    "The opening took its name from a correspondence match between London and Paris in 1834, when the Paris team employed the defence successfully.":
      "Açılış adını, 1834'te Londra ile Paris arasındaki bir yazışma maçından aldı; Paris takımı savunmayı başarıyla kullanmıştı.",
    "Its character is patient, but hardly passive.": "Karakteri sabırlıdır, ama pek de pasif değildir.",
    "Black builds a sturdy pawn chain, invites White to declare their intentions, then challenges the centre with moves such as pawn to c5 and when the moment is ripe, pawn to f6.":
      "Siyah sağlam bir piyon zinciri kurar, Beyaz'ı niyetini açıklamaya davet eder, sonra piyonu c5 gibi hamlelerle merkezi sorgular ve anı gelince piyonu f6'ya sürer.",
    "Our light-squared bishop may require a little diplomacy, but that is part of the opening's subtle architecture.":
      "Açık renkli filimiz biraz diplomasi isteyebilir, ama bu, açılışın ince mimarisinin bir parçasıdır.",
    "Solid, combative and rich in counterplay.": "Sağlam, mücadeleci ve karşı oyundan zengin.",
    "The French does not rush the argument, it wins it one precise question at a time.":
      "Fransız tartışmayı acele ettirmez; onu her seferinde tek kesin soruyla kazanır.",
    "So settle in, keep your eye on the pawn breaks and enjoy becoming more familiar with the French defence.":
      "O halde yerleş, piyon kırılmalarına gözünü dik ve Fransız Savunması'na daha aşina olmanın tadını çıkar.",
    "Right then, welcome to Line 1 of our French defence learning pack.": "Peki, Fransız Savunması öğrenme paketimizin 1. hattına hoş geldin.",
    "The proper title is the French defence Winawer variation, Advance positional main line, and we're drilling it from Black's side.":
      "Asıl adı Fransız Savunması Winawer varyantı, ilerletmenin konumsal ana hattıdır ve bunu Siyah'ın tarafından çalışıyoruz.",
    "White begins with pawn to e4, we answer pawn to e6, white takes the centre with pawn to d4 and we challenge it with pawn to d5.":
      "Beyaz piyonu e4'e sürer, biz piyonla e6 diye yanıtlarız, Beyaz merkezi piyonu d4 ile alır ve biz onu piyonu d5 ile sorgularız.",
    "Knight to c3, then bishop to b4, that announces the Winawer.": "At c3'e, sonra fil b4'e: bu, Winawer'i ilan eder.",
    "We pin the knight and ask white how ambitious they're feeling.": "Atı bağlarız ve Beyaz'a ne kadar hırslı hissettiklerini sorarız.",
    "White advances pawn to e5, we counter immediately with pawn to c5.": "Beyaz piyonu e5'e sürer, biz hemen piyonla c5 diye karşı koyarız.",
    "White plays pawn to a3, challenging our bishop, so bishop takes c3, check.": "Beyaz piyonu a3 oynar, filimize meydan okur, bu yüzden fil c3 alır, şah.",
    "White recaptures with the b-pawn to c3.": "Beyaz b-piyonuyla c3'e geri alır.",
    "White has gained the bishop pair and a broad centre, but accepted doubled c-pawns in return.":
      "Beyaz fil çiftini ve geniş bir merkezi kazandı, ama karşılığında çiftlenmiş c-piyonlarını kabul etti.",
    "That trade-and-balance is the very grammar of the Winawer.": "Bu değişim ve denge, Winawer'in ta kendisi olan dilbilgisidir.",
    "We develop knight to e7, white develops knight to f3 and our bishop goes to d7.": "Atı e7'ye geliştiririz, Beyaz atı f3'e geliştirir ve filimiz d7'ye gider.",
    "White plays pawn to a4, restraining queen side expansion.": "Beyaz piyonu a4 oynar, vezir kanadı genişlemesini kısıtlar.",
    "We answer queen to a5, applying pressure to c3 and helping clear the way for queen side castling.":
      "Vezirle a5 diye yanıtlarız, c3'e baskı yapar ve vezir kanadı rokuna yol açmaya yardım ederiz.",
    "Bishop to d2 and our knight develops to c6.": "Fil d2'ye ve atımız c6'ya gelişir.",
    "White places the bishop on d3, glancing rather impolitely at h7.": "Beyaz fili d3'e koyar, h7'ye oldukça kabaca bir bakış atarak.",
    "We advance pawn to c4, gaining space and sending that bishop back to e2.": "Piyonu c4'e süreriz, yer kazanır ve o fili e2'ye geri göndeririz.",
    "Now comes pawn to f6, the characteristic French lever.": "Şimdi piyon f6'ya gelir, Fransız'ın karakteristik kaldıracı.",
    "We are not merely admiring white's centre, we are asking it to provide its credentials.": "Beyaz'ın merkezine yalnızca hayran olmuyoruz; ondan kimliğini göstermesini istiyoruz.",
    "White castles king side, black castles queen side.": "Beyaz şah kanadına rokar, Siyah vezir kanadına rokar.",
    "The kings are now settled on opposite wings, the position is splendidly unbalanced and black's plan is clear.":
      "Şahlar artık karşı kanatlarda yerleşti, konum görkemli biçimde dengesiz ve Siyah'ın planı açık.",
    "Challenge the e5 pawn, open useful lines and generate queen side activity with proper purpose.": "e5 piyonunu sorgula, yararlı hatlar aç ve vezir kanadında amaçlı bir etkinlik üret.",
    "That is the positional Winawer, solid in construction, combative in intention and carrying a considerable amount of concealed electricity.":
      "Konumsal Winawer budur: kuruluşu sağlam, niyeti mücadeleci ve hatırı sayılır gizli bir elektrik taşır.",
    "Your turn, drill it until the move order feels less like memory and more like common sense.": "Sıra sende: hamle sırası bellekten çok sağduyu gibi hissedilene kadar bunu çalış.",
    "Right there my loves. Big Red here. And today we're having a proper look at the Ruy Lopez,":
      "Tam orada, sevgililerim. Big Red burada. Ve bugün Ruy Lopez'e hakkını vererek bakıyoruz,",
    "also known as the Spanish opening. There's some history in this one. It takes its name":
      "İspanyol açılışı olarak da bilinir. Bunda biraz tarih var. Adını alır",
    "from Ruy Lopez de Segura, a Spanish priest and chess writer who studied the opening in":
      "Ruy Lopez de Segura'dan, açılışı inceleyen bir İspanyol rahip ve satranç yazarından,",
    "the 16th century. White starts with pawn to e4. Black answers pawn to e5. Knight to f3":
      "16. yüzyılda. Beyaz piyonu e4'e sürer. Siyah piyonla e5 diye yanıtlar. At f3'e",
    "attacks that pawn and Black defends it with Knight to c6. Then comes Bishop to b5. And there":
      "o piyona saldırır ve Siyah atla c6 diye savunur. Sonra fil b5'e gelir. Ve işte",
    "you have it. The Ruy Lopez. The Bishop is not winning the e5 pawn immediately. It is applying":
      "karşınızda. Ruy Lopez. Fil e5 piyonunu hemen kazanmıyor. Baskı uyguluyor",
    "pressure to the Knight that guards it, giving Black a quiet but persistent problem to consider.":
      "onu koruyan ata, ve Siyah'a sessiz ama ısrarlı bir sorun bırakıyor.",
    "From this elegant little beginning grows one of the grandest opening families in chess.":
      "Bu zarif küçük başlangıçtan satrancın en görkemli açılış ailelerinden biri büyür.",
    "Some lines are calm and maneuvering, others can become lively before you've had time to settle":
      "Bazı hatlar sakin ve manevralıdır, başkaları çayını koyacak vaktin olmadan canlanabilir",
    "your tea. It is classical, subtle and full of proper strategic ideas. Old, dignified and still":
      "çayın. Klasik, ince ve gerçek stratejik fikirlerle dolu. Eski, vakur ve hâlâ",
    "bustling with possibilities. A little like London itself. So keep your eye on the centre,":
      "olasılıklarla dolu. Biraz Londra'nın kendisi gibi. Bu yüzden merkeze göz kulak ol,",
    "look after your pieces and enjoy becoming more familiar with the Ruy Lopez. Big Red will see you round.":
      "taşlarına iyi bak ve Ruy Lopez'i daha yakından tanımanın tadını çıkar. Big Red seni yine görür.",
    "Right then my loves, Big Red is back at the board and this is line 1 of our Ruy Lopez learning pack, the Morphy Defense Closed Breyer Variation.":
      "Pekâlâ sevgililerim, Big Red tahtaya döndü ve bu, Ruy Lopez öğrenme paketimizin 1. hattı, Morphy Savunması Kapalı Breyer Varyantı.",
    "We are playing the white pieces and this is a proper strategic masterpiece.":
      "Beyaz taşlarla oynuyoruz ve bu gerçek bir stratejik başyapıt.",
    "White begins with pawn to e4, Black answers pawn to e5, Nf3 attacks the pawn and Black defends it with Nc6.":
      "Beyaz piyonu e4'e sürerek başlar, Siyah piyonla e5 diye yanıtlar, Nf3 o piyona saldırır ve Siyah Nc6 ile savunur.",
    "Bb5 and the Ruy Lopez is on the board. Black plays pawn to a6, announcing the Morphy Defense":
      "Bb5 ve Ruy Lopez tahtadadır. Siyah piyonu a6 oynar, Morphy Savunması'nı ilan ederek",
    "and asking our bishop a very direct question. We retreat bishop to a4. Black develops Nf6,":
      "ve filimize çok doğrudan bir soru sorar. Fili a4'e çekeriz. Siyah Nf6 geliştirir,",
    "we castle kingside and Black develops bishop to e7. Rook to e1 reinforces our e4 pawn":
      "şah kanadına rokarız ve Siyah fili e7'ye geliştirir. Kale e1'e giderek e4 piyonumuzu pekiştirir",
    "and places the rook opposite Black's king. Black expands with pawn to b5, so our bishop settles":
      "ve kaleyi Siyah'ın şahının karşısına koyar. Siyah piyonla b5 diye genişler, böylece filimiz yerleşir",
    "on b3. Pawn to d6 gives Black's center a sturdy foundation. We play pawn to c3,":
      "b3'e. Piyon d6'ya gider ve Siyah'ın merkezine sağlam bir temel verir. Piyonu c3 oynarız,",
    "preparing the grand central advance, pawn to d4. Black castles kingside. Now pawn to h3,":
      "görkemli merkez ilerlemesini, piyonun d4'ünü hazırlayarak. Siyah şah kanadına rokar. Şimdi piyon h3'e,",
    "a useful little move that keeps a bishop or knight away from g4 and gives our king some breathing room.":
      "bir fili ya da atı g4'ten uzak tutan ve şahımıza biraz nefes alanı veren yararlı küçük bir hamle.",
    "Then comes the move that makes the Breyer unmistakable. Black retreats knight to b8.":
      "Sonra Breyer'i şaşmaz kılan hamle gelir. Siyah atı b8'e çeker.",
    "It looks as though the knight has forgotten why it came out, but not a bit of it. This is strategic":
      "At neden çıktığını unutmuş gibi görünür, ama hiç de değil. Bu stratejik",
    "recycling of the highest order. We strike with pawn to d4, establishing a magnificent center. Black":
      "geri dönüşümün en yüksek biçimidir. Piyonla d4 diye vurur, görkemli bir merkez kurarız. Siyah",
    "reroutes that knight to d7, where it supports e5 and frees the c pawn for future counterplay.":
      "o atı d7'ye yönlendirir; orada e5'i destekler ve gelecekteki karşı oyun için c piyonunu serbest bırakır.",
    "Our queenside knight develops to d2. Black's bishop goes to b7 and takes aim at e4. Bishop":
      "Vezir kanadı atımız d2'ye gelişir. Siyah'ın fili b7'ye gider ve e4'ü hedefler. Fil",
    "to c2 preserves our valuable Spanish bishop and points towards the kingside. Black places the":
      "c2'ye gider, değerli İspanyol filimizi korur ve şah kanadını gösterir. Siyah",
    "rook on e8, adding further support to the e5 pawn. Finally, our knight glides to f1. That knight":
      "kaleyi e8'e koyar, e5 piyonuna daha fazla destek ekler. Sonunda atımız f1'e kayar. O atın",
    "has a splendid itinerary. From f1 it can travel to g3, increasing the pressure on f5 and helping":
      "görkemli bir güzergâhı vardır. f1'den g3'e gidebilir, f5 üzerindeki baskıyı artırır ve yardım eder",
    "the kingside attack gather momentum. That is the closed Breyer. Patient, sophisticated and":
      "şah kanadı saldırısının ivme toplamasına. Kapalı Breyer budur. Sabırlı, incelikli ve",
    "absolutely brimming with life and energy. White owns the central space. Black has built a compact":
      "yaşam ve enerjiyle dopdolu. Beyaz merkezdeki alanı elinde tutar. Siyah derli toplu bir",
    "position and is preparing the counterstroke. Play it with conviction. Enjoy every maneuver":
      "konum kurmuştur ve karşı darbeyi hazırlar. İnançla oyna. Her manevranın tadını çıkar",
    "and remember, the quiet moves are not waiting around. They are loading the spring.":
      "ve unutma: sessiz hamleler bekleyip durmaz. Yayı kurarlar.",
    "Over to you, drill it until that knight journey from b1 to d2 to f1 feels as natural as finding":
      "Sıra sende: o atın b1'den d2'ye, oradan f1'e yolculuğu, bulmak kadar doğal hissedilene dek çalış",
    "your way around London.":
      "Londra'da yolunu.",
    "Right then, the Sicilian Defence for Black.":
      "Peki o zaman, Siyah için Sicilya savunması.",
    "White starts with 1. e4, claiming the centre.":
      "Beyaz bir nokta e4 ile başlar ve merkezi talep eder.",
    "Black replies 1... c5, striking from the side rather than copying White directly.":
      "Siyah bir nokta c5 ile karşılık verir; Beyazı doğrudan kopyalamak yerine yandan vurur.",
    "The idea is to challenge White's central ambitions, develop actively, and create counterplay from the very beginning.":
      "Fikir, Beyazın merkezdeki hırsına meydan okumak, etkin gelişmek ve en başından karşı oyun kurmaktır.",
    "A common route is 1. e4 c5 2. Nf3 e6 3. d4 cxd4 4. Nxd4 Nf6.":
      "Sık bir yol 1. e4, c5, 2. Nf3, e6, 3. d4, cxd4, 4. Nxd4, Nf6.",
    "There you are, a sharp, flexible defence with plenty of bite.":
      "İşte oradasınız: keskin, esnek ve epey ısırığı olan bir savunma.",
    "Right then, welcome to Line 1 of the Sicilian, the Najdorf.":
      "Peki, Sicilian hattı 1'e hoş geldin, Najdorf.",
    "This is one of Black's most ambitious answers to pawn to e4.":
      "Bu, Siyahın e4 piyonuna en hırslı cevaplarından biridir.",
    "White opens with pawn to e4, and Black immediately strikes with pawn to c5.":
      "Beyaz e4 piyonuyla açar ve Siyah hemen c5 piyonuyla vurur.",
    "White develops knight to f3.":
      "Beyaz atı f3'e geliştirir.",
    "Black plays pawn to d6, and White opens the centre with pawn to d4.":
      "Siyah d6 piyonunu oynar ve Beyaz d4 piyonuyla merkezi açar.",
    "Black takes on d4 with the c-pawn, White recaptures with knight takes d4.":
      "Siyah c piyonuyla d4'te alır, Beyaz at d4 alır diye geri alır.",
    "Black develops knight to f6, and White brings the other knight to c3.":
      "Siyah atı f6'ya geliştirir ve Beyaz öteki atı c3'e getirir.",
    "Now comes the famous Najdorf move, pawn to a6, a flexible little move with a great deal of venom behind it.":
      "Şimdi ünlü Najdorf hamlesi gelir, piyon a6'ya, arkasında epey zehir olan esnek küçük bir hamle.",
    "Black keeps the position adaptable and prepares to expand on the queenside.":
      "Siyah konumu uyarlanabilir tutar ve vezir kanadında genişlemeye hazırlanır.",
    "The first part of the line is pawn to e4, pawn to c5, knight to f3, pawn to d6, pawn to d4, pawn takes d4, knight takes d4, knight to f6, knight to c3, pawn to a6, bishop to e3, pawn to e5, knight to b3, bishop to e6.":
      "Hattın ilk bölümü piyon e4, piyon c5, at f3, piyon d6, piyon d4, piyon d4 alır, at d4 alır, at f6, at c3, piyon a6, fil e3, piyon e5, at b3, fil e6.",
    "Now the line continues, pawn to f3, bishop to e7, queen to d2, castle kingside, castle queenside, knight to bd7, pawn to g4, pawn to b5.":
      "Şimdi hat sürer, piyon f3, fil e7, vezir d2, kısa rok, uzun rok, at bd7, piyon g4, piyon b5.",
    "White prepares a kingside assault with pawn to f3.":
      "Beyaz f3 piyonuyla şah kanadında bir saldırı hazırlar.",
    "Black calmly develops bishop to e7, then White brings the queen to d2.":
      "Siyah sakince fili e7'ye geliştirir, sonra Beyaz veziri d2'ye getirir.",
    "Black castles kingside and White castles queenside.":
      "Siyah şah kanadına rok yapar ve Beyaz vezir kanadına rok yapar.",
    "Now the battle lines are drawn.":
      "Artık savaş hatları çizildi.",
    "Black develops knight to bd7 and White begins the famous pawn storm with pawn to g4.":
      "Siyah atı bd7'ye geliştirir ve Beyaz g4 piyonuyla ünlü piyon fırtınasını başlatır.",
    "Black answers with pawn to b5 and there it is, the Najdorf has burst into life.":
      "Siyah b5 piyonuyla karşılık verir ve işte, Najdorf canlandı.",
    "White is gathering forces on the kingside, Black is charging down the queenside, and both players are preparing something rather dangerous.":
      "Beyaz şah kanadında güç topluyor, Siyah vezir kanadından yükleniyor ve ikisi de oldukça tehlikeli bir şey hazırlıyor.",
    "Right then, follow the moves closely, keep your wits about you and enjoy this cracking Sicilian line.":
      "Peki, hamleleri yakından izle, uyanık kal ve bu harika Sicilian hattının tadını çıkar.",
  },
};
